SELECT 'moj-all-verified-judgments-review-002-chunk-185' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"c0b61865-7fb5-5630-a0d0-f9c86ccb8613","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -اتعاب محاماة -حجز حتفظي على حصص يف شركة - األصل عدم احلجز إال بعد ثبوت احلق -رد دعوى -االعتراض على احلكم -مرور املدة احملددة نظاما دون االعتراض -حكم قطعي .","document_number":"34202987","case_number":"34189358","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/1","year":"1434","subject":"عقد -اتعاب محاماة -حجز حتفظي على حصص يف شركة - األصل عدم احلجز إال بعد ثبوت احلق -رد دعوى -االعتراض على احلكم -مرور املدة احملددة نظاما دون االعتراض -حكم قطعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34202987 :‬تاريخه‪1434/5/1 :‬هـ‬\n                         ‫رقم الدعوى‪34189358 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34381270‬تاريخه‪1434/12/18 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬اتعــاب محامــاة ‪ -‬حجــز حتفظــي علــى حصــص يف شــركة ‪-‬‬\n      ‫األصــل عــدم احلجــز إال بعــد ثبــوت احلــق ‪ -‬رد دعــوى ‪ -‬االعتــراض علــى‬\n       ‫احلكــم ‪ -‬مــرور املــدة احملــددة نظامــا دون االعتــراض ‪ -‬حكــم قطعــي ‪.‬‬\n\n\n\n\n                              ‫قوله صلى اهلل عليه وسلم ( ال ضرر وال ضرار ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة علــى املدعــى عليهــا الغائبــة عــن مجلــس احلكــم‬\n      ‫يطالــب باحلجــز التحفظــي علــى حصصهــا مــن شــركة وشــركة‬\n      ‫لالســتثمار الصناعــي ‪ -‬حيــث تعاقــدت املدعــى عليهــا مــع مــوكل‬\n      ‫ا عنهــا يف جميــع‬    ‫املدعــي علــى أن يكــون محامي ـ ًا عنهــا ووكي ـ ً‬\n      ‫املنازعــات الناشــئة عــن تركــة مورثهــا فيمــا بينهــا وبــن باقــي الورثــة‬\n      ‫وقــد التزمــت املدعــى عليهــا بدفــع كامــل أتعــاب موكلــه ســواء انتهــت‬\n      ‫النزاعــات عــن طريــق الصلــح أو التحكيــم أو احلكــم القضائــي وســواء‬\n      ‫مت الصلــح عــن طريــق موكلــه أو بدونــه وقــد اســتلم موكلــه جــزء مــن‬\n      ‫األتعــاب وقدرهــا أربعــة ماليــن وخمــس مئــة ألــف ريــال ونســبة أتعابــه‬\n      ‫‪ %5‬باملائــة مــن القيمــة الفعليــة حلصــة املدعــى عليهــا مــن التركــة ‪ -‬وألن‬\n      ‫األصــل عــدم احلجــز إال بعــد ثبــوت احلــق‪ ،‬وملــا يف احلجــز مــع عــدم موجبــه‬\n\n‫‪301‬‬\n\f‫مــن اإلضــرار باحملجــوز عليــه‪ ،‬والضــرر ممنــوع لقولــه صلــى اهلل عليــه‬\n‫وســلم ـ‪( :‬ال ضــرر وال ضــرار) ‪ -‬احلكــم بــرد طلــب املدعــي ‪ -‬اعتــرض‬\n‫املدعــي وكالــة واســتعد بتقــدمي الئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n ‫احلقوقيــة الســابعة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬فلــدي أنــا ‪ ،......‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة‪ ،‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم‪ 34189358 :‬وتاريــخ‪:‬‬\n‫‪1434/04/24‬ه ـ املقيــدة باحملكمــة برقــم‪ 341011253 :‬وتاريــخ‪:‬‬\n‫‪1434/04/24‬ه ـ ففــي يــوم األربعــاء املوافــق‪1434/05/01 :‬ه ـ حضــر‪:‬‬\n‫‪ ،......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪...... :‬الوكيــل‬\n‫عــن‪ ،...... :‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجــدة‬\n‫برقــم‪...... :‬يف‪1434/3/22 :‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة‬\n‫واإلقــرار واإلنــكار والصلــح والتــازل واإلبــراء‪ ،‬وطلــب احلجــز والتنفيــذ‪.‬‬\n‫ا‪ .‬ه ـ ولــم حتضــر املدعــى عليهــا‪ ،......:‬وال مــن ميثلهــا ولــم يظهــر تبلغهــا‬\n‫قضية مقيدة‬‫ّ‬      ‫مبوعــد هــذه اجللســة‪ ،‬ثــم ادعــى األول قائــا‪ :‬لدى موكلــي‬\n‫يف احملكمــة برقــم‪ 3143889 :‬يف‪1431/5/6 :‬ه ـ محالــة للمكتــب‬\n‫القضائــي الســادس والعشــرون‪ ،‬واملتضمنــة‪ :‬تعاقــد موكلــي مــع املدعى‬\n‫ا عنهــا يف جميــع الدعــاوى واألعمــال‬      ‫عليهــا أن يكــون محاميـ ًا ووكيـ ً‬\n‫املتعلقــة بالنزاعــات الناشــئة عــن تركــة مورثهــا‪...... :‬فيمــا بينهــا وبــن‬\n‫باقــي الورثــة اآلخريــن‪ ،‬ومت توقيــع اتفاقيتــان بينهمــا‪ ،‬وقــد التزمــت‬\n‫املدعــى عليهــا بدفــع كامــل أتعــاب موكلــي ســواء انتهــت النزاعــات مــع‬\n\n                                                                                       ‫‪302‬‬\n\f      ‫الورثــة عــن طريــق الصلــح أو التحكيــم أو احلكــم القضائــي وســواء مت‬\n      ‫الصلــح عــن طريــق موكلــي أو بدونــه‪ ،‬ونســبة األتعــاب املتفــق عليهــا‬\n      ‫يف العقــد خمســة يف املئــة مــن القيمــة الفعليــة حلصــة املدعــى عليهــا مــن‬\n      ‫تركــة مورثهــا‪ ،‬وقــد أنهــت املدعــى عليهــا النزاعــات املتعلقــة بالتركــة‬\n      ‫كلهــا صلحــا مــع الورثــة مــن دون الرجــوع ملوكلــي‪ ،‬وقــد تسـلّم موكلي‬\n      ‫مبلغــا قــدره‪ :‬أربعــة ماليــن وخمــس مئــة ألــف ريــال وهــي جــزء مــن أتعــاب‬\n      ‫موكلــي‪ ،‬أطلــب إيقــاع احلجــز التحفظــي عاجــا علــى حصــص املدعــى‬\n      ‫عليهــا مــن شــركة ‪ ...‬ورقــم ســجلها التجــاري‪ ،)......( :‬وشــركة ‪......‬‬\n      ‫لالســتثمار الصناعــي ورقــم ســجلها التجــاري‪ ،)......( :‬هكــذا ادعــى‪.‬‬\n      ‫فبنــاء علــى مــا ســلف‪ ،‬وحيــث لــم يظهــر مــا يوجــب احلجــز الــذي يطلبــه‬\n      ‫املدعــي وكالــة‪ ،‬وألن األصــل عــدم احلجــز إال بعــد ثبــوت احلــق‪ ،‬وملــا‬\n      ‫يف احلجــز ـ مــع عــدم موجبــه ـ مــن اإلضــرار باحملجــوز عليــه‪ ،‬والضــرر‬\n      ‫ممنــوع لقولــه ـ صلــى اهلل عليــه وســلم ـ‪( :‬ال ضــرر وال ضــرار)‪ ،‬لذلــك‬\n      ‫فقــد رددت طلــب املدعــي‪ ،‬وبذلــك قضيــت‪ .‬وبإعــان احلكــم قــرر‬\n      ‫املدعــي وكالــة اعتراضــه واســتعد بتقــدمي الئحــة اعتراضيــة‪ ،‬فجــرى‬\n      ‫تســليمه نســخة مــن احلكــم‪ ،‬ولــه احلــق يف تقــدمي اعتراضــه خــال ثالثــن‬\n      ‫يوم ـ ًا اعتبــار ًا مــن هــذا اليــوم‪ ،‬وإذا تأخــر عــن هــذه املـ ّـدة احملــددة ولــم‬\n      ‫يقــدم الئحتــه ســقط حقــه يف االعتــراض بطلــب االســتئناف واكتســب‬\n      ‫القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                         ‫ّ‬          ‫احلكــم‬\n                                     ‫آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/05/01 :‬ه ـ‬\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n\n\n‫‪303‬‬\n\f‫رئيــس احملكمــة العامــة املســاعد بجــدة برقــم ‪ 34/1011253‬وتاريــخ‬\n‫‪1434/06/11‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪......‬‬\n‫باحملكمــة العامــة مبحافظــة جــدة املســجل برقــم ‪ 34202987‬وتاريــخ‬\n‫‪1434/05/01‬ه ـ املتضمــن دعــوى ‪ ......‬ضــد ‪ ،......‬وبدراســة الصــك‬\n‫وص ــورة ضبط ــه والئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‬\n‫واهلل املوفــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪304‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":301,"source_page_end":304,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a5e0f1ee82bfed91e69b129edb17f630232337cb26d9795ea4aa5377dced0cd4","normalized_text_hash":"733b4c14f355e2d78a571c0b862b2111c6257bd24464f20a6ac5b370e2c155ad","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p301-34202987"},{"id":"97fe4972-4180-5ff0-b106-8233a3f78954","document_type":"judgment","category":"judicial","subcategory":"general","title":"أتعاب محاماة -مطالبة بأتعاب محاماة -األصل عدم السداد - إقرار الورثة بتوقيع مورثهم على عقد االتفاق -التزام املورث دين ينتقل لتركته -الدين مقدم على قسمة التركة -بيع عقار املورث لسداد مستحقات الدائن.","document_number":"34194135","case_number":"33418167","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"أتعاب محاماة -مطالبة بأتعاب محاماة -األصل عدم السداد - إقرار الورثة بتوقيع مورثهم على عقد االتفاق -التزام املورث دين ينتقل لتركته -الدين مقدم على قسمة التركة -بيع عقار املورث لسداد مستحقات الدائن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34194135 :‬تاريخه‪1434/4/22 :‬هـ‬\n                         ‫رقم الدعوى‪33418167 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3433197‬تاريخه‪1434/10/15 :‬هـ‬\n\n\n      ‫أتعــاب محامــاة ‪ -‬مطالبــة بأتعــاب محامــاة ‪ -‬األصــل عــدم الســداد ‪-‬‬\n      ‫إقــرار الورثــة بتوقيــع مورثهــم علــى عقــد االتفــاق ‪ -‬التــزام املــورث ديــن‬\n      ‫ينتقــل لتركتــه ‪ -‬الديــن مقــدم علــى قســمة التركــة ‪ -‬بيــع عقــار‬\n                                                ‫املــورث لســداد مســتحقات الدائــن‪.‬‬\n\n\n\n\n                          ‫‪ .1‬قوله تعالى {من بعد وصية يوصى بها أو دين} ‪.‬‬\n                   ‫‪ .2‬قوله صلى اهلل عليه وسلم ( املسلمون على شروطهم ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة ضــد املدعــى عليهــم مبطالبتهــم بأتعــاب احملامــاة‬\n      ‫وقدرهــا ‪ %10‬باملائــة مــن قيمــة العقــارات ومقــدم أتعــاب قــدره خمســة‬\n      ‫آالف ريــال ‪ -‬حيــث تعاقــد مــورث املدعــى عليهــم مــع مــوكل املدعــي‬\n      ‫علــى أن يترافــع عنــه يف مطالبــة أوالده املدعــى عليهــم يف إثبــات ملكيتــه‬\n      ‫للعقــارات املســجلة باســم زوجتــه والدتهــم حيــث توفيــت زوجتــه قبــل‬\n      ‫وفاتــه والعقــارات باســمها ألنــه أجنبــي ال يســتطيع تســجيل العقــارات‬\n      ‫باســمه وأنكــره املدعــى عليهــم ومت احلكــم لــه بإثبــات ملكيتــه‬\n      ‫للعقــارات ولكونــه غيــر ســعودي فقــد حكــم ببيــع العقــارات باملــزاد‬\n      ‫العلنــي وتســليم قيمتهــا للمدعــي وتخصــم منهــا عشــرة باملائــة لصالــح‬\n\n‫‪305‬‬\n\f‫الدولــة ويكــون ملــوكل املدعــي ‪ %10‬باملائــة مــن قيمــة العقــارات لقــاء‬\n‫أتعابــه ‪ -‬أجــاب املدعــى عليهــم باملصادقــة علــى الدعــوى ماعــدا االتفــاق‬\n‫الــذي بــن مورثهــم ومــوكل املدعــي ‪ -‬صــادق املدعــى عليهــم علــى توقيــع‬\n‫والدهــم علــى العقــد ‪ -‬حضــر املدعــي أصالــة وحلــف اليمــن علــى أنــه لــم‬\n‫يســتلم ســوى عشــرة آالف مــن مقــدم األتعــاب ‪ -‬وألن منصــوص العقــد‬\n‫املبــرم بــن املدعــي وبــن مــورث املدعــى عليهــم ينــص علــى أن أتعــاب‬\n‫الطــرف األول الــذي هــو املدعــي عــن القضيــة عشــرة يف املائــة مــن قيمــة‬\n‫العقــارات ومقــدم أتعــاب خمســة عشــر ألــف ريــال ‪ -‬مبــا أن العقــد أبــرم‬\n‫مــع مورثهــم يف قضيــة مقامــة منــه ضدهــم ومــن البديهــي بــأن ينكــروا‬\n‫ويجادلــوا يف املوضــوع مــا دام أن احلكــم مت ضدهــم بإثبــات ملكيــة‬\n‫والدهــم للعقــارات املشــار إليهــا أعــاه إال أن املدعــى عليهمــا أصالــة‬\n‫ووكالــة أقــرا بــأن التوقيــع يف العقــد هــو توقيــع مورثهــم ‪ -‬وألن مــن‬\n‫أبــرم معــه العقــد قــد تــويف واألصــل هــو عــدم اســتالم املدعــي حقــه مــن‬\n‫أتعــاب القضيــة وأقــر بأنــه لــم يســتلم ســوى عشــرة آالف ريــال واملدعــى‬\n‫عليهمــا أصالــة ووكالــة ال يعلمــون شــيئا عــن ذلــك وقــد حلــف اليمــن‬\n‫الشــرعية بعــد اإلذن لــه بذلــك بأنــه لــم يســتلم مــن مقــدم األتعــاب ســوى‬\n‫عشــرة آالف ريــال ‪ -‬ولقــول النبــي صلــى اهلل عليــه وســلم « املســلمون‬\n‫علــى شــروطهم « ومــا مت االتفــاق فيــه يعتبــر مــن قبيــل الديــن والديــن‬\n‫مقــدم علــى قســمة التركــة لقولــه تعالــى ‪ « :‬مــن بعــد وصيــة يوصــى بهــا‬\n‫أو ديــن « ال ســيما وأن ملــورث املدعــى عليهــم أمــواال ومــن ذلــك العقــارات‬\n‫التــي حكــم لــه بهــا واحملكــوم ببيعهــا باملــزاد العلنــي ‪ -‬احلكــم مبــا‬\n‫يلــي‪ :‬أوال ‪ :‬إلــزام الورثــة بدفــع مبلــغ وقــدره خمســة آالف ريــال للمدعــي‬\n‫أصالــة ثاني ـ ًا ‪ :‬ثبــت بــأن للمدعــي عشــرة يف املائــة مــن قيمــة العقــارات‬\n\n\n                                                                                     ‫‪306‬‬\n\f      ‫املشــار إليهــا أعــاه تخصــم بعــد بيعهــا باملــزاد العلنــي وتســلم لــه ‪ -‬قنــع‬\n      ‫املدعــي واعتــرض املدعــى عليهــم بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n          ‫احلقوقيــة الرابعــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n      ‫فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة وبنــاء‬\n      ‫علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n      ‫املكرمــة برقــم ‪ 33418167‬يف ‪1433/6/22‬ه ـ املقيــدة يف احملكمــة‬\n      ‫برقــم ‪ 331171374‬يف ‪1433/6/22‬ه ـ ففــي يوم األحد ‪1434/4/21‬هـ‬\n      ‫الســاعة التاســعة صباحــا افتتحــت اجللســة للنظــر يف دعــوى ‪ ....‬ضــد كل‬\n      ‫مــن ‪....‬و‪......‬و‪ ....‬و‪ ....‬و‪ ....‬و‪ ....‬و‪ ....‬أوالد ‪ ....‬وفيهــا حضــر ‪....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬بالوكالــة عــن املدعــي ‪....‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل يف الغرفــة التجاريــة‬\n      ‫مبكــة برقــم ‪ 33193356‬يف ‪1433/7/26‬ه ـ واملخــول لــه يف الوكالــة‬\n      ‫حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار وطلــب اليمــن ‪ ...‬الخ وحضر‬\n      ‫حلضــوره كل مــن ‪....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪....‬و‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪....‬باألصالــة عــن‬\n      ‫نفســه وبالوكالــة عــن ‪....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بغــرب مكــة برقــم ‪ 34423432‬يف ‪1434/4/7‬ه ـ واملخــول لــه يف‬\n      ‫الوكالــة حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح ‪ ...‬الــخ‬\n      ‫وبالوكالــة عــن ‪ ....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بغــرب مكــة برقــم ‪ 33215238‬يف ‪1433/8/7‬ه ـ واملخــول لــه يف‬\n\n‫‪307‬‬\n\f‫الوكالــة حــق املرافعــة واملدافعــة والصلــح ‪ ...‬الــخ وبالوكالــة عــن ‪....‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بغــرب مكــة‬\n‫برقــم ‪ 33215203‬يف ‪1433/8/7‬ه ـ واملخــول لــه يف الوكالــة حــق‬\n‫املرافعــة واملدافعــة والصلــح ‪ ...‬الــخ وبالوكالــة عــن ‪....‬بصفتــه الوكيــل‬\n‫الشــرعي عــن ‪....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بالطائــف برقــم ‪ 11802‬يف ‪1427/3/17‬ه ـ واملخــول لــه يف الوكالــة‬\n‫حــق املرافعــة واملدافعــة والصلــح ‪ ...‬الــخ واملدعــى عليهــم أصالــة ووكالــة‬\n‫مــع ‪....‬هــم جميعــا ورثــة ‪....‬مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 33186515‬يف ‪1433/4/12‬ه ـ وبســؤال املدعــي‬\n‫وكالــة عــن دعــواه ادعــى قائــا ‪ :‬لقــد اتفــق موكلــي مــع مــورث املدعــى‬\n‫عليهــم ‪....‬املتوفــى بتاريــخ ‪1433/3/19‬ه ـ واملنحصــر ورثتــه يف أوالده‬\n‫البالغــن مــن زوجتــه املتوفــاة ‪ ....‬وهــم كل مــن ‪....‬و‪....‬و‪ ....‬و‪ ....‬و‪ ....‬و‪....‬‬\n‫و‪ ....‬وذلــك مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة‬\n‫برقــم ‪ 33186515‬يف ‪1433/4/12‬ه ـ علــى أن يقــوم بالترافــع نيابــة عنــه‬\n‫بصفتــه ميلــك مكتبــا لالستشــارات القانونيــة والشــرعية واحملامــاة‬\n‫املرخــص لــه مــن وزارة العــدل مبوجــب التصريــح رقــم ( ‪ ) ......‬وذلــك يف‬\n‫مطالبــة أوالده املدعــى عليهــم كل مــن ‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪....‬يف إثبــات‬\n‫ملكيتــه للعقــارات املســجلة باســم زوجتــه املتوفــاة قبلــه ‪ ....‬وهــي ثالثــة‬\n‫عقــارات األول ‪ :‬العمــارة الواقعــة مبكــة حــي ‪ ....‬رقــم القطعــة (‪)......‬‬\n‫مبوجــب الصــك الصــادر مــن كتابــة العــدل األولــى مبكــة املكرمــة‬\n‫برقــم ‪/2315‬ب وتاريــخ ‪1402/8/22‬ه ـ املكونــة مــن بــدروم وأربعــة‬\n‫أدوار والثانــي‪ :‬قطعــة األرض رقــم القطعــة (‪ )111‬اململوكــة بالصــك‬\n‫الصادر من كتابة العدل األولى مبكة املكرمة برقم ‪/2/5/1371‬ب‬\n\n\n                                                                                        ‫‪308‬‬\n\f      ‫وتاريــخ ‪1403/6/27‬ه ـ والثالــث ‪ :‬الــدار اململوكــة بالصــك الصــادر مــن‬\n      ‫كتابــة عــدل الطائــف برقــم ‪ 4/687‬وتاريــخ ‪1475/9/3‬ه ـ كونــه ال‬\n      ‫يحــق لــه التملــك نظام ـ ًا ألنــه غيــر ســعودي اجلنســية فقــد قــام بتســجيل‬\n      ‫جميــع تلــك العقــارات باســم زوجتــه ‪ ....‬ســعودية اجلنســية مبوجب الســجل‬\n      ‫املدنــي رقــم ‪ ....‬والتــي توفيــت قبلــه وانحصــر ورثتهــا يف زوجهــا ‪....‬‬\n      ‫وأوالدهــا منــه املدعــى عليهــم حيــث أنكــر املدعــى عليهــم ملكيــة‬\n      ‫والدهــم للعقــارات املشــار إليهــا وإمنــا هــي ملــك لوالدتهــم وقــد نظــرت‬\n      ‫القضيــة لديكــم وانتهــت بالصــك الصــادر مــن هــذه احملكمــة برقــم‬\n      ‫‪ 32338413‬يف ‪1432/11/27‬ه ـ املصــدق مــن محكمــة االســتئناف‬\n      ‫مبكــة املكرمــة بالقــرار رقــم ‪ 33279727‬يف ‪1433/6/3‬ه ـ وذلــك‬\n      ‫بإثبــات ملكيــة العقــارات لوالدهــم ‪ ....‬ولكونــه غيــر ســعودي فقــد‬\n      ‫حكــم بــأن تبــاع باملــزاد العلنــي وتســلم قيمتهــا للمدعــي ويخصــم منهــا‬\n      ‫عشــرة يف املائــة لصالــح الدولــة وذلــك بحيــث يكــون ملوكلــي لقــاء‬\n      ‫أتعابــه عشــرة يف املائــة مــن قيمــة العقــارات املــراد إثبــات ملكيتهــا‬\n      ‫باإلضافــة إلــى خمســة عشــر ألــف ريــال مقــدم أتعــاب لــم يســتلم منهــا‬\n      ‫ســوى عشــرة آالف ريــال ومبــا أنــه قــد تــويف وانحصــر ورثتــه يف أوالده‬\n      ‫املدعــى عليهــم لــذا فــإن موكلــي يطلــب إثبــات حقــه يف العقــارات‬\n      ‫املذكــورة بنســبة قدرهــا عشــرة يف املائــة مــن قيمتهــا والباقــي مــن مقــدم‬\n      ‫األتعــاب وقــدره خمســة آالف ريــال هــذه دعــواي وبعــرض الدعــوى علــى‬\n      ‫املدعــى عليهمــا أصالــة ووكالــة أجابــا قائلــن ‪ :‬مــا ذكــره املدعــي‬\n      ‫وكالــة مــن وفــاة مورثنــا ‪....‬بتاريــخ ‪1433/3/19‬ه ـ وانحصــار ورثتــه يف‬\n      ‫أوالده البالغــن مــن زوجتــه املتوفــاة ‪ ....‬وهــم كل مــن‬\n      ‫‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪ ....‬وذلــك مبوجــب صــك حصــر الورثــة الصــادر‬\n\n\n‫‪309‬‬\n\f‫مــن هــذه احملكمــة برقــم ‪ 33186515‬يف ‪1433/4/12‬ه ـ ووجود دعوى‬\n‫ســابقا بيننــا وبينــه حــول ملكيــة العقــارات املشــار إليهــا آنفــا وانتهائهــا‬\n‫بالصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 32338413‬يف‬\n‫‪1432/11/27‬ه ـ املصــدق مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫بالقــرار رقــم ‪ 33279727‬يف ‪1433/6/3‬ه ـ بإثبــات ملكيــة والدنــا‬\n‫للعقــارات فهــذا كلــه صحيــح وأمــا مــن ناحيــة وجــود عقــد بــن مورثنــا‬\n‫وبــن املدعــي أصالــة حــول أتعــاب القضيــة املنظــورة لديكــم فهــذا ال‬\n‫نعلــم عنــه إال أننــا قــد اطلعنــا علــى عقــد األتعــاب فوجدنــا مــا يلــي ‪ :‬أوال‬\n‫‪ :‬ال ينــص العقــد صراحــة ضمــن بنــوده علــى إلــزام ورثــة املتعاقــد الوالــد‬\n‫‪ .... /‬بالتســديد أو دفــع األتعــاب بعــد وفاتــه للمكتــب املذكــور أو مــن‬\n‫ميثلــه ثانيــا ‪ :‬نــص البنــد الرابــع ( الفقــرة الثانيــة ) مــن العقــد علــى أن ‪( :‬‬\n‫باقــي األتعــاب بعــد االنتهــاء مــن القضيــة ) ولــم ينــص العقــد علــى أن‬\n‫باقــي األتعــاب بعــد إصــدار احلكــم وحيــث إن وفــاة املتعاقــد حدثــت‬\n‫بتاريــخ ‪1433/3/19‬ه ـ أي قبــل أن يكتســب احلكــم صفتــه القطعيــة‬\n‫بتاريــخ ‪1433/6/3‬ه ـ واالنتهــاء مــن القضيــة أي أن إرثــه قــد عــاد لورثتــه‬\n‫بتاريــخ وفاتــه أي قبــل االنتهــاء مــن القضيــة واعتبــرت وكالــة الوكيــل‬\n‫الغيــة بوفــاة املــوكل لــذا فإنــه ال عالقــة للورثــة إطالقــا بهــذا العقــد ومــا‬\n‫تضمنــه مــن بنــود واتفاقــات بعــد وفــاة املتعاقــد ثالثــا ‪ :‬إن العقــد أبــرم مــع‬\n‫مورثنــا ‪....‬ومكتــب ‪....‬ومت إدخــال توقيــع أحــد ورثــة املتعاقــد ضمــن‬\n‫العقــد وهــي األخــت ‪ ....‬دون ذكــر عالقتهــا أو اإلشــارة ألســباب توقيعهــا‬\n‫ضمــن نصــوص العقــد فــإذا كان ســبب توقيعهــا على العقد هو الشــهادة‬\n‫أو إقرارهــا وموافقتهــا وتأييدهــا علــى العقــد املبــرم ومــا تضمنــه مــن‬\n‫بنــود بــن الطرفــن فــإن مطالبــة املدعــي تــؤول ألختنــا ‪ ....‬مــن نصيبهــا‬\n\n\n                                                                                           ‫‪310‬‬\n\f      ‫الشــرعي وليــس مــن نصيــب باقــي الورثــة هكــذا أجابــا وقــررا وبعــرض‬\n      ‫ذلــك علــى املدعــي وكالــة قــال ‪ :‬أوال ‪ :‬إن مــا مت االتفــاق بــن موكلــي‬\n      ‫وبــن مــورث املدعــى عليهــم يعتبــر مــا أجنــزه ديــن يف ذمتــه يلــزم ورثتــه‬\n      ‫مــن بعــده ومــن املعلــوم أن الديــون تقضــى قبــل تصفيــة التركــة لقولــه‬\n      ‫تعالــى‪ « :‬مــن بعــد وصيــة يوصــي بهــا أو ديــن « ثانيــا ‪ :‬إن أخــت املدعــى‬\n      ‫عليهــم ‪ ....‬مقــرة بالعقــد وهــي شــاهدة عليــه وقــد قامــت بتوكيــل‬\n      ‫موكلــي بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة يف الطائــف‬\n      ‫برقــم ‪ 36581‬يف ‪1433/6/30‬ه ـ هكــذا قــرر هــذا وقــد جــرى مــن‬\n      ‫االطــاع علــى مــا يلــي ‪ :‬أوال ‪ :‬صــك حصــر الورثــة الصــادر مــن هــذه‬\n      ‫احملكمــة برقــم ‪ 33186515‬يف ‪1433/4/12‬ه ـ فوجــد يتضمــن ثبــوت‬\n      ‫وفــاة ‪....‬بتاريــخ ‪1433/3/19‬ه ـ وانحصــار ورثتــه يف أوالده البالغــن مــن‬\n      ‫زوجتــه املتوفــاة ‪....‬وهــم كل مــن ‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪....‬ال وارث لــه‬\n      ‫ســواهم ثانيــا ‪ :‬الصــادر مــن هــذه احملكمــة برقــم ‪ 32338413‬يف‬\n      ‫‪1432/11/27‬ه ـ املصــدق مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫بالقــرار رقــم ‪ 33279727‬يف ‪1433/6/3‬ه ـ فوجــد يتضمــن دعــوى‬\n      ‫مقامــة مــن ‪....‬ضــد أوالده كل مــن ‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪ ....‬أوالد ‪......‬‬\n      ‫يف ملكيــة عقــارات مســجلة باســم زوجتــه ‪ ......‬وقــد تضمــن الصــك مــا‬\n      ‫يلــي ‪ :‬أ‪ -‬أن الــذي قــام بالترافــع يف القضيــة نيابــة عــن املدعــي مــن بدايــة‬\n      ‫القضيــة وحتــى انتهائهــا هــو املدعــي ‪ - ......‬أن ‪ ......‬مقــرة بدعــوى املدعي‬\n      ‫وأن العقــارات ملــك لوالدهــا وقــد أشــير فيــه إلــى وكالــة ‪ ......‬للمدعــي‬\n      ‫‪ ......‬ج ‪ -‬صــدر احلكــم لصالــح املدعــي ‪ ......‬وقــد تــويف بعــد احلكــم‬\n      ‫وقبــل اكتســابه القطعيــة وقــد أشــير إلــى ذلــك يف صــك احلكــم ثالثــا ‪:‬‬\n      ‫عقــد األتعــاب املبــرم بــن احملامــي ‪ ...... /‬وبــن ‪ ......‬فوجــد يتضمــن‬\n\n\n‫‪311‬‬\n\f‫االتفــاق بــن بــن احملامــي ‪ ...... /‬وبــن ‪ ......‬علــى أن يقــوم الطــرف األول‬\n‫بتولــي القضيــة اخلاصــة بإثبــات ملكيــة الطــرف الثانــي للعقــارات التــي‬\n‫باســم زوجتــه املتوفــاة ‪ ......‬وقــد نــص يف البنــد الرابــع منــه علــى أن أتعــاب‬\n‫الطــرف األول عــن هــذه القضيــة عشــرة يف املائــة مــن قيمــة العقــارات‬\n‫املــراد إثبــات ملكيتهــا علــى النحــو اآلتــي ‪ :‬أ‪ -‬مقــدم أتعــاب ‪ :‬خمســة‬\n‫عشــر ألــف ريــال ب ‪ -‬باقــي األتعــاب ‪ :‬بعــد االنتهــاء مــن القضيــة ومذيــل‬\n‫بتوقيــع الطرفــن كل مــن ‪ ......‬و‪ ......‬وبســؤال املدعــى عليهمــا أصالــة‬\n‫ووكالــة عــن توقيــع والدهمــا يف العقــد وصحتــه فقــاال ‪ :‬إن هــذا هــو‬\n‫توقيــع والدنــا وال ننكــره هكــذا قــررا وقــد جــرى إرفــاق صــور ممــا‬\n‫أشــير إليــه يف املعاملــة وقــد حضــر يف هــذه اجللســة املدعــي أصالــة ‪......‬‬\n‫ســعودي اجلنســية مبوجب الســجل املدني رقم ‪ ......‬وبســؤاله عما اســتلمه‬\n‫مــن مقــدم األتعــاب فقــال ‪ :‬إن مقــدم األتعــاب خمســة عشــر ألــف ريــال لــم‬\n‫أســتلم منهــا ســوى عشــرة آالف ريــال هكــذا قــرر وبعــرض ذلــك علــى‬\n‫املدعــى عليهمــا أصالــة ووكالــة فقــاال ‪ :‬ال نعلــم عــن ذلــك شــيئا وبطلــب‬\n‫اليمــن مــن املدعــي علــى ذلــك اســتعد بذلــك ثــم أذنــت لــه فحلــف قائــا ‪:‬‬\n‫« واهلل العظيــم الــذي ال إلــه إال هــو إننــي لــم أســتلم مــن مقــدم األتعــاب يف‬\n‫العقــد املبــرم بينــي وبــن ‪ ......‬بخصــوص ملكيتــه للعقــارات إال عشــرة‬\n‫آالف ريــال واهلل العظيــم واهلل العظيــم « هكــذا حلــف فجــرى ســؤال‬\n‫الطرفــن هــل لديكمــا مــا تريــدان إضافتــه ؟ فقــاال ‪ :‬ليــس لدينــا ســوى‬\n‫مــا قدمنــاه ونطلــب الفصــل يف القضيــة هكــذا قــررا فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وبعد دراســة القضيــة وتأملها وبعد االطالع‬\n‫علــى لفــات املعاملــة ومبــا أن املدعــي يطالــب بإثبــات حقــه يف العقــارات‬\n‫اململوكــة ملورثهــم لقــاء ترافعــه عنــه بنســبة قدرهــا عشــرة يف املائــة مــن‬\n\n\n                                                                                         ‫‪312‬‬\n\f      ‫قيمتهــا وباقــي مقــدم األتعــاب خمســة آالف ريــال وألن منصــوص العقــد‬\n      ‫املبــرم بــن املدعــي وبــن مــورث املدعــى عليهــم ‪ ......‬ينــص علــى أن أتعــاب‬\n      ‫الطــرف األول الــذي هــو املدعــي عــن القضيــة عشــرة يف املائــة مــن قيمــة‬\n      ‫العقــارات ومقــدم أتعــاب خمســة عشــر ألــف ريــال ومبــا أن العقــد أبــرم‬\n      ‫مــع مورثهــم يف قضيــة مقامــة منــه ضدهــم ومــن البديهــي بــأن ينكــروا‬\n      ‫ويجادلــوا يف املوضــوع مــا دام أن احلكــم مت ضدهــم بإثبــات ملكيــة‬\n      ‫والدهــم للعقــارات املشــار إليهــا أعــاه إال أن املدعــى عليهمــا أصالــة‬\n      ‫ووكالــة أقــرا بــأن التوقيــع يف العقــد هــو توقيــع مورثهــم وألن مــن أبــرم‬\n      ‫معــه العقــد قــد تــويف واألصــل هــو عــدم اســتالم املدعــي حقــه مــن أتعــاب‬\n      ‫القضيــة وأقــر بأنــه لــم يســتلم ســوى عشــرة آالف ريــال واملدعــى عليهمــا‬\n      ‫أصالــة ووكالــة ال يعلمــون شــيئا عــن ذلــك وقــد حلــف اليمــن الشــرعية‬\n      ‫بعــد اإلذن لــه بذلــك بأنــه لــم يســتلم مــن مقــدم األتعــاب ســوى عشــرة‬\n      ‫آالف ريــال وألن العقــد شــريعة املتعاقديــن وقــد قــال النبــي صلــى اهلل‬\n      ‫عليــه وســلم « املســلمون علــى شــروطهم « ومــا مت االتفــاق فيــه يعتبــر مــن‬\n      ‫قبيــل الديــن والديــن مقــدم علــى قســمة التركــة لقولــه تعالــى ‪ « :‬مــن‬\n      ‫بعــد وصيــة يوصــي بهــا أو ديــن « ال ســيما وأن ملــورث املدعــى عليهــم‬\n      ‫أمــواال ومــن ذلــك العقــارات التــي حكــم لــه بهــا واحملكــوم ببيعهــا‬\n      ‫باملــزاد العلنــي لذلــك كلــه فقــد قــررت مــا يلــي ‪ :‬أوال ‪ :‬إلــزام ورثــة ‪......‬‬\n      ‫بدفــع مبلــغ وقــدره خمســة آالف ريــال للمدعــي أصالــة ثانيــا ‪ :‬ثبــت لــدي‬\n      ‫بــأن للمدعــي عشــرة يف املائــة مــن قيمــة العقــارات املشــار إليهــا أعــاه‬\n      ‫تخصــم بعــد بيعهــا باملــزاد العلنــي وتســلم لــه ومبــا تقــدم حكمــت‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــي القناعــة بــه واملدعــى‬\n      ‫عليهمــا أصالــة ووكالــة عــدم القناعــة وطلبــا االســتئناف بالئحــة‬\n\n\n‫‪313‬‬\n\f‫اعتراضيــة فجــرى إفهامهمــا بــأن عليهمــا التقــدم للمحكمــة يــوم‬\n‫الثالثــاء ‪1434/4/30‬ه ـ الســتالم نســخة مــن صــك احلكــم لتقــدمي‬\n‫اعتراضهمــا عليــه خــال ثالثــن يومــا مــن التاريــخ املذكــور وإذا لــم‬\n‫يتقدمــا بذلــك خــال املــدة املذكــورة فسيســقط حقهمــا بطلــب‬\n‫االســتئناف وسيكتســب احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى‬\n ‫اهلل على نبينا محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/4/21‬هـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد ‪ :‬ففــي يــوم األربعــاء ‪1434/9/9‬ه ـ افتتحــت‬\n‫اجللســة وكان قــد جــرى بعــث املعاملــة حملكمــة االســتئناف مبكــة‬\n‫املكرمــة ثــم عــادت إلينــا بخطــاب فضيلــة رئيــس محكمــة االســتئناف‬\n‫مبكة املكرمة املكلف برقم ‪ 331171374‬يف ‪1434/8/2‬هـ وبرفقه‬\n‫قــرار الدائــرة احلقوقيــة الرابعــة برقــم ‪ 34280286‬يف ‪1434/7/26‬ه ـ‬\n‫املتضمــن بعــد املقدمــة مــا نصــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــرر باألكثريــة إعــادة املعاملــة لفضيلــة‬\n‫حاكمهــا ملالحظــة أن فضيلــة ناضــر القضيــة قــد حكــم بإلــزام ورثــة‬\n‫املتوفــى ‪ ......‬بدفــع مبلــغ خمســة آالف ريــال للمدعــي أصالــة وحكمــه‬\n‫هــذا محــل نظــر حيــث لــم يفصــل فضيلتــه حكمــه ويبــن بــأن هــذا‬\n‫املبلــغ مــن التركــة والبــد مــن ذلــك‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬قاضــي اســتئناف ‪ ......‬توقيعــه‬\n‫ختمــه الشــخصي قاضــي اســتئناف ‪ ......‬توقيعــه ختمــه الشــخصي رئيــس‬\n‫الدائــرة ‪ ......‬موافــق علــى احلكــم توقيعــه ختمــه الشــخصي أ‪.‬ه ـ وعليــه‬\n‫أجيــب أصحــاب الفضيلــة وفقنــي اهلل وإياهــم للعلــم النافــع والعمــل‬\n‫الصالــح بــأن املبلــغ مــا دام أنــه يف ذمــة مــورث املدعــى عليهــم فيكــون‬\n‫مــن تركتــه وبعــد اإلجابــة لــم يظهــر لــي ســوى مــا أجريتــه وحكمــت بــه‬\n\n\n                                                                                   ‫‪314‬‬\n\f      ‫وقــررت إعــادة املعاملــة حملكمــة االســتئناف إلكمــال الزمهــا‪ ،‬وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                  ‫يف ‪1434/9/9‬ه ـ‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪ ....../‬القاضــي باحملكمــة العامــة مكــة املكرمــة واملســجل‬\n      ‫بعدد‪34194135‬وتاريــخ ‪1434/4/22‬ه ـ املتضمــن دعــوى ‪ ......‬ضــد ورثة‬\n      ‫‪ ......‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد األجــراء‬\n      ‫األخيــر املبنــي علــى قــرار الدائــرة رقــم ‪34280286‬يف ‪1434/7/26‬ه ـ‬\n                    ‫‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪315‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":305,"source_page_end":315,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e7827ecaec2578015e1cfbc080102275b71af4f7e07bddb029765603126fa3b6","normalized_text_hash":"fc3223514574cd45a8b84fcb7734f7bad258d3937f87c7a64230d5183530d8b3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p305-34194135"},{"id":"9e52cb8e-b4cd-54c6-a3d1-95a2fdad1266","document_type":"judgment","category":"judicial","subcategory":"general","title":"أجرة عمل -توجيه اليمن على املدعى عليه -حلف اليمن النافية للدعوى -احلكم برد الدعوى.","document_number":"34305617","case_number":"34217704","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/25","year":"1434","subject":"أجرة عمل -توجيه اليمن على املدعى عليه -حلف اليمن النافية للدعوى -احلكم برد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34305617:‬تاريخه‪1434/8/25:‬هـ‬\n                  ‫رقم الدعوى‪34217704:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34382792‬تاريخه‪1434/12/19 :‬هـ‬\n\n\n‫أجــرة عمــل ‪ -‬توجيــه اليمــن علــى املدعــى عليــه ‪ -‬حلــف اليمــن النافية‬\n                                          ‫للدعــوى ‪ -‬احلكــم بــرد الدعوى‪.‬‬\n\n\n\n\n      ‫‪ .1‬قوله صلى اهلل عليه وسلم (ولكن اليمني على املدعى عليه) ‪.‬‬\n         ‫‪ .2‬املادة ‪ 55‬من نظام املرافعات الشرعية والئحتها التنفيذية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه مت‬\n‫االتفــاق مــع املدعــى عليــه علــى أن يعمــل لديــه بوظيفــة معقــب إلجنــاز‬\n‫أعمالــه مــن تســديد فواتيــر الكهربــاء والهواتــف وعمل مســيرات رواتب‬\n‫للعمــال ودفــع رواتبهــم ودفــع اإليجــارات وحتصيــل اإليصــاالت ودفــع‬\n‫أقســاط شــركة ‪ ...‬ووكيــل شــرعي عــن العمالــة املوجــودة لديــه مببلــغ‬\n‫شــهري قــدره ألــف وخمســمائة ريــال وقــد عمــل املدعــي لديــه ملــدة ســت‬\n‫ســنوات وطــول هــذه املــدة لــم يســتلم منــه الرواتــب الشــهرية وقدرهــا مائــة‬\n‫وثمانيــة آالف ريــال ويطلــب إلــزام املدعــى عليــه بدفــع الرواتــب املتأخــرة‬\n‫املشــار إليهــا ‪ -‬لــم يحضــر املدعــى عليــه مــع تبلغــه نظامـ ًا فجــرى الســير‬\n‫يف الدعــوى غيابيـ ًا بنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية ‪-‬‬\n‫ليــس للمدعــي بينــة علــى دعــواه ويطلــب ميــن املدعــى عليــه علــى نفيهــا‬\n\n                                                                                      ‫‪316‬‬\n\f      ‫ورفعــت اجللســة لتبليــغ املدعــى عليــه بتوجــه اليمــن عليــه وأنــه إذا تخلــف‬\n      ‫ال وســوف يقضــى عليــه بالنكــول‬    ‫بغيــر عــذر تقبلــه احملكمــة عـ ّـد نــاك ً‬\n      ‫بنــاء علــى املــادة ‪ 4/55‬مــن نظــام املرافعــات الشــرعية ‪ -‬حضــر املدعــى‬\n      ‫عليــه يف اجللســة التاليــة وأجــاب باملصادقــة علــى التعاقــد مــع املدعــى‬\n      ‫عليــه بــأن يعمــل معقــب لــه وأنــه اســتلم حقوقــه كاملــة وأنكــر تضمــن‬\n      ‫االتفــاق صــرف راتــب شــهري للمدعــي ‪ -‬حلــف املدعــى عليــه اليمــن‬\n      ‫النافيــة بالتعاقــد مــع املدعــي علــى صــرف راتــب شــهري لــه وأن ليــس‬\n      ‫بذمتــه املبلــغ املدعــى بــه ‪ -‬وإلنــكار املدعــى عليــه ملــا جــاء يف الدعــوى‬\n      ‫ولطلــب املدعــي ميــن املدعــى عليــه ولقولــه صلــى اهلل عليــه وســلم‪:‬‬\n      ‫(ولكــن اليمــن علــى املدعــى عليــه ) ولبــذل املدعــى عليــه اليمــن علــى‬\n      ‫نفــي دعــوى املدعــي ملــا تقــدم صــدر احلكــم بــرد دعــوى املدعــي ‪ -‬قنــع‬\n      ‫املدعــى عليــه باحلكــم واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم‬\n      ‫مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة االســتئناف مبنطقــة مكــة‬\n                                                                             ‫املكرمــة‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪......‬القاضــي يف احملكمــة العامــة‬\n      ‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة القائــم بعمــل رئيــس‬\n      ‫احملكمــة العامــة بينبــع برقــم ‪ 34217704‬وتاريــخ ‪ 1434/05/11‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 341158046‬وتاريــخ ‪ 1434/05/11‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1434/07/01‬ه ـ افتتحــت اجللســة وفيهــا حضر ‪......‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي ‪......‬وادعــى علــى الغائــب عــن‬\n      ‫ا يف دعــواه إنــه يف شــهر جمــادى األول‬ ‫مجلــس احلكــم الشــرعي ‪......‬قائـ ً‬\n\n‫‪317‬‬\n\f‫مــن عام‪1428‬ه ـ مت االتفــاق بينــي وبــن املدعــى عليــه علــى أن أعمــل لديه‬\n‫بوظيفــة ‪......‬إلجنــاز أعمالــه مــن تســديد فواتيــر الكهربــاء والهواتــف‬\n‫وعمــل مســيرات رواتــب للعمــال ودفع رواتبهم ودفــع اإليجارات وحتصيل‬\n‫اإليصــاالت ودفــع أقســاط شــركة ‪ ...‬ووكيــل شــرعي عــن العمالــة‬\n‫املوجــودة لديــه مببلــغ شــهري قــدره(‪ )1,500‬ألــف وخمســمائة ريــال وقــد‬\n‫عملــت لديــه ملــدة ســتة ســنوات وطــول هــذه املــدة لــم اســتلم منــه الرواتــب‬\n‫الشــهرية وقدرهــا(‪ )108,000‬مائــة وثمانيــة آالف ريــال أطلــب إلــزام‬\n‫املدعــى عليــه بدفــع الرواتــب املتأخــرة وقدرهــا(‪ )108,000‬مائــة وثمانيــة‬\n‫آالف ريــال هكــذا ادعــى ؛ وقــد ســبق طلــب املدعــى عليــه املذكــور‬\n‫ملقابلــة خصمــه شــرع ًا وتبلــغ باملواعيــد نظاميـ ًا ولــم يحضــر كمــا يتضــح‬\n‫مــن مرفقــات املعاملــة وهــي‪ )1(:‬ورقة التبليــغ األولى وفيها حتديد املوعد‬\n‫املــؤرخ يف يــوم الســبت املوافق‪1434/05/25‬ه ـ الســاعة احلاديــة عشــرة‬\n‫وذلــك عــن طريــق محضــر اخلصــوم باحملكمــة واســتلمها رجــل األمــن‬\n‫يف الشــركة ‪)2( ......‬وقــد ســبق الكتابــة لرئيــس محضــري اخلصــوم‬\n‫باحملكمــة باخلطــاب ذي الرقــم‪ 341271299‬وتاريخ‪1434/05/26‬ه ـ‬\n‫لتكليــف املدعــى عليــه باحلضــور للمحكمــة هــذا اليــوم وقــد وردنــا‬\n‫خطابهــم ذي الرقــم‪ 341271299‬وتاريخ‪1434/07/01‬ه ـ وبرفقــه‬\n‫قــرار محضــر اخلصــوم ‪......‬املتضمن(إشــارة خلطــاب املشــرف اإلداري‬\n‫رقــم ‪ ......‬وتاريخ‪1434/05/26‬ه ـ بشــأن إبــاغ املدعــو ‪......‬بأنــه مت‬\n‫الذهــاب إلــى مقــر عمــل املدعــى عليــه بتاريخ‪1434/06/24‬ه ـ وأفــادوا‬\n‫بأنــه غيــر متواجــد اآلن ومت االتصــال عليــه ولــم يجيــب أكثــر مــن مــرة‬\n‫ويف أوقــات مختلفــة ومت الذهــاب مــرة أخــرى بتاريخ‪1434/06/28‬ه ـ‬\n‫وســألت موظــف األمــن عــن املدعــى عليــه وأفــاد بأنــه متواجــد ورفضــوا‬\n\n\n                                                                                       ‫‪318‬‬\n\f      ‫دخولــي إلــى الشــركة لتبليــغ املدعــى عليــه شــخصي ًا ومت االتصــال‬\n      ‫عليــه ولــم يجيــب حــرر احملضــر بتاريخ‪1434/07/01‬هـ)ا‪.‬ه ـ وملــا ســبق‬\n      ‫واســتناد ًا علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية‬\n      ‫ونصهــا‪ (:‬إذا غــاب املدعــى عليــه عــن اجللســة األولــى فيؤجــل النظــر يف‬\n      ‫القضيــة إلــى جلســة الحقــة يبلــغ بهــا املدعــى عليــه ‪ ،‬فــإن غــاب عــن هــذه‬\n      ‫اجللســة أو غــاب عــن جلســة أخــرى دون عــذر تقبلــه احملكمــة فتحكــم‬\n      ‫احملكمــة يف القضيــة ويعــد حكمهــا يف حــق املدعــى عليــه غيابيـ ًا مــا لم‬\n      ‫يكــن غيابــه بعــد قفــل بــاب املرافعــة يف القضيــة فيعــد احلكــم حضوريـ ًا‬\n      ‫) ا‪.‬ه ـ ‪،‬لــذا فقــد قــررت الســير يف نظــر الدعــوى وطلبــت مــن املدعــي‬\n      ‫البينــة التــي تشــهد بصحــة دعــواه فأجــاب بقولــه ليــس لــدي بينــة هكــذا‬\n      ‫أجــاب فأفهمتــه أن لــه ميــن خصمــه علــى نفــي دعــواه فقــال أطلــب ميينــه‬\n      ‫ـاء علــى املــادة ‪ 4/55‬مــن نظــام املرافعــات الشــرعية والئحتهــا‬     ‫لــذا وبنـ ً‬\n      ‫التنفيذيــة ونصهــا (إذا توجهــت اليمــن علــى املدعــى عليــه بعــد ســماع‬\n      ‫الدعــوى فيبلــغ بذلــك حســب إجــراءات التبليــغ ‪ ،‬ويشــعر بوجــوب‬\n      ‫حضــوره ألداء اليمــن وأنــه إذا تخلــف بغيــر عــذر تقبلــه احملكمــة عـ ّـد‬\n      ‫ال وســوف يقضــى عليــه بالنكــول) لــذا فســيتم إشــعار املدعــى‬           ‫نــاك ً‬\n      ‫عليــه بوجــوب حضــوره يف اجللســة القادمــة ألداء اليمــن وأنــه إذا تخلــف‬\n      ‫ال وســوف يقضــى عليــه بالنكــول‬       ‫بغيــر عــذر تقبلــه احملكمــة عـ ّـد نــاك ً‬\n      ‫ويف جلســة أخــرى لــدي أنــا ‪......‬القاضــي يف احملكمــة العامــة بينبــع‬\n      ‫والقائــم بعمــل املكتــب القضائــي اخلامــس عليــه ففــي يــوم اإلثنــن‬\n      ‫املوافــق‪ 1434/08/22‬ه ـ افتحــت اجللســة وفيهــا حضــر املدعــي وحضــر‬\n      ‫حلضــوره املدعــى عليــه ‪......‬ســعودي بالهويــة الوطنيــة رقــم ‪......‬وجــرى‬\n      ‫عــرض الدعــوى علــى املدعــي فصــادق عليهــا ثــم جــرى ســؤال املدعــى‬\n\n\n‫‪319‬‬\n\f‫عليــه عــن الدعــوى فأجــاب ‪ :‬مــا ذكــره املدعــي مــن انــه عمــل معــي يف‬\n‫التعقيــب فصحيــح إال ان ذلــك كان عــن طريــق املكتــب الــذي ميلكــه‬\n‫واســمه مكتــب ‪......‬وقــد ســلمته كامــل حقوقــه امــا مــا يدعيــه مــن‬\n‫راتــب شــهري فغيــر صحيــح ولــم أتعاقــد معــه علــى ذلــك ولســت مســتعد ًا‬\n‫أن أدفــع لــه مــا ادعــى بــه هكــذا أجــاب املدعــى عليــه وبعــرض جوابــه‬\n‫علــى املدعــي قــال ‪ :‬مــا ذكــره املدعــى عليــه غيــر صحيــح والصحيــح مــا‬\n‫ذكرتــه فســالته عــن البينــه علــى دعــواه فقــال ‪ :‬ليــس لــدي بينــه واطلــب‬\n‫ميــن املدعــى عليــه علــى نفــي دعــواي هكــذا قــال وبعــرض ذلــك علــى‬\n‫املدعــى عليــه قــال ‪ :‬إنــي مســتعد ببــذل اليمــن هكــذا قــال فأفهمتــه‬\n‫بخطــورة اليمــن وعظيــم شــانها فقــال‪ :‬انــي احلــف علــى حــق فأذنــت‬\n‫لــه أن يحلــف فحلــف قائ ـاً‪ :‬واهلل العظيــم واهلل العظيــم واهلل العظيــم‬\n‫إنــي لــم أتعاقــد مــع املدعــي هــذا احلاضــر علــى أن يعمــل معــي براتــب‬\n‫‪ 1500‬ريــال شــهري ًا وليــس يف ذمتــي مبلــغ ‪ 108000‬ريــال للمدعــي واهلل‬\n‫العظيــم هكــذا حلــف املدعــى عليــه فبنــاء عليــه وبعــد ســماع الدعــوى‬\n‫واالجابــة واالطــاع علــى اوراق املعاملــة والنــكار املدعــى عليــه ملــا‬\n‫جــاء يف الدعــوى ولطلــب املدعــي ميــن املدعــى عليــه ولقولــه صلــى اهلل‬\n‫عليــه وســلم‪( :‬ولكــن اليمــن علــى املدعــى عليــه ) ولبــذل املدعــى عليــه‬\n‫اليمــن علــى نفــي دعــوى املدعــي لذلــك كلــه فقــد رددت دعــوى املدعــي‬\n‫وأخليــت ســبيل املدعــى عليــه منهــا وبذلــك حكمــت وبعــرض احلكــم‬\n‫علــى املدعــي قــرر اعتراضــه عليــه وأفهــم باملراجعــة يــوم اإلثنــن املوافــق‬\n‫‪1434/8/29‬ه ـ الســتالم نســخة احلكــم لتقــدمي اعتراضــه عليــه ويف‬\n‫حــال مضــت مــدة ثالثــن يومـ ًا ولــم يتقــدم باعتراضــه ولــم يــأت الســتالم‬\n‫نســخة احلكــم فإنــه يســقط حقــه يف طلــب االســتئناف ويكتســب‬\n\n\n                                                                                     ‫‪320‬‬\n\f      ‫احلكــم القطعيــة وبعرضــه علــى املدعــى عليــه قــرر قناعتــه وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف ‪ 1434/08/22‬ه ـ‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى منــا‬\n      ‫االطــاع نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشيخ ‪......‬القاضي باحملكمة العامة بينبع واملسجل بعدد ‪34305617‬‬\n      ‫وتاريــخ ‪ 1434/8/25‬ه ـ املتضمــن دعــوى ‪ ......‬ضــد ‪......‬واحملكــوم فيــه‬\n      ‫مبــادون باطنــه وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم مــع مالحظــة التنبيــه املرفــق وصلــى اهلل‬\n                                     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪321‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":316,"source_page_end":321,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"805994ba41090f469368d597760c0e0403cba16377075ee5e9db31edebdfd3cb","normalized_text_hash":"ef90b6657e1a6cb67ba3eb90831b96163bfd2d97692dedf38d396a7882798d0e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p316-34305617"},{"id":"aac7a6d3-4c63-5333-953d-dcb674b16dd1","document_type":"judgment","category":"judicial","subcategory":"general","title":"استقدام عمالة -سداد قيمة مادفعه املدعى الستقدام املدعى عليها -مترجم لكون املدعى عليها اجنبيه -عدم الرغبه يف العمل لإلصابة بالسكري -األجير اخلاص يضمن بالتعدي أو التفريط -مقاصة قضائية -الزام املدعى عليها بسداد ماغرمه املدعى","document_number":"34291127","case_number":"34289348","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/8","year":"1434","subject":"استقدام عمالة -سداد قيمة مادفعه املدعى الستقدام املدعى عليها -مترجم لكون املدعى عليها اجنبيه -عدم الرغبه يف العمل لإلصابة بالسكري -األجير اخلاص يضمن بالتعدي أو التفريط -مقاصة قضائية -الزام املدعى عليها بسداد ماغرمه املدعى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34291127 :‬تاريخه‪1434/8/8 :‬هـ‬\n                  ‫رقم الدعوى‪34289348 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34315707‬تاريخه‪1434/9/9 :‬هـ‬\n\n\n‫اســتقدام عمالــة ‪ -‬ســداد قيمــة مادفعــه املدعــى الســتقدام املدعــى‬\n‫عليهــا ‪ -‬مترجــم لكــون املدعــى عليهــا اجنبيــه ‪ -‬عــدم الرغبــه يف العمــل‬\n‫لإلصابــة بالســكري ‪ -‬األجيــر اخلــاص يضمــن بالتعــدي أو التفريــط‬\n‫‪ -‬مقاصــة قضائيــة ‪ -‬الــزام املدعــى عليهــا بســداد ماغرمــه املدعــى‬\n                                                               ‫الســتقدامها ‪.‬‬\n\n\n\n                            ‫األجير اخلاص يضمن بالتعدي أو التفريط‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليهــا انــه اســتقدمها للعمــل لديــه كعاملــة‬\n‫منزليــة ملــده ســنتني بالتكلفــة املذكــورة يف دعــواه وأنهــا عملــت لديــه‬\n‫مــدة ســتة أشــهر وعشــرة أيــام وســلمها رواتــب أربعــة أشــهر ثــم قامــت‬\n‫بالهــرب مــن منزلــه وعثــر عليهــا بعــد ذلــك مركــز شــؤون اخلــدم‪ ،‬ولــذا‬\n‫طلــب احلكــم عليهــا بالرجــوع إلــى العمــل لديــه لباقــي مــدة العقــد أو أن‬\n‫تدفــع لــه مــا غرمــه لقــاء اســتقدامه لهــا‪ -‬أقــرت املدعــى عليهــا بواســطة‬\n‫املترجــم مبــا جــاء يف الدعــوى ودفعــت بأنهــا ال ترغب بالرجــوع إلى العمل‬\n‫لديــه لكونهــا مريضــة بالســكري وآالم يف العظــام فــا تســتطيع العمل‬\n‫كمــا أنهــا ال تســتطيع دفــع مبلــغ االســتقدام للمدعــي لعــدم وجــود مــال‬\n\n                                                                                    ‫‪330‬‬\n\f      ‫لديهــا‪ -‬طلبــت احملكمــة مــن املدعــى عليهــا تقريــر ًا طبيـ ًا يثبــت عجزهــا‬\n      ‫عــن العمــل فقــررت أنــه ليــس لديهــا مــا يثبــت ذلــك‪ -‬أفهمــت احملكمــة‬\n      ‫املدعــي بــأن مــا طلبــه مــن إلــزام املدعــى عليهــا بإكمــال العمــل لديــه‬\n      ‫باقــي مــدة العقــد ال يتوافــق مــع األصــول الشــرعية وال ميكــن إنفــاذه‬\n      ‫وهــي ممتنعــة فعــدل عــن طلبــه وحصــره يف دفــع املدعــى عليهــا لــه مــا‬\n      ‫غرمــه لقــاء اســتقدامها‪ -‬املدعــى عليهــا مبنزلــة األجيــر اخلــاص الــذي‬\n      ‫عليــه الضمــان بالتفريــط أو التعــدي وامتناعهــا عــن العمــل وهروبهــا دون‬\n      ‫ســبب وجيــه تعــد وتفريــط فيلزمهــا ضمــان مــا غرمــه املدعــي‪ -‬قضــت‬\n      ‫احملكمــة بإلــزام املدعــى عليهــا أن تدفــع للمدعــي مــا غرمــه بســبب‬\n      ‫اســتقدامها بعــد إجــراء مقاصــة مــع باقــي رواتبهــا لديــه‪ -‬قنــع املدعــي‬\n      ‫باحلكــم وعارضــت عليــه املدعــى عليهــا‪ -‬قــررت محكمــة االســتئناف‬\n                                                ‫باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 34289348‬وتاريــخ ‪ 1434/06/24‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341521831‬وتاريــخ ‪ 1434/06/24‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافــق‪ 1434/07/16‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 30‬‬\n      ‫وفيهــا حضــر ‪ ........‬ســعودي اجلنســية احلامــل لبطاقــة الهويــة الوطنيــة‬\n      ‫رقــم ‪ ........‬وادعــى علــى احلاضــرة معــه ‪ ........‬ســريالنكية اجلنســية‬\n      ‫مبوجــب اإلقامــة اجلــواز رقــم ‪ ........‬قائــا يف دعــواه عليهــا ان هــذه‬\n      ‫احلاضــرة معــي مت اســتقدامها مــن مكتــب ‪ ...‬بالريــاض للعمــل عنــدي‬\n\n‫‪331‬‬\n\f‫عاملــه منزليــه ملــده ســنتني بــدأت مــن تاريــخ حضورهــا للمملكــة بتاريــخ‬\n‫‪1433/10/29‬ه ـ وبراتــب شــهري قــدره ثمامنائــة ريــال وكلفنــي رســوم‬\n‫اســتقدامها مبلــغ خمســة عشــر الــف ريــال اضافــه الــى مبلــغ الفــي ريــال‬\n‫رســوم تأشــيره واملجمــوع ســبعه عشــر الــف ريــال وقــد عملــت عنــدي مــدة‬\n‫ســتة اشــهر وعشــرة ايــام وقــد اعطيتهــا رواتــب اربعــه اشــهر فقــط ثــم‬\n‫انهــا قامــت بالهــروب مــن منزلــي وبعــد ان بلغــت عنهــا بفتــرة اتصــل علــي‬\n‫مركــز شــؤون اخلــدم واخبرونــي انهــا لديهــم واطلــب احلكــم عليهــا‬\n‫يف هــذه الدعــوى بالرجــوع الــى العمــل عنــدي واكمــال مــده العقــد‬\n‫الســنتني او تدفــع لــي مــا غرمتــه لقــاء اســتقدامي لهــا وهــو مبلــغ ســبعه‬\n‫عشــر الــف ريــال هــذه دعــواي وابــرز املدعــي عقــد اتفــاق بينــه وبــن‬\n‫مكتــب ‪ ...‬لالســتقدام صــادر مــن املكتــب املذكــور برقــم ‪ 46674‬يف‬\n‫‪1433/9/26‬ه ـ ومبطالعتــه وجدتــه يتضمــن ان يقــوم املكتــب املذكــور‬\n‫بالتوســط باســتقدام خادمــه واحــده مــن ســيرالنكا مقابــل مبلــغ خمســة‬\n‫عشــر الــف ريــال وعليــه تواقيــع للمذكوريــن وختــم باســم املكتــب‬\n‫املذكــور كمــا ابــرز ســند قبــض صــادر مــن املكتــب املذكــور برقــم‬\n‫‪ 42954‬يف ‪1433/9/26‬ه ـ باســتالم مبلــغ خمســة عشــر الــف ريــال مــن‬\n‫املدعــي مقابــل اســتقدام عاملــه منزليــه مــن ســيرالنكا كمــا ابــرز‬\n‫تذكــرة مراجعــه تأشــيرات صــادره مــن مكتــب العمــل وقــد تضمــن‬\n‫املوافقــة علــى طلــب املدعــي اســتقدام عاملــه منزليــه مــن ســيرالنكا‬\n‫هــذا وبعــرض ذلــك علــى املدعــى عليهــا فأجابــت علــى لســان مترجــم‬\n‫احملكمــة ‪ ........‬بقولهــا مــا ذكــره املدعــي يف دعــواه صحيــح اال اننــي‬\n‫ال ارغــب بالرجــوع الــى منزلــه حيــث اننــي مريضــه وزاد علــي مــرض‬\n‫الســكري واعانــي مــن آالم يف عظامــي وال اســتطيع العمــل كمــا اننــي‬\n\n\n                                                                                    ‫‪332‬‬\n\f      ‫ال اســتطيع دفــع مبلــغ االســتقدام للمدعــي لعــدم وجــود مــال عنــدي‬\n      ‫هــذا وبعــرض ذلــك علــى املدعــي فقــال نعــم املدعــى عليهــا مريضــه‬\n      ‫بالســكري وقمــت بعالجهــا يف مســتوصف ‪...‬واعطوهــا ا لعــاج الــازم‬\n      ‫وهــذا املــرض ال مينــع مــن العمــل هــذا فســالت املدعــى عليهــا هــل لديهــا‬\n      ‫تقريــر طبــي علــى انهــا ال تســتطيع العمــل فقالــت ال يوجــد عنــدي ذلــك‬\n      ‫هــذا فعرضــت علــى الطرفــن مــن ان يقــوم املدعــي بنقــل كفالــه املدعــى‬\n      ‫عليهــا الــى شــخص اخــر للعمــل عنــده فقــال املدعــي ال مانــع لــدي مــن‬\n      ‫ذلــك امــا املدعــى عليهــا فقالــت ال ارغــب بنقــل كفالتــي الــى شــخص‬\n      ‫اخــر وارغــب بتســفيري لبــادي ثــم ابــرز املدعــي جــواز ســفر املدعــى‬\n      ‫عليهــا رقــم ‪ ........‬وتاريــخ ‪2012/7/4‬م وباالطــاع علــى التأشــيرة‬\n      ‫املرفقــة بهــذا اجلــواز تبــن ان رقمهــا ‪ ........‬وتاريخهــا ‪1433/10/18‬ه ـ‬\n      ‫واســم املدعــى عليهــا ‪ ........‬لغــرض العمــل لــدى ‪..... .....‬أه ـ هــذا فجــرى‬\n      ‫افهــام املدعــى بــان مــا طلبــه مــن الــزام املدعــى عليهــا بإكمــال العمــل‬\n      ‫لديــه مــدة العقــد الســنتني ال يتوافــق مــع االصــول الشــرعية وال ميكــن‬\n      ‫انفــاذه وهــي ممتنعــه ورافضــه فقــال املدعــي اقــرر اذا عدولــي عــن طلبــي‬\n      ‫هــذا واطلــب ان تدفــع لــي املدعــى عليهــا مــا غرمتــه لقــاء اســتقدامي لهــا‬\n      ‫مــن مــال وقــدره ســبعة عشــر الــف ريــال وال مانــع لــدي مــن خصــم باقــي‬\n      ‫رواتبهــا التــي لهــا عنــدي مــن املبلــغ املدعــى بــه هــذا فطلبــت مــن املدعــي‬\n      ‫ابــراز التقريــر الطبــي الــذي عملــه للمدعــى عليهــا فابــرز تقريــرا طبيــا‬\n      ‫صــادرا مــن مســتوصف ‪...‬برقــم ‪ 1125‬يف ‪1434/7/2‬ه ـ وقــد تضمــن ان‬\n      ‫املدعــى عليهــا تعانــي مــن التهــاب يف املســالك البوليــة وارتفــاع بالســكر‬\n      ‫بنســبه ‪530‬مجــم ‪.‬أه ـ فنظــرا ملــا تقــدم مــن الدعــوى واإلجابــة هــذا‬\n      ‫وحيــث ان مــا ذكرتــه املدعــى عليهــا مــن ســبب امتناعهــا عــن العمــل‬\n\n\n‫‪333‬‬\n\f‫غيــر مقنــع حيــث ان مــرض الســكري ال مينــع مــن العمــل خصوصــا‬\n‫ان املدعــى عليهــا ليســت كبيــره فهــي تبلــغ مــن العمــر ثمانيــة وثالثــن‬\n‫عامــا حيــث ان تاريــخ ميالدهــا ‪1976/10/20‬م حســبما جــاء يف جــواز‬\n‫ســفرها ولــم تســتقدم ويتــم التعاقــد معهــا اال مــن اجــل ان ينتفــع املدعــى‬\n‫بخدمتهــا وعملهــا وهــي مبنزلــه االجيــر اخلــاص الــذي عليــه الضمــان‬\n‫بالتفريــط او التعــدي وهنــا املدعــى عليهــا تعــدت وفرطــت بهروبهــا ثــم‬\n‫برفضهــا العمــل واخلــت بعقــد العمــل بــدون ســبب وجيــه وفوتــت علــى‬\n‫املدعــى حقــه يف االنتفــاع بخدمتهــا بباقــي مــدة العقــد واالجــازة عقــد‬\n‫الزم كمــا انهــا احلقــت باملدعــي ضــررا ماديــا بإضاعــة مــا دفعــه مــن‬\n‫مــال نظيــر اســتقدامها للعمــل لديــه فيلزمهــا ضمــان مــا غرمــه ودفعــه‬\n‫املدعــي هــذا وحيــث ان مــا دفعــه املدعــي مبلــغ ســبعة عشــر الــف ريــال‬\n‫وباقــي رواتــب املدعــى عليهــا عنــد املدعــي الــف وثمامنائــة وســبعه وســتون‬\n‫ريــال والفــرق بعــد املقاصــة خمســة عشــر الــف ومائــه وثالثــة وثالثــون‬\n‫ريــاال فقــد حكمــت علــى املدعــى عليهــا ان تدفــع للمدعــى خمســة عشــر‬\n‫الــف ومائــه وثالثــة وثالثــن ريــاال هــذا وبعــرض احلكــم علــى املدعــى‬\n‫عليهــا بواســطه مترجــم احملكمــة ‪ ........‬فقــررت عــدم القناعــة باحلكــم‬\n‫وطلبــت االســتئناف فأجيبــت لطلبهــا كمــا قــررت بقولهــا اننــي ال ارغــب‬\n‫يف اســتالم نســخه مــن قــرار احلكــم لالعتــراض عليــه وامنــا اطلــب تدويــن‬\n‫اعتراضــي يف ضبــط القضيــة وهــو انــه ليــس لــي قــدره يف دفــع املبلــغ‬\n‫احملكــوم بــه علــي حيــث ال مــال عنــدي هــذا هــو اعتراضــي وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪ 1434/07/30‬ه ـ‬\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34315707‬وتاريــخ‬\n                                                             ‫‪1434/9/9‬هـ‬\n                                                                                    ‫‪334‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":330,"source_page_end":334,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"657e7e30f6d5b2a454d0ed9d28313120e98b644ce59aa7571b71a35913450c70","normalized_text_hash":"a160eab6da4930a53dca1cbf69454f96ff43d2383d06deb193e4938ec1d71efa","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p330-34291127"},{"id":"e6075bb2-e08a-5b7c-8ed4-3d64db79ea86","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد اجرة على عمل -جتديد إقامة عامل -مطالبة بفسخ عقد اجرة وإعادة أجرة أعمال التعقيب لعدم إجناز جزء العمل -اإلجارة عقد الزم ال ينفسخ بإرادة طرف واحد -اقرار املدعى عليه بفسخ العقد وارجاع املبالغ التي ميكن استعادتها -احلكم برد املبالغ التي ميكن استعادتها واملقر بها ورد الدعوى يف غير ذلك .","document_number":"34368555","case_number":"34501872","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة بقعاء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/24","year":"1434","subject":"عقد اجرة على عمل -جتديد إقامة عامل -مطالبة بفسخ عقد اجرة وإعادة أجرة أعمال التعقيب لعدم إجناز جزء العمل -اإلجارة عقد الزم ال ينفسخ بإرادة طرف واحد -اقرار املدعى عليه بفسخ العقد وارجاع املبالغ التي ميكن استعادتها -احلكم برد املبالغ التي ميكن استعادتها واملقر بها ورد الدعوى يف غير ذلك .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34368555 :‬تاريخه‪1434/11/24 :‬هـ‬\n                          ‫رقم الدعوى‪34501872 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34373422‬تاريخه‪1434/11/27 :‬هـ‬\n\n\n       ‫عقــد اجــرة علــى عمــل‪ -‬جتديــد إقامــة عامــل ‪ -‬مطالبــة بفســخ عقــد‬\n       ‫اجــرة وإعــادة أجــرة أعمــال التعقيــب لعــدم إجنــاز جــزء العمــل‪ -‬اإلجــارة‬\n       ‫عقــد الزم ال ينفســخ بــإرادة طــرف واحــد‪ -‬اقــرار املدعــى عليــه بفســخ‬\n       ‫العقــد وارجــاع املبالــغ التــي ميكــن اســتعادتها ‪ -‬احلكــم بــرد املبالــغ التــي‬\n                        ‫ميكــن اســتعادتها واملقــر بهــا ورد الدعــوى يف غيــر ذلــك ‪.‬‬\n\n\n\n\n                  ‫‪ -1‬اإلجارة عقد الزم من الطرفني‪ .‬كشاف القناع (‪.)3/262‬‬\n       ‫‪ -2‬جــاء يف كشــاف القنــاع (‪« :)263/3‬وإن فســخها املســتأجر مــن غيــر‬\n                                                       ‫عيــب لــم تنفســخ اإلجــارة»‪.‬‬\n       ‫‪ -3‬جــاء يف املغنــي (‪« :)23/8‬أنــه عقــد ‪-‬أي اإلجــارة‪ -‬ال يجــوز فســخه‬\n                                                                         ‫لغيــر عــذر»‪.‬‬\n       ‫‪ -4‬جــاء يف بدايــة املجتهــد (‪« :)229/2‬ال ينفســخ ‪ -‬أي عقــد اإلجــارة ‪-‬‬\n                                    ‫إال مبــا تنفســخ بــه العقــود الالزمــة ‪..‬إلــخ»‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي بأنــه دفــع للمدعــى عليــه مبلغــا مالي ـ ًا مقابــل أعمــال‬\n       ‫تعقيــب علــى جتديــد إقامــة عامــل لديــه إال أن املدعــى عليــه لــم يجــدد‬\n       ‫اإلقامــة املذكــورة‪ ،‬ولــذا طلــب احلكــم علــى املدعــى عليــه بإرجــاع‬\n\n‫‪335‬‬\n\f‫كامــل املبلــغ الــذي دفعــه لــه‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى‬\n‫ودفــع بأنــه بــدأ يف العمــل املتفــق عليــه فقــام بســداد رســوم مكتــب‬\n‫العمــل ثــم طلــب منــه املدعــي العــدول عــن التجديــد فلــم يتمكــن مــن‬\n‫اســترجاع الرســوم املدفوعــة وأنــه مســتعد بإكمــال جتديــد إقامــة‬\n‫العامــل املذكــور إذا أكمــل املدعــي مــا بقــي عليــه مــن تكاليــف‬\n‫التجديــد وإذا لــم يرغــب املدعــي بذلــك فــا مانــع لديــه مــن إعــادة باقــي‬\n‫املبلــغ لــه ليكمــل إجــراءات التجديــد بنفســه‪ -‬اإلجــارة عقــد الزم مــن‬\n‫الطرفــن ال ينفســخ إال مبــا تنفســخ بــه العقــود الالزمــة واملدعــى عليــه‬\n‫وافــق علــى فســخ العقــد علــى باقــي العمــل‪ -‬قضــت احملكمــة بإلــزام‬\n‫املدعــى عليــه بــأن يدفــع للمدعــي املبلــغ الــذي يقابــل العمــل الــذي لــم‬\n‫ينجــز كمــا قضــت بــرد دعــوى املدعــي يف مطالبتــه باملبلــغ الــذي يقابــل‬\n‫العمــل املنجــز مــن املدعــى عليــه‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض‬\n‫عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد يف يــوم‬\n‫اخلميــس املوافــق ‪1434/11/20‬ه ـ لــدي أنــا ‪ ........‬رئيــس احملكمــة‬\n‫العامــة مبحافظــة بقعــاء افتتحــت اجللســة يف الســاعة العاشــرة والنصــف‬\n‫صباحــا للنظــر يف الدعــوى املقدمــة مــن ‪ ........‬ضــد ‪ ...‬واملقيــدة بهــذه‬\n‫احملكمــة برقــم ‪ 342544637‬يف ‪1434/11/9‬ه ـ واحملالــة لــي برقــم‬\n‫‪ 34501872‬يف ‪1434/11/9‬ه ـ وقــد حضــر يف هــذه اجللســة ‪........‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وادعــى علــى‬\n‫احلاضــر معــه يف هــذه اجللســة ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n\n                                                                                    ‫‪336‬‬\n\f      ‫املدنــي رقــم ‪ ........‬قائــا يف حتريــر دعــواه لقــد دفعــت للمدعــى عليــه‬\n      ‫بتاريــخ ‪1434/5/19‬ه ـ بصفتــه مالــك مكتــب مجموعــة ‪ ...‬مبلغــا قــدره‬\n      ‫ثالثــة آالف ومائــة ريــال وذلــك لتجديــد إقامــة العامــل اخلــاص بــي وهــو‪...‬‬\n      ‫ورقــم إقامتــه ‪ .......‬ومهنتــه عامــل تربيــة مواشــي ولــم يتــم جتديــد اإلقامــة‬\n      ‫حتــى اآلن أطلــب احلكــم علــى املدعــى عليــه بإرجــاع كامــل املبلــغ الــذي‬\n      ‫دفعتــه لــه وقــدره ثالثــة آالف ومائــة ريــال هــذه دعــواي وبســؤال املدعــى‬\n      ‫عليــه عــن دعــوى املدعــي أجــاب قائــا مــا ذكــره املدعــي يف دعــواه مــن‬\n      ‫اســتالمي للمبلــغ املذكــور يف دعــواه فهــذا صحيــح علمــا بــأن ألفــن‬\n      ‫وخمســمائة ريــال مــن إجمالــي املبلــغ املذكــور يف دعــوى املدعــي خــاص‬\n      ‫لرســوم مكتــب العمــل وقمــت بســدادها واملتبقــي وقــدره ســتمائة ريــال‬\n      ‫رســوم للجــوازات وقمــت بســدادها واملبلــغ املدفــوع للجــوازات وقــدره‬\n      ‫ســتمائة ريــال أســتطيع إرجاعــه للمدعــي وأمــا رســوم مكتــب العمــل‬\n      ‫وقدرهــا ألفــان وخمســمائة ريــال فــا ميكــن إرجاعهــا حســب نظــام‬\n      ‫مكتــب العمــل علمــا بأننــي مســتعد بإكمــال طلــب املدعــي وهــو‬\n      ‫جتديــد إقامــة العامــل املذكــور يف دعــواه إذا دفــع مــا بقــي عليــه مــن‬\n      ‫تكاليــف جتديــد إقامــة العامــل وقدرهــا مائــة ريــال وتســديد الغرامــات‬\n      ‫إن كان عليــه غرامــات تأخيــر هكــذا أجــاب املدعــى عليــه وعنــد‬\n      ‫وصــول القضيــة لهــذا احلــد رفعــت اجللســة النتهــاء وقتهــا وطلبــت مــن‬\n      ‫املدعــى عليــه إحضــار الســجل التجــاري اخلــاص مبكتــب مجموعــة ‪...‬‬\n      ‫ويف جلســة أخــرى وفيهــا حضــر املدعــي واملدعــى عليــه وقــد أبــرز املدعــى‬\n      ‫عليــه الســجل التجــاري رقــم ‪ .......‬يف ‪1414/6/28‬ه ـ واملتضمــن أن ‪........‬‬\n      ‫مالــك مجموعــة ‪ ...‬وقــد جــرى منــي عــرض الصلــح علــى الطرفــن فلــم‬\n      ‫يســتجيبا لــه فســألت الطرفــن هــل بينكمــا عقــد مكتــوب فأجابــا‬\n\n\n‫‪337‬‬\n\f‫بالنفــي ثــم ســألت املدعــي عمــا ذكــره املدعــى عليــه يف اجللســة الســابقة‬\n‫فأجــاب مــا ذكــره املدعــى عليــه يف جوابــه صحيــح جملــة وتفصيــا‬\n‫هكــذا أجــاب املدعــي ثــم ســألت املدعــى عليــه عــن املبلــغ الــذي‬\n‫دفــع ملكتــب العمــل وقــدره ألفــان وخمســمائة ريــال فقــال إنــه متعلــق‬\n‫بالســجل املدنــي للمدعــي وبإمــكان املدعــي إكمــال جتديــد إقامــة‬\n‫العامــل وســألته ملــاذا لــم يتــم التجديــد للعامــل فقــال إن املدعــي راجعنــا‬\n‫باملكتــب وطلــب جتديــد رخصــة العامــل املذكــور ودفعنــا تكاليــف‬\n‫اإلصــدار للجــوازات وملكتــب العمــل ثــم عــاد إلينــا بعــد خمــس دقائــق‬\n‫وقــال إننــي عدلــت عــن التجديــد وال أرغــب فيــه ثــم ســألت املدعــي عــن‬\n‫ذلــك فقــال مــا ذكــره املدعــى عليــه مــن أننــي راجعــت املكتــب لطلــب‬\n‫جتديــد رخصــة إقامــة العامــل ثــم رجوعــي لهــم مــرة أخــرى وطلبــي منهــم‬\n‫العــدول عــن التجديــد فهــذا صحيــح هكــذا أجاب املدعي فبنــاء على ما‬\n‫تقــدم مــن الدعــوى واإلجابــة ونظــرا ألن املدعــى عليــه ال يســتطيع إرجــاع‬\n‫املبلــغ الــذي دفــع ملكتــب العمــل نظــرا ألن املبلــغ املدفــوع ملكتــب العمــل‬\n‫وقــدره ألفــان وخمســمائة ريــال مســجل باســم املدعــي ومتعلــق بســجله‬\n‫املدنــي وبإمــكان املدعــي إكمــال إجــراءات جتديــد الرخصــة مــن قبلــه‬\n‫وألن االتفــاق الــذي حصــل بــن الطرفــن يعتبــر إجــارة فاملدعــى عليــه‬\n‫وهــو مالــك مكتــب مجموعــة ‪ ...‬يعتبــر أجيــر مشــترك وألن فســخ العقــد‬\n‫مت مــن قبــل املدعــي واإلجــارة عقــد الزم مــن الطرفــن انظــر كشــاف‬\n‫القنــاع ‪ 262/3‬كمــا جــاء يف كشــاف القنــاع ‪ 263/3‬مــا نصــه (وإن‬\n‫فســخها املســتأجر مــن غيــر عيــب لــم تنفســخ اإلجــارة) وجــاء يف املغنــي‬\n‫‪ 23/8‬مــا نصــه (أنــه عقــد ‪-‬أي اإلجــارة‪ -‬ال يجــوز فســخه لغيــر عــذر)‬\n‫وجــاء يف بدايــة املجتهــد ونهايــة املقتصــد مــا نصــه ‪( 229/2‬ال ينفســخ ‪-‬‬\n\n\n                                                                                      ‫‪338‬‬\n\f      ‫أي عقــد اإلجــارة ‪ -‬إال مبــا تنفســخ بــه العقــود الالزمــة مــن وجــود العيــب‬\n      ‫بهــا أو ذهــاب محــل اســتيفاء املنفعــة ) وألن املدعــى عليــه لــم يظهــر‬\n      ‫منــه عيــب أو خلــل يف إجنــاز العمــل فهــو ال ميانــع مــن إجنــاز العمــل إذا‬\n      ‫أكمــل املدعــي الرســوم املتبقيــة فاســتيفاء املنفعــة وهــي جتديــد رخصــة‬\n      ‫العامــل املذكــور ممكنــة كمــا أن املدعــي لــم يذكــر عيبــا يوجــب‬\n      ‫الفســخ وألن املدعــى عليــه وافــق علــى فســخ العقــد فيمــا يتعلــق باملبلــغ‬\n      ‫املدفــوع للجــوازات وقــدره ســتمائة ريــال وملــا تقــدم كلــه فقــد حكمــت‬\n      ‫مبــا يلــي أوال أن يدفــع املدعــى عليــه للمدعــي مبلــغ ســتمائة ريــال وهــي‬\n      ‫الرســوم التــي دفعــت للجــوازات ثانيــا رددت دعــوى املدعــي يف مطالبتــه‬\n      ‫يف باقــي املبلــغ وقــدره ألفــان وخمســمائة ريــال وأفهمتــه بــأن لــه مطالبــة‬\n      ‫مــن بيــده العــن إذا رغــب وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n      ‫عليــه القناعــة بــه وقــرر املدعــي االعتــراض علــى احلكــم وطالــب بتمييــزه‬\n      ‫بــدون الئحــة اعتراضيــة فأجيــب لذلــك وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/11/23‬ه ـ‬\n      ‫احلمــد هلل وحده ـ والصــاة والســام علــى مــن ال نبــي بعــده فلــدي أنــا‬\n      ‫‪ ........‬رئيــس احملكمــة العامــة مبحافظــة بقعــاء افتتحــت اجللســة يف‬\n      ‫يــوم االثنــن املوافــق ‪1434/12/16‬ه ـ الســاعة الواحــدة وخمســة عشــر‬\n      ‫دقيقــة ظهــرا بنــاء علــى ورود املعاملــة مــن محكمــة االســتئناف بحائــل‬\n      ‫برقــم ‪ 342544637‬يف ‪1434/12/3‬ه ـ ومرفقــا بهــا قــرار الدائــرة‬\n      ‫احلقوقيــة األولــى رقــم ‪ 34373422‬يف ‪1434/11/27‬ه ـ املتضمــن مــا‬\n      ‫نصــه بعــد املقدمــة وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قررنــا املصادقــة علــى مــا حكــم بــه فضيلتــه وصلــى اهلل وســلم علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/12/16‬هــ‪.‬‬\n\n\n‫‪339‬‬\n\f340\n\f341\n\f342\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":335,"source_page_end":342,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b907a8d81539e41279ae2958b01ff85aabce877ba1690bec73179c55592c5a87","normalized_text_hash":"11548a8914fb285247195207f95c9280eb5dbe823199559e41d416f0ad9968ba","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p335-34368555"},{"id":"10199698-97fc-5533-bb2f-2eb43d84fe65","document_type":"judgment","category":"judicial","subcategory":"general","title":"شفعة -شفعة جار -بيع مزرعة -وجود حدود مستقلة بن مزرعة املدعي واملدعى عليه -الشهادة بأن األرض محاطة بعقوم وشبوك- املرفق املشترك يخدم سائر املزارع املجاورة -صرف النظر لكون العن املباعة غير مشاعة (مفروزة مستقلة).","document_number":"3457090","case_number":"3351663","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/7","year":"1434","subject":"شفعة -شفعة جار -بيع مزرعة -وجود حدود مستقلة بن مزرعة املدعي واملدعى عليه -الشهادة بأن األرض محاطة بعقوم وشبوك- املرفق املشترك يخدم سائر املزارع املجاورة -صرف النظر لكون العن املباعة غير مشاعة (مفروزة مستقلة).","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/3/7 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3457090 :‬‬\n                         ‫َر ْق ُم الدعوى‪3351663 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34198915‬تاريخه‪1434/4/27:‬هـ‬\n\n\n      ‫شــفعة‪ -‬شــفعة جــار‪ -‬بيــع مزرعــة‪ -‬وجــود حــدود مســتقلة بــن مزرعــة‬\n      ‫املدعــي واملدعــى عليــه‪ -‬الشــهادة بــأن األرض محاطــة بعقــوم وشــبوك‪-‬‬\n      ‫املرفــق املشــترك يخــدم ســائر املــزارع املجــاورة ‪ -‬صــرف النظــر لكــون‬\n                            ‫العــن املباعــة غيــر مشــاعة (مفــروزة مســتقلة)‪.‬‬\n\n\n\n      ‫‪« .1‬الشــفعة تثبــت للجــار فيمــا إذا كان شــريكا يف حقــوق امللــك مــن‬\n                                   ‫طريــق أو مســيل وغيرهــا» (املبــدع ‪.)206/5‬‬\n                        ‫‪ .2‬قرار هيئة كبار العلماء رقم ‪ 44‬يف ‪1396/4/13‬هــ‪.‬‬\n\n\n\n      ‫تقــدم وكيــل املدعــي بدعــواه ضــد املدعــى عليــه بأنــه اشــترى املزرعــة‬\n      ‫املجــاورة ملزرعــة موكلــه التــي تفصــل بينــه وبــن مزرعــة والــده ويطالــب‬\n      ‫بالشــفعة‪ -‬أقــر املدعــى عليــه بأنــه اشــترى املزرعــة املجــاورة ملزرعــة‬\n      ‫املدعــي ودفــع بــأن شــروط اســتحقاق املدعــي للشــفعة ال تنطبــق علــى‬\n      ‫الواقعــة‪ -‬طلــب صــرف النظــر عــن دعــواه كمــا طلــب تعويضــه عــن‬\n      ‫األضــرار التــي حلقــت بــه جــراء تعليــق تصرفــه يف أرضــه طــول املــدة التــي‬\n      ‫ســتبقى موقوفــة بســبب الدعــوى وحترمــه مــن بيــع أرضــه واســتثمار املبلغ‬\n      ‫الكبيــر قيمــة األرض ‪ ،‬خاصــة عنــد عــدم اســتقرار أســعار األراضــي‬\n      ‫يف الوقــت الراهــن وحتمــل أتعــاب احملامــاة‪ -‬متســك املدعــي ببعــض‬\n‫‪343‬‬\n\f‫النصــوص الشــرعية وأقــوال بعــض أهــل العلــم باســتحقاق اجلــار للشــفعة‬\n‫إن اشــتركا يف حــق مــن حقــوق امللــك كالطريــق وأن الطريــق املوصــل‬\n‫للمزرعتــن واملــزارع املجــاورة واحــد‪ -‬أنكــر املدعــي بأنــه لــم يطالــب‬\n‫بهــا علــى الفــور وقــرر بأنــه طالــب بهــا فــور علمــه بالبيــع وأن الراجــح‬\n‫بــأن املطالبــة بالشــفعة علــى التراخــي ال الفــور وأن طلبــه للصلــح ال يلــزم‬\n‫منــه اإلقــرار بصحــة البيــع ‪ -‬أحضــر املدعــى عليــه شــاهدين شــهدا‬\n‫بــأن املزرعــة محاطــة بشــبوك وعقــوم‪ -‬عليــه وملــا رواه جابــر ‪-‬رضــي‬\n‫اهلل عنــه‪ -‬قــال‪« :‬أن النبــي صلــى اهلل عليــه وســلم قضــى بالشــفعة يف‬\n‫كل مــا لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة «‪،‬‬\n‫وألن أهــل العلــم ‪-‬رحمهــم اهلل تعالــى‪ -‬قــرروا بــأن الشــفعة تثبــت للجــار‬\n‫فيمــا إذا كان شــريكان يف حقــوق امللــك مــن طريــق أو مســيل وغيرهــا‬\n‫(املبــدع ‪ ،)206/5‬وقــد صــدر قــرار هيئــة كبــار العلمــاء رقــم‪ 44 :‬يف‬\n‫‪1396/4/13‬هـ ـ املتضمــن أن الشــفعة تثبــت بالشــركة يف املرافــق‬\n‫اخلاصــة كالبئــر والطريــق واملســيل ‪ ،‬ومبــا أن املدعــي لــم يذكــر وجــود‬\n‫اشــتراك بينــه وبــن املدعــى عليــه إال الطريــق املذكــور‪ ،‬وقــد قــرر أنــه‬\n‫طريــق عــام وقــد شــهد الشــاهدان أن األرض محيــوزة ومعقمــة؛ لذلــك‬\n‫كلــه فقــد صرفــت الدائــرة النظــر عــن دعــوى املدعــي لعــدم اســتحقاقه‬\n‫الشــفعة كمــا صرفــت النظــر عــن طلبــات املدعــى عليــه وأفهمتــه بــأن‬\n‫لــه التقــدم بهــا بعــد اكتســاب احلكــم القطعيــة ‪ -‬وبعــرض احلكــم‬\n‫عليهمــا‪ ،‬قــرر املدعــى عليــه القناعــة‪ ،‬قــرر املدعــي االعتــراض بتقــدمي‬\n‫الئحــة فأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                     ‫‪344‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪......................‬القاضــي يف احملكمــة‬\n      ‫العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بالريــاض برقــم ‪ 3351663‬وتاريــخ ‪1433/01/19‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 33133609‬وتـ ــاريـ ـ ــخ ‪1433/01/19‬ه ففــي‬\n      ‫يـ ـ ـ ـ ــوم الســبت املـ ـ ـ ــوافق‪ 1433/04/10‬ه ـ افتتحــت اجلـ ــلسـ ـ ــة الســاعة‬\n      ‫‪ 11 : 10‬وفيهــا حضــر ‪..........................‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ..................‬بصفتــه وكيــا عــن ‪.........................‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل املزاحميــة برقــم ‪ 14‬يف‬\n      ‫‪1433/4/10‬ه ـ واملخــول لــه فيهــا بإقامــة الدعاوى واملخاصمــة واملرافعة‬\n      ‫واملدافعــة وســماع الدعــاوي والــرد عليهــا وإقامــة البينــة واإلقــرار وحضــر‬\n      ‫حلضــوره ‪ ............................‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ..................‬بصفتــه وكيــا عــن ‪ .......................‬مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم ‪3339621‬‬\n      ‫وتاريــخ ‪1433/4/7‬ه ـ واملخــول لــه فيهــا باملرافعــة واملدافعــة وقبــول‬\n      ‫األحــكام ونفيهــا وطلــب اإلســتئناف قائــا يف دعــواه إن موكلــي ميلــك‬\n      ‫املزرعــة الواقعــة يف مركــز اجللــه شــمال طريــق الريــاض الطائــف ويحــد‬\n      ‫أرض موكلــي أرض زراعيــة مملوكــة ‪ ...‬مــن الشــمال وقــد قــام مالــك‬\n      ‫االرض املذكــورة ببيعهــا علــى املدعــى عليــه أصالــة‪.......................‬‬\n      ‫مببلــغ مليــون وســتمائة ألــف ريــال وقــد علــم موكلــي ببيعهــا قبــل‬\n      ‫افراغهــا للمدعــى عليــه بيــوم فقــام باالتصــال علــى املدعــى عليــه أصالــة‬\n      ‫وأخبــره أنــه شــافع يف األرض لكونهــا حتــده مــن الشــمال وهــذه األرض‬\n\n‫‪345‬‬\n\f‫بينــه وبــن أرض والــده فقــال لــه املدعــى عليــه يكــون خيــر ثــم قــام‬\n‫بإقفــال جوالــه وموكلــي يرغــب يف شــراء هــذه األرض وأننــي أطلــب‬\n‫يف دعــواي هــذه ســؤال املدعــى عليــه وكالــة وإثبــات شــفعة موكلــي‬\n‫يف االرض املذكــورة وشــرائها لكونــه أحــق بهــا مــن املدعــى عليــه‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه وكالــة قــال إننــي أطلــب إمهالــي‬\n‫ملراجعــة موكلــي واســتعد بإحضــار اجلــواب يف اجللســة القادمــة هــذا‬\n‫مــا لــدي وقــال املدعــي وكالــة إننــي ســبق وإن تقدمــت بطلــب احلجــز‬\n‫التحفظــي علــى األرض املدعــى بهــا وأقــرر لديكــم عــدول موكلــي‬\n‫عــن هــذا الطلــب هــذا مــا لــدي وبنــاء عليــه فقــد جــرى رفــع اجللســة ويف‬\n‫جلســة أخــرى حضــر املدعــي وكالــه ‪ .................‬واملدعــى عليــه وكالــه‬\n‫‪ ..................‬وابــرز املدعــى عليــه وكالــة الوكالــة الصــادرة مــن كتابــه‬\n‫عــدل جنــوب الريــاض الثانيــة برقــم ‪ 33151641‬يف ‪1433/7/2‬ه ـ والتي‬\n‫وكلــه فيهــا ‪ ..........................‬وجعــل لــه فيهــا حــق املرافعــة واملدافعــة‬\n‫واالقــرار واالنــكار والصلــح وطلــب اليمــن ورده وابــرز املدعــى عليــه‬\n   ‫وكالــه مذكرتــه اجلوابيــة املكــون مــن صفحتــن والتــي جــاء فيهــا‬\n‫إش ــارة إل ــى الدع ــوى رقــم (‪ )33133609‬وتاريــخ ‪1433 /01/19‬ه ـ‬\n‫املقام ــة مــن املكــرم ‪ ......................... /‬ض ــد موكلــي امل ــكرم ‪/‬‬\n‫‪...........................‬املتضمنــة طلــب إفــراغ أرض موكلــي لــه بحجــة أن‬\n‫األرض املوصوفــة أدنــاه تقــع بينــه وبــن ملــك مزرعــة والــده ومتداخلــة‬\n‫بــن صكوكهمــا الواقعــة يف ‪ .................‬التابعــة حملافظــة املزاحميــة‬\n‫(( التــي اشــتراها موكلــي مــن املكــرم ‪..................... /‬مبوجــب عقــد‬\n‫البيــع رقــم (‪ )55‬وتاريــخ ‪1432 /10/26‬ه ـ مبلــغ وقــدره مليــون وســتمائة‬\n‫ألــف ريــال (‪ )1600000‬باإلضافــة إلــى مبلــغ الســعي البالــغ أربعــون ألــف‬\n\n\n                                                                                          ‫‪346‬‬\n\f      ‫ريــال (‪ )40000‬ومســاحتها مليونــن وأربعمائــة وواحــد وعشــرين ألــف‬\n      ‫وثالثمائــة وخمســة وســبعون متــر مربــع (‪ )2421375‬واألرض حســب‬\n      ‫شــروط العقــد وشــهادة الشــهود محيــوزة ومحــدودة بشــبك وعقــم‬\n      ‫مــن جميــع اجلهــات ومــا بداخلــه داخــل يف البيــع ويحدهــا مــن الغــرب‬\n      ‫شــارع عــام عرضــه خمســون متــرا (‪ )50‬م وقــد مت إفراغهــا ملوكلــي‬\n      ‫مبوجــب الصــك رقــم (‪ )3/149/1697‬وتاريــخ‪1432/11/11‬ه الصــادر‬\n      ‫مــن كتابــة عــدل املزاحميــة))‪ .‬وعليــه أطلــب صــرف النظــر عــن طلــب‬\n                                                       ‫املدعــي لألمــور التاليــة ‪:‬‬\n      ‫أوالً‪ :‬املدعــي غيــر ذي صفــة فــاألرض محيــوزة ومحاطــة بشــبك وعقــم‬\n      ‫ترابــي ‪ ،‬وهــي القطعــة الزراعيــة رقــم (‪ )4‬مــن املخطــط الزراعــي رقــم‬\n      ‫(‪ )6/218‬الصــادر مــن وزارة الزراعــة منــذ أكثــر مــن ثالثــة وعشــرين‬\n      ‫ســنة حســب تاريــخ صــك األرض الصــادر مــن كتابــة عــدل محافظــة‬\n      ‫القويعيــة رقــم (‪52‬ح‪ 2‬صـ‪ 52‬ــ) وتاريــخ ‪1409/12/21‬ه ـ وقد مت إفراغها‬\n      ‫ملوكلي مبوجب الصك رقم (‪ )3/149/1697‬وتاريخ ‪1432/11/11‬هـ‬\n      ‫)) الصــادر مــن كتابــة عــدل املزاحميــة والكروكــي واســتلم موكلــي‬\n      ‫األرض خاليــة غيــر مشــغولة بعــد الوقــوف عليهــا فقبضهــا يف محلهــا‬\n      ‫وصــارت يف حوزتــه وحتــت يــده محيــوزة ومحــدودة بشــبك وعقــم مــن‬\n      ‫جميــع اجلهــات ومــا بداخلــه داخــل يف البيــع‪ ،‬واألرض ليســت متداخلــة‬\n      ‫بــن أرض املدعــي وبــن مزرعــة والــده أو متداخلــة بــن صكوكهمــا‬\n      ‫حســب الصكــوك والكروكــي ‪ ،‬علمــا أن املدعــي لــم يذكــر موقــع‬\n      ‫عقــاره وحــدوده وكامــل أطوالــه ومســاحته وصــك متلكــه وموقــع اجلــزء‬\n                             ‫املتداخــل مــن العقــار وحــدوده وأطوالــه ومســاحته‪.‬‬\n      ‫ثانيـ ًا ‪ :‬األرض معروضــة للبيــع منــذ أكثــر مــن ســنة ‪ ،‬واألرض ومعظــم‬\n\n\n‫‪347‬‬\n\f‫األراضــي املجــاورة هــي عبــارة عــن مــزارع مهجــورة وغيــر مأهولــة‬\n                                                                    ‫بالســكان‪.‬‬\n‫ثالثـ ًا ‪ :‬املدعــي ليــس شــريكا للبائــع يف األرض وال شــريكا يف منافعهــا‬\n‫‪ ،‬فاألرض يحدها من الشمال أرض ‪ ..............‬وجنوبا مزرعة ‪...............‬‬\n                     ‫وشــرقا أرض ‪ ........................‬وغربا شــارع عام عرضه‬\n‫خمســون متــرا ولــم يذكــر يف صحيفــة دعــواه أي مســتند أو بيــان‬\n‫يثبــت شــيئا مــن ذلــك ‪ ،‬وقــد صــدر قــرار فتــوى هيئــة كبــار العلمــاء ذو‬\n‫الرقــم (‪ )44‬يف ‪1396/4/13‬ه ـ يف الــدورة الثامنــة املنعقــدة يف الريــاض‬\n‫والتيــوردت بصيغــة تعميــم علــى كافــة احملاكــم بالرقــم ‪/13/161‬ت‬\n‫يف ‪1396/8/12‬ه ـ مــن معالــي وزيــر العــدل واملبنــي علــى خطــاب‬\n‫املقــام الســامي ذي الرقــم ‪ 17080‬يف ‪1396/7/15‬ه ـ (‪ ...‬قــرر املجلــس‬\n‫باألكثريــة أن الشــفعة تثبــت بالشــركة يف املرافــق اخلاصــة كالبئــر‪...‬‬\n‫ونحوهمــا كمــا تثبــت الشــفعة فيمــا ال ميكــن قســمته مــن العقــار‬\n‫كالبيــت واحلانــوت الصغيريــن ‪ ،....‬وملــا روى البخــاري يف صحيحــه وأبــو‬\n‫داود والترمــذي يف ســننهما بإســنادهم إلــى جابــر بــن عبــداهلل رضــي اهلل‬\n‫عنهمــا قــال ‪ :‬قضــى رســول اهلل صلــى اهلل عليــه وســلم بالشــفعة يف كل‬\n     ‫مــا لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة ‪. )...‬‬\n‫رابعـ ُا ‪ :‬املدعــي تبلــغ بالبيــع حـس ــب إقــراره علــى لســان وكيله يف اجل ــلسة‬\n‫‪1433 /4/10‬ه ـ واملــدون يف محضــر اجللســة أنــه تبلــغ ليلــة إفــراغ الصــك‬\n‫للمشــتري بتاريــخ ‪1432/11/11‬ه ـ ولــم يبــادر بالشــفعة علــى الفــور‬\n‫وقــد تراخــى و تأخــر أكثــر مــن شــهرين يف املطالبــة بالشــفعة وتقــدمي‬\n‫صحيفــة دعــواه حتــى تاريــخ ‪1433/1/19‬ه ـ ‪ .‬وقــد ورديف األثــر (الشــفعة‬\n‫كحــل العقــال) (فــإن قيدهــا مكانــه ثبــت حقــه‪ ،‬وإال فاللــوم عليــه)‬\n\n\n                                                                                       ‫‪348‬‬\n\f      ‫(إمنــا الشــفعة ملــن واثبهــا ) ومــن تراخــى عــن املطالبــة ســقط حقــه يف‬\n                                                                                   ‫الشــفعة‬\n      ‫خامسـ ًا ‪ :‬عــرض املدعــي علــى املشــتري شــراء األرض بفائــدة (خمســون‬\n      ‫ألــف ريــال) بتاريخ‪1432/11/17‬ه ـ بحضــور ‪ .............................‬وبعــد‬\n      ‫فتــرة قبــل تقــدمي صحيفــة الدعــوى عــرض شــرائها مببلــغ مليونــن ريــال‬\n      ‫عــن طريــق ‪ ...‬و‪ ،...‬وهــذا يــدل علــى إقــراره بأنهــا ملــك للمشــتري وأن‬\n      ‫ا حــق يف الشــفعة‪ .‬وعليــه أطلــب صــرف النظــر عــن طلــب‬          ‫ليــس لــه أص ـ ً‬\n      ‫املدعــي لألســباب املذكــورة أعــاه ‪ ،‬كمــا أطلــب تعويــض موكلــي‬\n      ‫عــن األضــرار التــي حلقــت بــه جــراء تعليــق تصرفــه يف أرضــه وطــول‬\n      ‫املــدة التــي ســتبقى موقوفــه بســبب الدعــوى وحترمــه مــن بيــع أرضــه‬\n      ‫واســتثمار املبلــغ الكبيــر قيمــة األرض ‪ ،‬خاصــة عنــد عــدم اســتقرار‬\n      ‫أســعار األراضــي يف الوقــت الراهــن وحتمــل أتعــاب احملامــاة اه ـ وبعــرض‬\n      ‫جــواب املدعــى عليــه وكالــه علــى املدعــي وكالــه بعــد تســليمه صــوره‬\n      ‫مــن املذكــرة اجلوابيــة قــال اطلــب امهالــي ملراجعــة موكلــي واســتعد‬\n      ‫إلحضار اجلواب يف اجللســة القادمة وبناء عليه مت رفع اجللســة ويف جلســة‬\n      ‫اخــرى حضــر املدعــي وكالــة وحضــر حلضــوره املدعــى عليــه وكالــة‬\n      ‫واملدونــة هوياتهمــا ســابقا‪ ،‬وقــدم املدعــي وكالــة مذكــرة جــاء فيهــا‪:‬‬\n      ‫‪ -1‬مــا ذكــره املدعــي عليــه وكالــة بقولــه (واســتلم موكلــي األرض‬\n      ‫خاليــة غيــر مشــغولة بعــد الوقــوف عليهــا فقبضهــا يف محلهــا وصــارت يف‬\n      ‫حوزتــه وحتــت يــده محيــوزة ومحــدودة بشــبك وعقــم مــن جميــع اجلهــات‬\n      ‫ومــا بداخلــه داخــل يف البيــع ‪..‬إلــخ ) وتعقيبــي ‪:‬أنــا ال أطالــب بإزالــة حتــى‬\n      ‫يذكــر املدعــى عليــه وكالــة مــا تقــدم إمنــا أطالــب بالشــفعة والشــفعة‬\n      ‫هــي حــق متلــك العقــار املبيــع جبــرا عــن املشــترى مبــا قــام عليــه مــن ثمــن‬\n\n\n‫‪349‬‬\n\f‫وتكاليــف ‪ ،‬أمــا مــا ذكــره بقولــه (واألرض ليســت متداخلــة بــن أرض‬\n‫املدعــي وبــن مزرعــة والــده أو متداخلــة بــن صكوكهــا ‪..‬إلــخ ) فهــذا‬\n‫غيــر صحيــح‪ ،‬بــل مــا ورد بإجابتــه بإقــراره بالبنــد (ثالث ـاً) يفيــد وقوعــه‬\n‫يف التناقــض وعــدم صحــة مــا ورد بدفعــه حــن قــال (األرض يحدهــا‬\n‫مــن الشــمال أرض ‪( .................... /‬والــد املدعــي) وجنوب ـ ًا مزرعــة ‪/‬‬\n‫‪( ...............‬املدعــي أصالــة)‪ -2.‬قولــه أنــي لســت شــريكا يف األرض‬\n‫أقــول ‪ :‬أهــل العلــم أجــازوا ذلــك ملــن يشــترك يف حــق مــن حقــوق امللــك‬\n‫كالطريــق مثــا ملــا رواه أصحــاب الســن بإســناد صحيــح عــن جابــر‬\n‫عــن النبــي‪ ،‬صلــى اهلل عليــه وســلم‪ ،‬قــال‪ :‬اجلــار أحــق بشــفعة جــاره‪،‬‬\n‫ينتظــر بهــا وإن كان غائبــا إذا كان طريقهمــا واحــدا قــال ابــن القيــم‪:‬‬\n‫وعلــى هــذا القــول تــدل أحاديــث جابــر منطوقهــا ومفهومهــا ويــزول عنهــا‬\n‫القضــاء واالختــاف‪ .‬وقــد فصــل هــذه النقطــة الشــيخ محمــد العثيمــن‬\n‫بقولــه ‪ :‬فــإذا قــال قائــل‪ :‬مــا الدليــل علــى مــا اشــترطه املؤلــف ألن قولــه‪:‬‬\n‫لشــريك يف أرض يخــرج اجلــار‪ ،‬وقــد صـ َّـرح بــه فقــال‪ :‬فــا شــفعة جلــار‬\n‫فمــا الدليــل قالــوا‪ :‬إن الدليــل قــول جابــر ـ رضــي اهلل عنــه ـ‪( :‬قضــى‬\n‫النبــي ص ّلــى اهلل عليــه وسـلّم بالشــفعة يف كل مــا لــم يقســم) فمفهومــه‬\n‫أن مــا قســم ليــس فيــه شــفعة‪ ،‬وإذا قســم صــار الشــريك جــاراً‪ ،‬كأرض‬\n‫بــن رجلــن اقتســماها كانــت يف األول مشــتركة واآلن صــار الشــريك‬\n‫جــاراً‪ ،‬واحلديــث‪( :‬قضــى النبــي ص ّلــى اهلل عليــه وسـلّم بالشــفعة فيــكل‬\n‫مــا لــم يقســم) هــذا املنطــوق‪ ،‬ومفهومــه ال شــفعة فيمــا قســم‪ ،‬والنتيجــة‬\n‫ال شــفعة للجــار ألنــه إذا كان اجلــار الــذي كان شــريك ًا بــاألول ال‬\n‫شــفعة لــه‪ ،‬فاجلــار الــذي ليــس بينــه وبــن جــاره شــركة مــن بــاب أولــى‪.‬‬\n‫ولكــن نقــول‪ :‬االســتدالل بهــذا احلديــث فيــه نظــر؛ ألنــه يجــب إذا‬\n\n\n                                                                                        ‫‪350‬‬\n\f      ‫اســتدللنا باحلديــث أن نســتدل بــه كام ـاً‪ ،‬وإذا اســتدللنا باحلديــث‬\n      ‫ا لــزم أن يكــون اجلــار لــه شــفعة يف بعــض األحــوال‪ ،‬وليــس لــه‬     ‫كام ـ ً‬\n      ‫شــفعة يف بعــض األحــوال‪ ،‬يقــول جاب ـرـ رضــي اهلل عنــه ـ‪( :‬فــإذا وقعــت‬\n      ‫احلــدود وصرفــت الطــرق فــا شــفعة) فاحلديــث بـ َّـن أنــه إذا حصلــت‬\n      ‫وصرفــت الطــرق‪ ،‬بــأن كان هــذا‬     ‫ِّ‬    ‫القســمة ورســمت األرض بحدودهــا‬\n      ‫اجلانــب لــه طريــق واجلانــب اآلخــر لــه طريــق فــا شــفعة‪ ،‬فيؤخــذ مــن‬\n      ‫هــذا أنهمــا لــو اقتســما وبقــي الطريــق واحــد ًا لــم ُيصـ َّـرف فالشــفعة‬\n      ‫باقيــة‪ ،‬وهــذا هــو القــول الراجــح‪ ،‬أن اجلــار لــه الشــفعة فيحــال وليــس لــه‬\n      ‫الشــفعة يف حــال‪ ،‬فــإذا كانــت الطريــق واحــدة‪ ،‬أو املــاء الــذي يســقى‬\n      ‫بــه الــزرع واحــداً‪ ،‬أو أي شــيء اشــتركا فيــه مــن حــق امللــك فــإن الشــفعة‬\n      ‫ثابتــة‪ ،‬وإذا لــم يكــن بينهمــا حــق مشــترك فــا شــفعة‪ ،‬هــذا هــو القــول‬\n      ‫الراجــح يف ثبــوت الشــفعة للجــار‪ ،‬وعليــه يحمــل حديــث‪ :‬اجلــار أحــق‬\n      ‫بســقبه ‪ ،‬وهــو اختيــار شــيخ اإلســام ابــن تيميــة ـ رحمــه اهلل ـ‪ .‬وقــال‬\n      ‫بعــض العلمــاء‪ :‬للجــار الشــفعة مطلق ـ ًا حلديــث‪ :‬اجلــار أحــق بســقبه أي‪:‬‬\n      ‫مبــا جــاوره‪ -3.‬لــم أعلــم عــن عــرض األرض للبيــع خصوصــا وأن غالــب‬\n      ‫إقامتــي الســنوات األخيــرة خــارج البــاد وال يســتطيع املدعــى عليــه‬\n      ‫إثبــات علمــي بالبيــع‪ :-4.‬إننــي بــادرت لطلــب الشــفعة حــال علمــي وال‬\n      ‫ميلــك املدعــى عليــه البينــة علــى رضــاي وتهاونــي ‪ ،‬واالســتدالل مــن قبــل‬\n      ‫املدعــى عليــه بحديــث‪ :‬الشــفعة ملــن واثبهــا والشــفعة كحــل العقــال ] أرد‬\n      ‫عليــه بــأن هذيــن احلديثــن ضعيفــن كمــا قــال ابــن عثيمــن وأضــاف ‪:‬‬\n      ‫ال ُيحتــج بهمــا وال ميكــن أن يتوصــل بهمــا إلــى إســقاط حــق املســلم فــا‬\n      ‫اعتمــاد عليهمــا‪ ،‬وإذا لــم يكــن عليهمــا اعتمــاد رجعنــا إلــى األصــل‪،‬‬\n      ‫واألصــل أن كل مــن ثبــت لــه حــق فإنــه ال يســقط إال مبــا يــدل علــى‬\n\n\n‫‪351‬‬\n\f‫رضــاه؛ ألن هــذا حــق شــرعي‪ :‬قضــى النبــي ص ّلــى اهلل عليــه وس ـلّم‬\n‫بالشــفعة يف كل مــا لــم يقســم فهــذا قضــاء نبــوي ال ميكــن أن يســقط‬\n‫إال مبــا يــدل علــى الرضــا‪ .‬وعليــه فالقــول الراجــح الــذي يتعــن األخــذ‬\n‫بــه أن يقــال‪ :‬هــي علــى التراخــي ال تســقط إال مبــا يــدل علــى الرضــا‪.‬‬\n‫‪ -5‬ال صحــة لطلــب الشــراء وكنــت حريصــا علــى ســامة النفــوس فــا‬\n‫يســقط حقــي مــن الشــفعة قــال ابــن عثيمــن رحمــه اهلل ‪ :‬لكــن ينبغــي‬\n‫أن يقــال‪ :‬إن اللــوازم التــي ذكروهــا مــن أن طلــب املصاحلــة‪ ،‬أو طلــب‬\n‫البعــض‪ ،‬أو مــا أشــبه ذلــك‪ ،‬تــدل علــى أنــه أقــر البيــع‪ ،‬ينبغــي أن يقــال‪:‬‬\n‫إذا وقــع هــذا مــن عالــم فنعــم‪ ،‬وإن وقــع مــن جاهــل ال يــدري‪ ،‬وقــال‪ :‬أنــا‬\n‫أريــد املصاحلــة دفعـ ًا للمطالبــة وكســر قلبــه‪ ،‬ومــا أشــبه ذلــك‪ ،‬فإنــه ال‬\n‫ينبغــي أن تســقط الشــفعة‪ ،‬فيفــرق بــن مــن يفهــم ويعلــم‪ ،‬وبــن مــن ال‬\n‫يفهــم وال يعلــم‪ ،‬فــإذا قــال‪ :‬صاحلنــي‪ ،‬أو جنعلهــا أنصاف ـ ًا لــك النصــف‬\n‫ولــي النصــف‪ ،‬عــن ســامة قلــب وعــدم معرفــة فينبغــي أن ال تســقط‬\n‫الشــفعة؛ ألنــه يف هــذه احلــال معــذور‪ ،‬وكمــا عــذروا مــن لــم يطلبهــا علــى‬\n‫الفــور مبــا عــذروه بــه‪ ،‬فهــذه مثلهــا واخلالصــة‪ :‬أن الشــفعة حق للشــفيع ال‬\n‫تســقط إال مبــا يــدل علــى رضــاه‪ ،‬أمــا كونهــا حقـ ًا للشــفيع فهــو قضــاء‬\n‫نبــوي‪ :‬قضــى بالشــفعة يف كل مــا يقســم ‪ ،‬وأمــا كونهــا ال تســقط‬\n‫إال برضــاه؛ فألنهــا حقــه‪ ،‬وال ميكــن أن تؤخــذ احلقــوق مــن أصحابهــا‬\n‫كره ـ ًا وكذلــك بخصــوص مــا ذكــره املدعــي عليــه مبذكرتــه‬\n‫الســابقة يف البنــد خامســا بــأن موكلــي عــرض شــرائها مببلــغ مليونــن‬\n‫ال مــن ‪ ................‬و‪ ،.................‬فأنــه بعــد رجــوع‬\n                                                              ‫ريــال عــن طريــق ك ً‬\n‫موكلــي لهــم أنكــرا ذلــك‪ ،‬ومســتعدون بالشــهادة بذلــك‪ -6.‬كمــا أن‬\n‫املدعــى عليــه لــم يعمــل بأمركــم املنــع مــن التصــرف يف األرض حلــن‬\n\n\n                                                                                       ‫‪352‬‬\n\f      ‫نهايــة القضيــة بــل قــام ببيــع قطــع فيهــا ومــن املؤســف جــد ًا أنــه بــاع علــى‬\n      ‫أنــاس يعتبــرون دخــاء علــى املنطقــة ويخالفــون أهلهــا يف عقيدتهــم (ال‬\n      ‫والء إال ببــراء) وقــد صــدرت فتــاوى أهــل العلــم بحرمــة ذلــك ممــا يؤكــد‬\n      ‫الضــرر علينــا‪ .‬وحلكمــة الشــفعة مــن حيــث دفــع الضــرر عــن الشــفيع‪،‬‬\n      ‫إذ قــد ال تتفــق أخالقــه وعاداتــه ومذهبــه مــع املشــترى اجلديــد ‪ ،‬وقــد‬\n      ‫يكــون مؤذيــا ســيء األخــاق أو العــادات أو الطبــاع‪ ،‬ولقولــه صلــى اهلل‬\n      ‫عليــه وســلم ( جــار الــدار أحــق بالــدار) و ( اجلــار أحــق بســقبه )‪ .‬بجميــع‬\n      ‫مــا ســبق فإنــي أطلــب حقــي بالشــفعة مــن املدعــى عليــه ‪ ،‬وبعرضــه علــى‬\n      ‫املدعــى عليــه وكالــة بعــد تســليمه صــورة منهــا قــال او ًال املدعــي غير ذي‬\n      ‫صفــة فــاألرض محيــوزة ومحاطــة بشــبك وعقــم ترابــي‪ ،‬وهــي القطعــة‬\n      ‫الزراعيــة رقــم (‪ )4‬مــن املخطــط الزراعــي رقــم (‪ )6/218‬الصــادر مــن‬\n      ‫وزارة الزراعــة منــذ أكثــر مــن ثالثــة وعشــرين ســنة حســب تاريــخ صــك‬\n      ‫األرض الصــادر مــن كتابــة عدل محافظة القويعية رقم (‪52‬ح‪ 2‬صـ‪52‬ــ)‬\n      ‫وتاريــخ ‪1409/12/21‬ه ـ وقــدمت إفراغهــا ملوكلــي مبوجــب الصــك‬\n      ‫رقــم(‪ )3/149/1697‬وتاريخ‪1432/11/11‬ه ـ )الصــادر مــن كتابــة‬\n      ‫عــدل املزاحميــة والكروكــي املرفــق صورتــه واســتلم موكلــي األرض‬\n      ‫خاليــة غيــر مشــغولة بعــد الوقــوف عليهــا فقبضهــا يف محلهــا وصــارت‬\n      ‫يف حوزتــه وحتــت يــده ‪ ،‬محيــوزة ومحــدودة بشــبك وعقــم مــن جميــع‬\n      ‫اجلهــات ومــا بداخلــه داخــل يف البيع(وقــد أقــر املدعــي صراحــة بذلــك‬\n      ‫يف مذكرتــه الدفاعيــة الفقــرة األولــى التــي ســلمها وكيلــه يف اجللســة‬\n      ‫الرابعــة وســجلت يف محضــر اجللســة) علمــا أن املدعــي لــم يذكــر موقــع‬\n      ‫عقــاره وحــدوده وكامــل أطوالــه ومســاحته وصــك متلكــه وموقــع اجلــزء‬\n      ‫املتداخــل مــن العقــار وحــدوده وأطوالــه ومســاحته ‪،‬وهــل يوجــد لديــه‬\n\n\n‫‪353‬‬\n\f‫صــك ملكيــة أم ال ثانيـاً‪ :‬ذكــر املدعــي أنــه يشــترك يف حــق مــن حقــوق‬\n‫امللــك كالطريــق وهــذا غيــر صحيــح فالطريــق عــام عرضــه خمســون‬\n‫متــرا وليــس خــاص بينهمــا كمــا هــو موضــح يف الكروكــي ومذكــور‬\n‫يف صــور الصكــوك املســلمة لفضيلتكــم يف اجللســة املاضيــة ‪ ،‬وقــد‬\n‫صدر قرار فتوى هيئة كبار العلماء ذو الرقم (‪ )44‬يف ‪1396/4/13‬هـ‬\n‫يف الــدورة الثامنــة املنعقــدة يف الريــاض والتــي وردت بصيغــة تعميــم علــى‬\n‫كافــة احملاكــم بالرقــم ‪/13/161‬ت يف ‪1396/8/12‬ه ـ مــن معالــي‬\n‫وزيــر العــدل واملبنــي علــى خطــاب املقــام الســامي ذي الرقــم ‪17080‬يف‬\n‫‪1396/7/15‬هـ (‪ ..‬قرر املجلس باألكثرية أن الشــفعة تثبت بالشــركة‬\n‫يف املرافــق اخلاصــة كالبئــر والطريــق ونحوهمــا كمــا تثبــت الشــفعة‬\n‫فيمــا ال ميكــن قســمته مــن العقــار كالبيــت واحلانــوت الصغيرين ‪ ،..‬وملا‬\n‫روى البخــاري يف صحيحــه وأبــو داود والترمــذي فيســننهما بإســنادهم‬\n‫إلــى جابــر بــن عبــداهلل رضــي اهلل عنهمــا قــال ‪ :‬قضــى رســول اهلل صلــى‬\n‫اهلل عليــه وســلم بالشــفعة يف كل مــا لــم يقســم فــإذا وقعــت احلــدود‬\n                                             ‫وصرفــت الطــرق فــا شــفعة ‪.)..‬‬\n‫ثالث ـ ًا ‪:‬ذكــر أنــه طلــب الشــفعة حــال علمــه ولــم يذكــر تاريخــا لذلــك‬\n‫‪ ،‬وأكتفــي مبــا ذكرتــه يف املذكــرة الســابقة عــن هــذه الفقــرة رابعـاُ‪:‬‬\n‫أنكــر املدعــي أنــه عــرض شــرائها مببلــغ مليونــن ريــال عــن طريــق‬\n‫ال مــن ‪..............‬و‪ ................‬وأنهمــا أنكــرا ذلــك وعليــه فــإن املبلــغ‬\n                                                                                   ‫ك ً‬\n‫ليــس هدفــا يف ذاتــه ‪ ،‬وأكتفــي مبــا ذكرتــه يف املذكــرة الســابقة عــن‬\n‫هــذه الفقــرة ‪.‬خامس ـاً‪ :‬ذكــر املدعــي أن موكلــي لــم يعمــل بأمــر املنــع‬\n‫مــن التصــرف يف األرض حلــن نهايــة القضيــة ‪ ،‬ولــم يصــدر أي خطــاب‬\n‫باملنــع وأكتفــي عــن بقيــة الفقــرات مبــا ذكرتــه يف املذكــرة الســابقة‬\n\n\n                                                                                         ‫‪354‬‬\n\f      ‫وعليــه أطلــب صــرف النظــر عــن طلــب املدعــي واحلكــم بذلــك لألســباب‬\n      ‫املذكــورة أعــاه ‪،‬كمــا أطلــب تعويــض موكلــي عــن األضــرار التــي‬\n      ‫حلقــت بــه جــراء ابتعــاد املشــترين بســبب وجــود قضيــة فيهــا وطــول‬\n      ‫املــدة التــي ســتبقى معطلــة بســبب الدعــوى وحترمــه مــن اســتثمار املبلــغ‬\n      ‫الكبيــر (قيمــة األرض)‪ ،‬خاصــة عنــد عــدم اســتقرار أســعار األراضــي‬\n      ‫يف الوقــت الراهــن ‪ ،‬وحتمــل أتعــاب احملامــاة وبعرضــه علــى املدعــي‬\n      ‫وكالــة قــال اكتفــي مبــا قدمــت يف دعــواي وال أعلــم هــل األرض‬\n      ‫محيــوزة بعقــوم وشــبوك هــذا مــا لــدي ‪ ،‬وقــال املدعــى عليــه وكالــة‬\n      ‫لــدي بينــة علــى أن األرض محيــوزة ومحاطــة بعقــوم وشــبوك واســتعد‬\n      ‫بإحضارهــا هــذا مــا لــدي وبنــاء عليــه فقــد مت رفــع اجللســة ويف جلســة‬\n      ‫اخــرى حضــر املدعــي أصالــة‪ .................... /‬حامــل الســجل املدنــي رقــم‪:‬‬\n      ‫(‪ ).......................‬وحضــر حلضــوره املدعــي وكالــة ‪ ...............‬املدونــة‬\n      ‫هويتــه ســابقا‪ ،‬كمــا حضــر املدعــى عليــه أصالــة‪ .................... /‬حامــل‬\n      ‫الســجل املدنــي رقــم‪ )..……………( :‬وحضــر حلضــوره املدعــى‬\n      ‫عليــه وكالــة‪ ................. /‬حامــل الســجل املدنــي رقــم‪)..................( :‬‬\n      ‫بالوكالــة عــن ‪ ...............‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بجنــوب الريــاض برقــم‪ )34219243( :‬وتاريــخ ‪1434/2/24‬ه ـ ـ‬\n      ‫والتــي تخولــه املطالبــة واملدافعــة واملرافعــة وطلــب اليمــن واالقــرار‬\n      ‫واالنــكار‪ ،‬وقــال املدعــي وكالــة إن مزرعــة موكلــي ومزرعــة املدعــى‬\n      ‫عليــه ومزرعــة والــد موكلــي كلهــا ميــر بهــا طريــق عــام عرضــه خمســن‬\n      ‫متــر يخــدم هــذه املــزارع‪ ،‬وغيرهــا‪ ،‬هــذا مــا لــدي‪ .‬وقــال املدعــى عليــه‬\n      ‫أصالــة‪ /‬إن األرض محــل الدعــوى محيــوزة وميــر بهــا الطريــق املذكــور‬\n      ‫مــن جهــة الغــرب ولــدي بينــة أطلــب ســماعها‪ ،‬وأحضــر معــه كال مــن‪:‬‬\n\n\n‫‪355‬‬\n\f‫‪ .................... /1‬حامــل الســجل املدنــي رقــم‪ ،).....................( :‬و‪/2‬‬\n‫‪ ......................‬حامــل الســجل املدنــي رقــم‪ ،).................( :‬وطلــب ســماع‬\n‫مــا لديهمــا‪ ،‬وبســؤالهما عمــا لديهمــا قــال الشــاهد األول ‪.............‬‬\n‫إننــي مــن مواليــد عــام ‪ 1354‬وأســكن يف تبــراك وال أعمــل وليــس‬\n‫بينــي وبــن املدعــي وال املدعــى عليــه أي عالقــة قرابــة‪ ،‬وأشــهد هلل بــأن‬\n‫األرض محــل النــزاع الواقعــة يف شــمال اجللــه التــي يدعــي بهــا املدعــي‬\n‫كانــت ملــكا ل‪ ...................‬ثــم باعهــا علــى ‪ ..................‬ثــم ‪.............‬‬\n‫علــى ‪ ،.................‬واألرض محاطــة بعقــوم وشــبوك‪ ،‬هــذا مــا لــدي مــن‬\n‫شــهادة‪ ،‬وأشــهد هلل بهــا‪ .‬وقــال الشــاهد الثانــي إننــي مــن مواليــد عــام‬\n‫‪1382‬هـ ـ وأســكن يف الريــاض‪ ،‬وأعمــل يف جامعــة امللــك ســعود‪ ،‬وال‬\n‫تربطنــي باملدعــي وال املدعــى عليــه أي عالقــة قرابــة‪ ،‬وأشــهد اهلل بــأن‬\n‫األرض محــل النــزاع الواقعــة يف شــمال اجللــه التــي يدعــي بهــا املدعــي‬\n‫كانــت ملــك ل‪ ....................‬ثــم باعهــا علــى ‪ .................‬ثــم ‪...............‬‬\n‫باعهــا علــى ‪ ،..................‬واألرض محاطــة بعقــوم وشــبوك‪ ،‬هــذا مــا‬\n‫لــدي مــن شــهادة‪ ،‬وأشــهد هلل بهــا‪ ،‬هــذا مــا لــدي‪ .‬وبعــرض الشــهود‬\n‫ومــا جــاء يف شــهادتهم علــى املدعــي أصالــة‪ ،‬قــال‪ :‬أمــا الشــاهد األول‬\n‫عــدل ثقــة‪ ،‬وأمــا الثانــي فــا أعرفــه ومــا جــاء يف شــهادتهم صحيــح إال‬\n‫أن العقــوم والشــبوك علــى أرض أكبــر مســاحة مــن مشــمول الصــك‪،‬‬\n‫هــذا مــا لــدي‪ .‬وبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة وملــا رواه جابــر‬\n‫رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وســلم قضــى بالشــفعة يف‬\n‫كل مــا لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة‪،‬‬\n‫ومبــا أن أهــل العلــم رحمهــم اهلل تعالــى قــرروا أن الشــفعة إمنــا تثبــت‬\n‫للجــار فيمــا إذا كان شــريكان يف حقــوق امللــك مــن طريــق أو مســيل‬\n\n\n                                                                                               ‫‪356‬‬\n\f      ‫وغيرهــا (املبــدع ‪ )206/5‬وقــد صــدر قــرار هيئــة كبــار العلمــاء رقــم‪:‬‬\n      ‫‪ 44‬يف ‪1396/4/13‬ه ـ املتضمن أن الشــفعة تثبت بالشــركة يف املرافق‬\n      ‫اخلاصــة كالبئــر والطريــق واملســيل ومبــا أن املدعــي لــم يذكــر وجــود‬\n      ‫اشــتراك بينــه وبــن املدعــى عليــه إال الطريــق املذكــور‪ ،‬وقــد قــرر أنــه‬\n      ‫طريــق عــام وقــد شــهد الشــاهدان أن األرض محيــوزة ومعقمــة؛ لذلــك‬\n      ‫كلــه فقــد صرفــت النظــر عــن دعــوى املدعــي لعــدم اســتحقاقه الشــفعة‬\n      ‫كمــا صرفــت النظــر عــن طلبــات املدعــى عليــه وكالــة املذكــورة‬\n      ‫وأفهمتــه بــأن لــه التقــدم بهــا بعــد اكتســاب احلكــم القطعيــة وبجميــع‬\n      ‫مــا تقــدم حكمــت‪ ،‬وبعــرض احلكــم عليهمــا‪ ،‬قــرر املدعــى عليهــا‬\n      ‫أصالــة القناعــة‪ ،‬وأمــا املدعــي أصالــة فقــرر عــدم القناعــة‪ ،‬وطلــب‬\n      ‫رفــع املعاملــة إلــى محكمــة االســتئناف‪ ،‬فأجبتــه إلــى طلبــه وأفهمتــه‬\n      ‫بأنــه ســوف يســلم صــورة مــن نســخة احلكــم يــوم االثنــن املوافــق‬\n      ‫‪1434/3/9‬هـ ـ وأن لــه مهلــة ثالثــن يومــا مــن تاريــخ االســتالم لتقــدمي‬\n      ‫الئحتــه االعتراضيــة‪ ،‬فــإذا انتهــت املهلــة ولــم يتقــدم بالئحتــه ســقط‬\n      ‫حقــه يف االعتــراض وأصبــح احلكــم نافــذا وبــه ختمــت اجللســة يف متــام‬\n      ‫الســاعة ‪ 12 : 15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                     ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/4‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪ 1434/5/14‬ه ـ‬\n      ‫افتتحــت ‪ :02 15‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫باخلطــاب رقــم ‪ 34956370‬يف ‪1434/5/4‬ه ـ وبرفقهــا القــرار الصــادر‬\n      ‫مــن الدائــرة الثالثــة لتمييــز القضايــا احلقوقيــة يف محكمــة االســتئناف‬\n      ‫رقم ‪ 34198915‬يف ‪1434/4/27‬هـ واملتضمن وبدراســة الصك وصورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة واوراق املعاملــة تقــرر الدائــرة املصادقــة‬\n\n\n‫‪357‬‬\n\f‫علــى احلكــم واهلل املوفــق أه ـ ‪ ،‬وعليــه جــرى التهميــش مبوجبــه ‪ ،‬وبــه‬\n‫ختمــت اجللســة يف متــام الســاعة ‪ 02:20‬وبــاهلل التوفيــق ‪،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد‬\n‫باخلطــاب رقــم ‪ 33133609‬وتاريــخ ‪1434/4/14‬ه ـ املرفــق بهــا الصــك‬\n‫رقــم ‪ 3457090‬وتاريــخ ‪1434/3/7‬ه ـ الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ...................... /‬املتضمــن احلكــم يف الدعــوى‬\n‫املقامــة مــن ‪........................ /‬ضــد ‪ ........................ /‬علــى النحــو‬\n‫املوضــح بالصــك واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫تقــرر الدائــرة املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                          ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪358‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":343,"source_page_end":358,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"366f1f3dc75012f9d182f41758f80b337b7b24697025cbde79d645c19a4ae757","normalized_text_hash":"483ae3a6198f99ba0ede51060187356643208ec25b976effc0c8a810c08a7711","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p343-3457090"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"c0b61865-7fb5-5630-a0d0-f9c86ccb8613","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -اتعاب محاماة -حجز حتفظي على حصص يف شركة - األصل عدم احلجز إال بعد ثبوت احلق -رد دعوى -االعتراض على احلكم -مرور املدة احملددة نظاما دون االعتراض -حكم قطعي .","document_number":"34202987","case_number":"34189358","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/1","year":"1434","subject":"عقد -اتعاب محاماة -حجز حتفظي على حصص يف شركة - األصل عدم احلجز إال بعد ثبوت احلق -رد دعوى -االعتراض على احلكم -مرور املدة احملددة نظاما دون االعتراض -حكم قطعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34202987 :‬تاريخه‪1434/5/1 :‬هـ‬\n                         ‫رقم الدعوى‪34189358 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34381270‬تاريخه‪1434/12/18 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬اتعــاب محامــاة ‪ -‬حجــز حتفظــي علــى حصــص يف شــركة ‪-‬‬\n      ‫األصــل عــدم احلجــز إال بعــد ثبــوت احلــق ‪ -‬رد دعــوى ‪ -‬االعتــراض علــى‬\n       ‫احلكــم ‪ -‬مــرور املــدة احملــددة نظامــا دون االعتــراض ‪ -‬حكــم قطعــي ‪.‬‬\n\n\n\n\n                              ‫قوله صلى اهلل عليه وسلم ( ال ضرر وال ضرار ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة علــى املدعــى عليهــا الغائبــة عــن مجلــس احلكــم‬\n      ‫يطالــب باحلجــز التحفظــي علــى حصصهــا مــن شــركة وشــركة‬\n      ‫لالســتثمار الصناعــي ‪ -‬حيــث تعاقــدت املدعــى عليهــا مــع مــوكل‬\n      ‫ا عنهــا يف جميــع‬    ‫املدعــي علــى أن يكــون محامي ـ ًا عنهــا ووكي ـ ً‬\n      ‫املنازعــات الناشــئة عــن تركــة مورثهــا فيمــا بينهــا وبــن باقــي الورثــة‬\n      ‫وقــد التزمــت املدعــى عليهــا بدفــع كامــل أتعــاب موكلــه ســواء انتهــت‬\n      ‫النزاعــات عــن طريــق الصلــح أو التحكيــم أو احلكــم القضائــي وســواء‬\n      ‫مت الصلــح عــن طريــق موكلــه أو بدونــه وقــد اســتلم موكلــه جــزء مــن‬\n      ‫األتعــاب وقدرهــا أربعــة ماليــن وخمــس مئــة ألــف ريــال ونســبة أتعابــه‬\n      ‫‪ %5‬باملائــة مــن القيمــة الفعليــة حلصــة املدعــى عليهــا مــن التركــة ‪ -‬وألن‬\n      ‫األصــل عــدم احلجــز إال بعــد ثبــوت احلــق‪ ،‬وملــا يف احلجــز مــع عــدم موجبــه‬\n\n‫‪301‬‬\n\f‫مــن اإلضــرار باحملجــوز عليــه‪ ،‬والضــرر ممنــوع لقولــه صلــى اهلل عليــه‬\n‫وســلم ـ‪( :‬ال ضــرر وال ضــرار) ‪ -‬احلكــم بــرد طلــب املدعــي ‪ -‬اعتــرض‬\n‫املدعــي وكالــة واســتعد بتقــدمي الئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n ‫احلقوقيــة الســابعة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬فلــدي أنــا ‪ ،......‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة‪ ،‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم‪ 34189358 :‬وتاريــخ‪:‬‬\n‫‪1434/04/24‬ه ـ املقيــدة باحملكمــة برقــم‪ 341011253 :‬وتاريــخ‪:‬‬\n‫‪1434/04/24‬ه ـ ففــي يــوم األربعــاء املوافــق‪1434/05/01 :‬ه ـ حضــر‪:‬‬\n‫‪ ،......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪...... :‬الوكيــل‬\n‫عــن‪ ،...... :‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجــدة‬\n‫برقــم‪...... :‬يف‪1434/3/22 :‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة‬\n‫واإلقــرار واإلنــكار والصلــح والتــازل واإلبــراء‪ ،‬وطلــب احلجــز والتنفيــذ‪.‬‬\n‫ا‪ .‬ه ـ ولــم حتضــر املدعــى عليهــا‪ ،......:‬وال مــن ميثلهــا ولــم يظهــر تبلغهــا‬\n‫قضية مقيدة‬‫ّ‬      ‫مبوعــد هــذه اجللســة‪ ،‬ثــم ادعــى األول قائــا‪ :‬لدى موكلــي‬\n‫يف احملكمــة برقــم‪ 3143889 :‬يف‪1431/5/6 :‬ه ـ محالــة للمكتــب‬\n‫القضائــي الســادس والعشــرون‪ ،‬واملتضمنــة‪ :‬تعاقــد موكلــي مــع املدعى‬\n‫ا عنهــا يف جميــع الدعــاوى واألعمــال‬      ‫عليهــا أن يكــون محاميـ ًا ووكيـ ً‬\n‫املتعلقــة بالنزاعــات الناشــئة عــن تركــة مورثهــا‪...... :‬فيمــا بينهــا وبــن‬\n‫باقــي الورثــة اآلخريــن‪ ،‬ومت توقيــع اتفاقيتــان بينهمــا‪ ،‬وقــد التزمــت‬\n‫املدعــى عليهــا بدفــع كامــل أتعــاب موكلــي ســواء انتهــت النزاعــات مــع‬\n\n                                                                                       ‫‪302‬‬\n\f      ‫الورثــة عــن طريــق الصلــح أو التحكيــم أو احلكــم القضائــي وســواء مت‬\n      ‫الصلــح عــن طريــق موكلــي أو بدونــه‪ ،‬ونســبة األتعــاب املتفــق عليهــا‬\n      ‫يف العقــد خمســة يف املئــة مــن القيمــة الفعليــة حلصــة املدعــى عليهــا مــن‬\n      ‫تركــة مورثهــا‪ ،‬وقــد أنهــت املدعــى عليهــا النزاعــات املتعلقــة بالتركــة‬\n      ‫كلهــا صلحــا مــع الورثــة مــن دون الرجــوع ملوكلــي‪ ،‬وقــد تسـلّم موكلي‬\n      ‫مبلغــا قــدره‪ :‬أربعــة ماليــن وخمــس مئــة ألــف ريــال وهــي جــزء مــن أتعــاب‬\n      ‫موكلــي‪ ،‬أطلــب إيقــاع احلجــز التحفظــي عاجــا علــى حصــص املدعــى‬\n      ‫عليهــا مــن شــركة ‪ ...‬ورقــم ســجلها التجــاري‪ ،)......( :‬وشــركة ‪......‬‬\n      ‫لالســتثمار الصناعــي ورقــم ســجلها التجــاري‪ ،)......( :‬هكــذا ادعــى‪.‬‬\n      ‫فبنــاء علــى مــا ســلف‪ ،‬وحيــث لــم يظهــر مــا يوجــب احلجــز الــذي يطلبــه‬\n      ‫املدعــي وكالــة‪ ،‬وألن األصــل عــدم احلجــز إال بعــد ثبــوت احلــق‪ ،‬وملــا‬\n      ‫يف احلجــز ـ مــع عــدم موجبــه ـ مــن اإلضــرار باحملجــوز عليــه‪ ،‬والضــرر‬\n      ‫ممنــوع لقولــه ـ صلــى اهلل عليــه وســلم ـ‪( :‬ال ضــرر وال ضــرار)‪ ،‬لذلــك‬\n      ‫فقــد رددت طلــب املدعــي‪ ،‬وبذلــك قضيــت‪ .‬وبإعــان احلكــم قــرر‬\n      ‫املدعــي وكالــة اعتراضــه واســتعد بتقــدمي الئحــة اعتراضيــة‪ ،‬فجــرى‬\n      ‫تســليمه نســخة مــن احلكــم‪ ،‬ولــه احلــق يف تقــدمي اعتراضــه خــال ثالثــن‬\n      ‫يوم ـ ًا اعتبــار ًا مــن هــذا اليــوم‪ ،‬وإذا تأخــر عــن هــذه املـ ّـدة احملــددة ولــم‬\n      ‫يقــدم الئحتــه ســقط حقــه يف االعتــراض بطلــب االســتئناف واكتســب‬\n      ‫القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                         ‫ّ‬          ‫احلكــم‬\n                                     ‫آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/05/01 :‬ه ـ‬\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n\n\n‫‪303‬‬\n\f‫رئيــس احملكمــة العامــة املســاعد بجــدة برقــم ‪ 34/1011253‬وتاريــخ‬\n‫‪1434/06/11‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪......‬‬\n‫باحملكمــة العامــة مبحافظــة جــدة املســجل برقــم ‪ 34202987‬وتاريــخ‬\n‫‪1434/05/01‬ه ـ املتضمــن دعــوى ‪ ......‬ضــد ‪ ،......‬وبدراســة الصــك‬\n‫وص ــورة ضبط ــه والئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‬\n‫واهلل املوفــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪304‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":301,"source_page_end":304,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a5e0f1ee82bfed91e69b129edb17f630232337cb26d9795ea4aa5377dced0cd4","normalized_text_hash":"733b4c14f355e2d78a571c0b862b2111c6257bd24464f20a6ac5b370e2c155ad","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p301-34202987"},{"id":"97fe4972-4180-5ff0-b106-8233a3f78954","document_type":"judgment","category":"judicial","subcategory":"general","title":"أتعاب محاماة -مطالبة بأتعاب محاماة -األصل عدم السداد - إقرار الورثة بتوقيع مورثهم على عقد االتفاق -التزام املورث دين ينتقل لتركته -الدين مقدم على قسمة التركة -بيع عقار املورث لسداد مستحقات الدائن.","document_number":"34194135","case_number":"33418167","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"أتعاب محاماة -مطالبة بأتعاب محاماة -األصل عدم السداد - إقرار الورثة بتوقيع مورثهم على عقد االتفاق -التزام املورث دين ينتقل لتركته -الدين مقدم على قسمة التركة -بيع عقار املورث لسداد مستحقات الدائن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34194135 :‬تاريخه‪1434/4/22 :‬هـ‬\n                         ‫رقم الدعوى‪33418167 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3433197‬تاريخه‪1434/10/15 :‬هـ‬\n\n\n      ‫أتعــاب محامــاة ‪ -‬مطالبــة بأتعــاب محامــاة ‪ -‬األصــل عــدم الســداد ‪-‬‬\n      ‫إقــرار الورثــة بتوقيــع مورثهــم علــى عقــد االتفــاق ‪ -‬التــزام املــورث ديــن‬\n      ‫ينتقــل لتركتــه ‪ -‬الديــن مقــدم علــى قســمة التركــة ‪ -‬بيــع عقــار‬\n                                                ‫املــورث لســداد مســتحقات الدائــن‪.‬‬\n\n\n\n\n                          ‫‪ .1‬قوله تعالى {من بعد وصية يوصى بها أو دين} ‪.‬‬\n                   ‫‪ .2‬قوله صلى اهلل عليه وسلم ( املسلمون على شروطهم ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة ضــد املدعــى عليهــم مبطالبتهــم بأتعــاب احملامــاة‬\n      ‫وقدرهــا ‪ %10‬باملائــة مــن قيمــة العقــارات ومقــدم أتعــاب قــدره خمســة‬\n      ‫آالف ريــال ‪ -‬حيــث تعاقــد مــورث املدعــى عليهــم مــع مــوكل املدعــي‬\n      ‫علــى أن يترافــع عنــه يف مطالبــة أوالده املدعــى عليهــم يف إثبــات ملكيتــه‬\n      ‫للعقــارات املســجلة باســم زوجتــه والدتهــم حيــث توفيــت زوجتــه قبــل‬\n      ‫وفاتــه والعقــارات باســمها ألنــه أجنبــي ال يســتطيع تســجيل العقــارات‬\n      ‫باســمه وأنكــره املدعــى عليهــم ومت احلكــم لــه بإثبــات ملكيتــه‬\n      ‫للعقــارات ولكونــه غيــر ســعودي فقــد حكــم ببيــع العقــارات باملــزاد‬\n      ‫العلنــي وتســليم قيمتهــا للمدعــي وتخصــم منهــا عشــرة باملائــة لصالــح‬\n\n‫‪305‬‬\n\f‫الدولــة ويكــون ملــوكل املدعــي ‪ %10‬باملائــة مــن قيمــة العقــارات لقــاء‬\n‫أتعابــه ‪ -‬أجــاب املدعــى عليهــم باملصادقــة علــى الدعــوى ماعــدا االتفــاق‬\n‫الــذي بــن مورثهــم ومــوكل املدعــي ‪ -‬صــادق املدعــى عليهــم علــى توقيــع‬\n‫والدهــم علــى العقــد ‪ -‬حضــر املدعــي أصالــة وحلــف اليمــن علــى أنــه لــم‬\n‫يســتلم ســوى عشــرة آالف مــن مقــدم األتعــاب ‪ -‬وألن منصــوص العقــد‬\n‫املبــرم بــن املدعــي وبــن مــورث املدعــى عليهــم ينــص علــى أن أتعــاب‬\n‫الطــرف األول الــذي هــو املدعــي عــن القضيــة عشــرة يف املائــة مــن قيمــة‬\n‫العقــارات ومقــدم أتعــاب خمســة عشــر ألــف ريــال ‪ -‬مبــا أن العقــد أبــرم‬\n‫مــع مورثهــم يف قضيــة مقامــة منــه ضدهــم ومــن البديهــي بــأن ينكــروا‬\n‫ويجادلــوا يف املوضــوع مــا دام أن احلكــم مت ضدهــم بإثبــات ملكيــة‬\n‫والدهــم للعقــارات املشــار إليهــا أعــاه إال أن املدعــى عليهمــا أصالــة‬\n‫ووكالــة أقــرا بــأن التوقيــع يف العقــد هــو توقيــع مورثهــم ‪ -‬وألن مــن‬\n‫أبــرم معــه العقــد قــد تــويف واألصــل هــو عــدم اســتالم املدعــي حقــه مــن‬\n‫أتعــاب القضيــة وأقــر بأنــه لــم يســتلم ســوى عشــرة آالف ريــال واملدعــى‬\n‫عليهمــا أصالــة ووكالــة ال يعلمــون شــيئا عــن ذلــك وقــد حلــف اليمــن‬\n‫الشــرعية بعــد اإلذن لــه بذلــك بأنــه لــم يســتلم مــن مقــدم األتعــاب ســوى‬\n‫عشــرة آالف ريــال ‪ -‬ولقــول النبــي صلــى اهلل عليــه وســلم « املســلمون‬\n‫علــى شــروطهم « ومــا مت االتفــاق فيــه يعتبــر مــن قبيــل الديــن والديــن‬\n‫مقــدم علــى قســمة التركــة لقولــه تعالــى ‪ « :‬مــن بعــد وصيــة يوصــى بهــا‬\n‫أو ديــن « ال ســيما وأن ملــورث املدعــى عليهــم أمــواال ومــن ذلــك العقــارات‬\n‫التــي حكــم لــه بهــا واحملكــوم ببيعهــا باملــزاد العلنــي ‪ -‬احلكــم مبــا‬\n‫يلــي‪ :‬أوال ‪ :‬إلــزام الورثــة بدفــع مبلــغ وقــدره خمســة آالف ريــال للمدعــي‬\n‫أصالــة ثاني ـ ًا ‪ :‬ثبــت بــأن للمدعــي عشــرة يف املائــة مــن قيمــة العقــارات‬\n\n\n                                                                                     ‫‪306‬‬\n\f      ‫املشــار إليهــا أعــاه تخصــم بعــد بيعهــا باملــزاد العلنــي وتســلم لــه ‪ -‬قنــع‬\n      ‫املدعــي واعتــرض املدعــى عليهــم بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n          ‫احلقوقيــة الرابعــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n      ‫فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة وبنــاء‬\n      ‫علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n      ‫املكرمــة برقــم ‪ 33418167‬يف ‪1433/6/22‬ه ـ املقيــدة يف احملكمــة‬\n      ‫برقــم ‪ 331171374‬يف ‪1433/6/22‬ه ـ ففــي يوم األحد ‪1434/4/21‬هـ‬\n      ‫الســاعة التاســعة صباحــا افتتحــت اجللســة للنظــر يف دعــوى ‪ ....‬ضــد كل‬\n      ‫مــن ‪....‬و‪......‬و‪ ....‬و‪ ....‬و‪ ....‬و‪ ....‬و‪ ....‬أوالد ‪ ....‬وفيهــا حضــر ‪....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬بالوكالــة عــن املدعــي ‪....‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل يف الغرفــة التجاريــة‬\n      ‫مبكــة برقــم ‪ 33193356‬يف ‪1433/7/26‬ه ـ واملخــول لــه يف الوكالــة‬\n      ‫حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار وطلــب اليمــن ‪ ...‬الخ وحضر‬\n      ‫حلضــوره كل مــن ‪....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪....‬و‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪....‬باألصالــة عــن‬\n      ‫نفســه وبالوكالــة عــن ‪....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بغــرب مكــة برقــم ‪ 34423432‬يف ‪1434/4/7‬ه ـ واملخــول لــه يف‬\n      ‫الوكالــة حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح ‪ ...‬الــخ‬\n      ‫وبالوكالــة عــن ‪ ....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بغــرب مكــة برقــم ‪ 33215238‬يف ‪1433/8/7‬ه ـ واملخــول لــه يف‬\n\n‫‪307‬‬\n\f‫الوكالــة حــق املرافعــة واملدافعــة والصلــح ‪ ...‬الــخ وبالوكالــة عــن ‪....‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بغــرب مكــة‬\n‫برقــم ‪ 33215203‬يف ‪1433/8/7‬ه ـ واملخــول لــه يف الوكالــة حــق‬\n‫املرافعــة واملدافعــة والصلــح ‪ ...‬الــخ وبالوكالــة عــن ‪....‬بصفتــه الوكيــل‬\n‫الشــرعي عــن ‪....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بالطائــف برقــم ‪ 11802‬يف ‪1427/3/17‬ه ـ واملخــول لــه يف الوكالــة‬\n‫حــق املرافعــة واملدافعــة والصلــح ‪ ...‬الــخ واملدعــى عليهــم أصالــة ووكالــة‬\n‫مــع ‪....‬هــم جميعــا ورثــة ‪....‬مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 33186515‬يف ‪1433/4/12‬ه ـ وبســؤال املدعــي‬\n‫وكالــة عــن دعــواه ادعــى قائــا ‪ :‬لقــد اتفــق موكلــي مــع مــورث املدعــى‬\n‫عليهــم ‪....‬املتوفــى بتاريــخ ‪1433/3/19‬ه ـ واملنحصــر ورثتــه يف أوالده‬\n‫البالغــن مــن زوجتــه املتوفــاة ‪ ....‬وهــم كل مــن ‪....‬و‪....‬و‪ ....‬و‪ ....‬و‪ ....‬و‪....‬‬\n‫و‪ ....‬وذلــك مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة‬\n‫برقــم ‪ 33186515‬يف ‪1433/4/12‬ه ـ علــى أن يقــوم بالترافــع نيابــة عنــه‬\n‫بصفتــه ميلــك مكتبــا لالستشــارات القانونيــة والشــرعية واحملامــاة‬\n‫املرخــص لــه مــن وزارة العــدل مبوجــب التصريــح رقــم ( ‪ ) ......‬وذلــك يف‬\n‫مطالبــة أوالده املدعــى عليهــم كل مــن ‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪....‬يف إثبــات‬\n‫ملكيتــه للعقــارات املســجلة باســم زوجتــه املتوفــاة قبلــه ‪ ....‬وهــي ثالثــة‬\n‫عقــارات األول ‪ :‬العمــارة الواقعــة مبكــة حــي ‪ ....‬رقــم القطعــة (‪)......‬‬\n‫مبوجــب الصــك الصــادر مــن كتابــة العــدل األولــى مبكــة املكرمــة‬\n‫برقــم ‪/2315‬ب وتاريــخ ‪1402/8/22‬ه ـ املكونــة مــن بــدروم وأربعــة‬\n‫أدوار والثانــي‪ :‬قطعــة األرض رقــم القطعــة (‪ )111‬اململوكــة بالصــك‬\n‫الصادر من كتابة العدل األولى مبكة املكرمة برقم ‪/2/5/1371‬ب‬\n\n\n                                                                                        ‫‪308‬‬\n\f      ‫وتاريــخ ‪1403/6/27‬ه ـ والثالــث ‪ :‬الــدار اململوكــة بالصــك الصــادر مــن‬\n      ‫كتابــة عــدل الطائــف برقــم ‪ 4/687‬وتاريــخ ‪1475/9/3‬ه ـ كونــه ال‬\n      ‫يحــق لــه التملــك نظام ـ ًا ألنــه غيــر ســعودي اجلنســية فقــد قــام بتســجيل‬\n      ‫جميــع تلــك العقــارات باســم زوجتــه ‪ ....‬ســعودية اجلنســية مبوجب الســجل‬\n      ‫املدنــي رقــم ‪ ....‬والتــي توفيــت قبلــه وانحصــر ورثتهــا يف زوجهــا ‪....‬‬\n      ‫وأوالدهــا منــه املدعــى عليهــم حيــث أنكــر املدعــى عليهــم ملكيــة‬\n      ‫والدهــم للعقــارات املشــار إليهــا وإمنــا هــي ملــك لوالدتهــم وقــد نظــرت‬\n      ‫القضيــة لديكــم وانتهــت بالصــك الصــادر مــن هــذه احملكمــة برقــم‬\n      ‫‪ 32338413‬يف ‪1432/11/27‬ه ـ املصــدق مــن محكمــة االســتئناف‬\n      ‫مبكــة املكرمــة بالقــرار رقــم ‪ 33279727‬يف ‪1433/6/3‬ه ـ وذلــك‬\n      ‫بإثبــات ملكيــة العقــارات لوالدهــم ‪ ....‬ولكونــه غيــر ســعودي فقــد‬\n      ‫حكــم بــأن تبــاع باملــزاد العلنــي وتســلم قيمتهــا للمدعــي ويخصــم منهــا‬\n      ‫عشــرة يف املائــة لصالــح الدولــة وذلــك بحيــث يكــون ملوكلــي لقــاء‬\n      ‫أتعابــه عشــرة يف املائــة مــن قيمــة العقــارات املــراد إثبــات ملكيتهــا‬\n      ‫باإلضافــة إلــى خمســة عشــر ألــف ريــال مقــدم أتعــاب لــم يســتلم منهــا‬\n      ‫ســوى عشــرة آالف ريــال ومبــا أنــه قــد تــويف وانحصــر ورثتــه يف أوالده‬\n      ‫املدعــى عليهــم لــذا فــإن موكلــي يطلــب إثبــات حقــه يف العقــارات‬\n      ‫املذكــورة بنســبة قدرهــا عشــرة يف املائــة مــن قيمتهــا والباقــي مــن مقــدم‬\n      ‫األتعــاب وقــدره خمســة آالف ريــال هــذه دعــواي وبعــرض الدعــوى علــى‬\n      ‫املدعــى عليهمــا أصالــة ووكالــة أجابــا قائلــن ‪ :‬مــا ذكــره املدعــي‬\n      ‫وكالــة مــن وفــاة مورثنــا ‪....‬بتاريــخ ‪1433/3/19‬ه ـ وانحصــار ورثتــه يف‬\n      ‫أوالده البالغــن مــن زوجتــه املتوفــاة ‪ ....‬وهــم كل مــن‬\n      ‫‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪ ....‬وذلــك مبوجــب صــك حصــر الورثــة الصــادر‬\n\n\n‫‪309‬‬\n\f‫مــن هــذه احملكمــة برقــم ‪ 33186515‬يف ‪1433/4/12‬ه ـ ووجود دعوى‬\n‫ســابقا بيننــا وبينــه حــول ملكيــة العقــارات املشــار إليهــا آنفــا وانتهائهــا‬\n‫بالصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 32338413‬يف‬\n‫‪1432/11/27‬ه ـ املصــدق مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫بالقــرار رقــم ‪ 33279727‬يف ‪1433/6/3‬ه ـ بإثبــات ملكيــة والدنــا‬\n‫للعقــارات فهــذا كلــه صحيــح وأمــا مــن ناحيــة وجــود عقــد بــن مورثنــا‬\n‫وبــن املدعــي أصالــة حــول أتعــاب القضيــة املنظــورة لديكــم فهــذا ال‬\n‫نعلــم عنــه إال أننــا قــد اطلعنــا علــى عقــد األتعــاب فوجدنــا مــا يلــي ‪ :‬أوال‬\n‫‪ :‬ال ينــص العقــد صراحــة ضمــن بنــوده علــى إلــزام ورثــة املتعاقــد الوالــد‬\n‫‪ .... /‬بالتســديد أو دفــع األتعــاب بعــد وفاتــه للمكتــب املذكــور أو مــن‬\n‫ميثلــه ثانيــا ‪ :‬نــص البنــد الرابــع ( الفقــرة الثانيــة ) مــن العقــد علــى أن ‪( :‬‬\n‫باقــي األتعــاب بعــد االنتهــاء مــن القضيــة ) ولــم ينــص العقــد علــى أن‬\n‫باقــي األتعــاب بعــد إصــدار احلكــم وحيــث إن وفــاة املتعاقــد حدثــت‬\n‫بتاريــخ ‪1433/3/19‬ه ـ أي قبــل أن يكتســب احلكــم صفتــه القطعيــة‬\n‫بتاريــخ ‪1433/6/3‬ه ـ واالنتهــاء مــن القضيــة أي أن إرثــه قــد عــاد لورثتــه‬\n‫بتاريــخ وفاتــه أي قبــل االنتهــاء مــن القضيــة واعتبــرت وكالــة الوكيــل‬\n‫الغيــة بوفــاة املــوكل لــذا فإنــه ال عالقــة للورثــة إطالقــا بهــذا العقــد ومــا‬\n‫تضمنــه مــن بنــود واتفاقــات بعــد وفــاة املتعاقــد ثالثــا ‪ :‬إن العقــد أبــرم مــع‬\n‫مورثنــا ‪....‬ومكتــب ‪....‬ومت إدخــال توقيــع أحــد ورثــة املتعاقــد ضمــن‬\n‫العقــد وهــي األخــت ‪ ....‬دون ذكــر عالقتهــا أو اإلشــارة ألســباب توقيعهــا‬\n‫ضمــن نصــوص العقــد فــإذا كان ســبب توقيعهــا على العقد هو الشــهادة‬\n‫أو إقرارهــا وموافقتهــا وتأييدهــا علــى العقــد املبــرم ومــا تضمنــه مــن‬\n‫بنــود بــن الطرفــن فــإن مطالبــة املدعــي تــؤول ألختنــا ‪ ....‬مــن نصيبهــا‬\n\n\n                                                                                           ‫‪310‬‬\n\f      ‫الشــرعي وليــس مــن نصيــب باقــي الورثــة هكــذا أجابــا وقــررا وبعــرض‬\n      ‫ذلــك علــى املدعــي وكالــة قــال ‪ :‬أوال ‪ :‬إن مــا مت االتفــاق بــن موكلــي‬\n      ‫وبــن مــورث املدعــى عليهــم يعتبــر مــا أجنــزه ديــن يف ذمتــه يلــزم ورثتــه‬\n      ‫مــن بعــده ومــن املعلــوم أن الديــون تقضــى قبــل تصفيــة التركــة لقولــه‬\n      ‫تعالــى‪ « :‬مــن بعــد وصيــة يوصــي بهــا أو ديــن « ثانيــا ‪ :‬إن أخــت املدعــى‬\n      ‫عليهــم ‪ ....‬مقــرة بالعقــد وهــي شــاهدة عليــه وقــد قامــت بتوكيــل‬\n      ‫موكلــي بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة يف الطائــف‬\n      ‫برقــم ‪ 36581‬يف ‪1433/6/30‬ه ـ هكــذا قــرر هــذا وقــد جــرى مــن‬\n      ‫االطــاع علــى مــا يلــي ‪ :‬أوال ‪ :‬صــك حصــر الورثــة الصــادر مــن هــذه‬\n      ‫احملكمــة برقــم ‪ 33186515‬يف ‪1433/4/12‬ه ـ فوجــد يتضمــن ثبــوت‬\n      ‫وفــاة ‪....‬بتاريــخ ‪1433/3/19‬ه ـ وانحصــار ورثتــه يف أوالده البالغــن مــن‬\n      ‫زوجتــه املتوفــاة ‪....‬وهــم كل مــن ‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪....‬ال وارث لــه‬\n      ‫ســواهم ثانيــا ‪ :‬الصــادر مــن هــذه احملكمــة برقــم ‪ 32338413‬يف‬\n      ‫‪1432/11/27‬ه ـ املصــدق مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫بالقــرار رقــم ‪ 33279727‬يف ‪1433/6/3‬ه ـ فوجــد يتضمــن دعــوى‬\n      ‫مقامــة مــن ‪....‬ضــد أوالده كل مــن ‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪....‬و‪ ....‬أوالد ‪......‬‬\n      ‫يف ملكيــة عقــارات مســجلة باســم زوجتــه ‪ ......‬وقــد تضمــن الصــك مــا‬\n      ‫يلــي ‪ :‬أ‪ -‬أن الــذي قــام بالترافــع يف القضيــة نيابــة عــن املدعــي مــن بدايــة‬\n      ‫القضيــة وحتــى انتهائهــا هــو املدعــي ‪ - ......‬أن ‪ ......‬مقــرة بدعــوى املدعي‬\n      ‫وأن العقــارات ملــك لوالدهــا وقــد أشــير فيــه إلــى وكالــة ‪ ......‬للمدعــي‬\n      ‫‪ ......‬ج ‪ -‬صــدر احلكــم لصالــح املدعــي ‪ ......‬وقــد تــويف بعــد احلكــم‬\n      ‫وقبــل اكتســابه القطعيــة وقــد أشــير إلــى ذلــك يف صــك احلكــم ثالثــا ‪:‬‬\n      ‫عقــد األتعــاب املبــرم بــن احملامــي ‪ ...... /‬وبــن ‪ ......‬فوجــد يتضمــن‬\n\n\n‫‪311‬‬\n\f‫االتفــاق بــن بــن احملامــي ‪ ...... /‬وبــن ‪ ......‬علــى أن يقــوم الطــرف األول‬\n‫بتولــي القضيــة اخلاصــة بإثبــات ملكيــة الطــرف الثانــي للعقــارات التــي‬\n‫باســم زوجتــه املتوفــاة ‪ ......‬وقــد نــص يف البنــد الرابــع منــه علــى أن أتعــاب‬\n‫الطــرف األول عــن هــذه القضيــة عشــرة يف املائــة مــن قيمــة العقــارات‬\n‫املــراد إثبــات ملكيتهــا علــى النحــو اآلتــي ‪ :‬أ‪ -‬مقــدم أتعــاب ‪ :‬خمســة‬\n‫عشــر ألــف ريــال ب ‪ -‬باقــي األتعــاب ‪ :‬بعــد االنتهــاء مــن القضيــة ومذيــل‬\n‫بتوقيــع الطرفــن كل مــن ‪ ......‬و‪ ......‬وبســؤال املدعــى عليهمــا أصالــة‬\n‫ووكالــة عــن توقيــع والدهمــا يف العقــد وصحتــه فقــاال ‪ :‬إن هــذا هــو‬\n‫توقيــع والدنــا وال ننكــره هكــذا قــررا وقــد جــرى إرفــاق صــور ممــا‬\n‫أشــير إليــه يف املعاملــة وقــد حضــر يف هــذه اجللســة املدعــي أصالــة ‪......‬‬\n‫ســعودي اجلنســية مبوجب الســجل املدني رقم ‪ ......‬وبســؤاله عما اســتلمه‬\n‫مــن مقــدم األتعــاب فقــال ‪ :‬إن مقــدم األتعــاب خمســة عشــر ألــف ريــال لــم‬\n‫أســتلم منهــا ســوى عشــرة آالف ريــال هكــذا قــرر وبعــرض ذلــك علــى‬\n‫املدعــى عليهمــا أصالــة ووكالــة فقــاال ‪ :‬ال نعلــم عــن ذلــك شــيئا وبطلــب‬\n‫اليمــن مــن املدعــي علــى ذلــك اســتعد بذلــك ثــم أذنــت لــه فحلــف قائــا ‪:‬‬\n‫« واهلل العظيــم الــذي ال إلــه إال هــو إننــي لــم أســتلم مــن مقــدم األتعــاب يف‬\n‫العقــد املبــرم بينــي وبــن ‪ ......‬بخصــوص ملكيتــه للعقــارات إال عشــرة‬\n‫آالف ريــال واهلل العظيــم واهلل العظيــم « هكــذا حلــف فجــرى ســؤال‬\n‫الطرفــن هــل لديكمــا مــا تريــدان إضافتــه ؟ فقــاال ‪ :‬ليــس لدينــا ســوى‬\n‫مــا قدمنــاه ونطلــب الفصــل يف القضيــة هكــذا قــررا فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وبعد دراســة القضيــة وتأملها وبعد االطالع‬\n‫علــى لفــات املعاملــة ومبــا أن املدعــي يطالــب بإثبــات حقــه يف العقــارات‬\n‫اململوكــة ملورثهــم لقــاء ترافعــه عنــه بنســبة قدرهــا عشــرة يف املائــة مــن‬\n\n\n                                                                                         ‫‪312‬‬\n\f      ‫قيمتهــا وباقــي مقــدم األتعــاب خمســة آالف ريــال وألن منصــوص العقــد‬\n      ‫املبــرم بــن املدعــي وبــن مــورث املدعــى عليهــم ‪ ......‬ينــص علــى أن أتعــاب‬\n      ‫الطــرف األول الــذي هــو املدعــي عــن القضيــة عشــرة يف املائــة مــن قيمــة‬\n      ‫العقــارات ومقــدم أتعــاب خمســة عشــر ألــف ريــال ومبــا أن العقــد أبــرم‬\n      ‫مــع مورثهــم يف قضيــة مقامــة منــه ضدهــم ومــن البديهــي بــأن ينكــروا‬\n      ‫ويجادلــوا يف املوضــوع مــا دام أن احلكــم مت ضدهــم بإثبــات ملكيــة‬\n      ‫والدهــم للعقــارات املشــار إليهــا أعــاه إال أن املدعــى عليهمــا أصالــة‬\n      ‫ووكالــة أقــرا بــأن التوقيــع يف العقــد هــو توقيــع مورثهــم وألن مــن أبــرم‬\n      ‫معــه العقــد قــد تــويف واألصــل هــو عــدم اســتالم املدعــي حقــه مــن أتعــاب‬\n      ‫القضيــة وأقــر بأنــه لــم يســتلم ســوى عشــرة آالف ريــال واملدعــى عليهمــا‬\n      ‫أصالــة ووكالــة ال يعلمــون شــيئا عــن ذلــك وقــد حلــف اليمــن الشــرعية‬\n      ‫بعــد اإلذن لــه بذلــك بأنــه لــم يســتلم مــن مقــدم األتعــاب ســوى عشــرة‬\n      ‫آالف ريــال وألن العقــد شــريعة املتعاقديــن وقــد قــال النبــي صلــى اهلل‬\n      ‫عليــه وســلم « املســلمون علــى شــروطهم « ومــا مت االتفــاق فيــه يعتبــر مــن‬\n      ‫قبيــل الديــن والديــن مقــدم علــى قســمة التركــة لقولــه تعالــى ‪ « :‬مــن‬\n      ‫بعــد وصيــة يوصــي بهــا أو ديــن « ال ســيما وأن ملــورث املدعــى عليهــم‬\n      ‫أمــواال ومــن ذلــك العقــارات التــي حكــم لــه بهــا واحملكــوم ببيعهــا‬\n      ‫باملــزاد العلنــي لذلــك كلــه فقــد قــررت مــا يلــي ‪ :‬أوال ‪ :‬إلــزام ورثــة ‪......‬‬\n      ‫بدفــع مبلــغ وقــدره خمســة آالف ريــال للمدعــي أصالــة ثانيــا ‪ :‬ثبــت لــدي‬\n      ‫بــأن للمدعــي عشــرة يف املائــة مــن قيمــة العقــارات املشــار إليهــا أعــاه‬\n      ‫تخصــم بعــد بيعهــا باملــزاد العلنــي وتســلم لــه ومبــا تقــدم حكمــت‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــي القناعــة بــه واملدعــى‬\n      ‫عليهمــا أصالــة ووكالــة عــدم القناعــة وطلبــا االســتئناف بالئحــة‬\n\n\n‫‪313‬‬\n\f‫اعتراضيــة فجــرى إفهامهمــا بــأن عليهمــا التقــدم للمحكمــة يــوم‬\n‫الثالثــاء ‪1434/4/30‬ه ـ الســتالم نســخة مــن صــك احلكــم لتقــدمي‬\n‫اعتراضهمــا عليــه خــال ثالثــن يومــا مــن التاريــخ املذكــور وإذا لــم‬\n‫يتقدمــا بذلــك خــال املــدة املذكــورة فسيســقط حقهمــا بطلــب‬\n‫االســتئناف وسيكتســب احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى‬\n ‫اهلل على نبينا محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/4/21‬هـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد ‪ :‬ففــي يــوم األربعــاء ‪1434/9/9‬ه ـ افتتحــت‬\n‫اجللســة وكان قــد جــرى بعــث املعاملــة حملكمــة االســتئناف مبكــة‬\n‫املكرمــة ثــم عــادت إلينــا بخطــاب فضيلــة رئيــس محكمــة االســتئناف‬\n‫مبكة املكرمة املكلف برقم ‪ 331171374‬يف ‪1434/8/2‬هـ وبرفقه‬\n‫قــرار الدائــرة احلقوقيــة الرابعــة برقــم ‪ 34280286‬يف ‪1434/7/26‬ه ـ‬\n‫املتضمــن بعــد املقدمــة مــا نصــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــرر باألكثريــة إعــادة املعاملــة لفضيلــة‬\n‫حاكمهــا ملالحظــة أن فضيلــة ناضــر القضيــة قــد حكــم بإلــزام ورثــة‬\n‫املتوفــى ‪ ......‬بدفــع مبلــغ خمســة آالف ريــال للمدعــي أصالــة وحكمــه‬\n‫هــذا محــل نظــر حيــث لــم يفصــل فضيلتــه حكمــه ويبــن بــأن هــذا‬\n‫املبلــغ مــن التركــة والبــد مــن ذلــك‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬قاضــي اســتئناف ‪ ......‬توقيعــه‬\n‫ختمــه الشــخصي قاضــي اســتئناف ‪ ......‬توقيعــه ختمــه الشــخصي رئيــس‬\n‫الدائــرة ‪ ......‬موافــق علــى احلكــم توقيعــه ختمــه الشــخصي أ‪.‬ه ـ وعليــه‬\n‫أجيــب أصحــاب الفضيلــة وفقنــي اهلل وإياهــم للعلــم النافــع والعمــل‬\n‫الصالــح بــأن املبلــغ مــا دام أنــه يف ذمــة مــورث املدعــى عليهــم فيكــون‬\n‫مــن تركتــه وبعــد اإلجابــة لــم يظهــر لــي ســوى مــا أجريتــه وحكمــت بــه‬\n\n\n                                                                                   ‫‪314‬‬\n\f      ‫وقــررت إعــادة املعاملــة حملكمــة االســتئناف إلكمــال الزمهــا‪ ،‬وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                  ‫يف ‪1434/9/9‬ه ـ‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪ ....../‬القاضــي باحملكمــة العامــة مكــة املكرمــة واملســجل‬\n      ‫بعدد‪34194135‬وتاريــخ ‪1434/4/22‬ه ـ املتضمــن دعــوى ‪ ......‬ضــد ورثة‬\n      ‫‪ ......‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد األجــراء‬\n      ‫األخيــر املبنــي علــى قــرار الدائــرة رقــم ‪34280286‬يف ‪1434/7/26‬ه ـ‬\n                    ‫‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪315‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":305,"source_page_end":315,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e7827ecaec2578015e1cfbc080102275b71af4f7e07bddb029765603126fa3b6","normalized_text_hash":"fc3223514574cd45a8b84fcb7734f7bad258d3937f87c7a64230d5183530d8b3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p305-34194135"},{"id":"9e52cb8e-b4cd-54c6-a3d1-95a2fdad1266","document_type":"judgment","category":"judicial","subcategory":"general","title":"أجرة عمل -توجيه اليمن على املدعى عليه -حلف اليمن النافية للدعوى -احلكم برد الدعوى.","document_number":"34305617","case_number":"34217704","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/25","year":"1434","subject":"أجرة عمل -توجيه اليمن على املدعى عليه -حلف اليمن النافية للدعوى -احلكم برد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34305617:‬تاريخه‪1434/8/25:‬هـ‬\n                  ‫رقم الدعوى‪34217704:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34382792‬تاريخه‪1434/12/19 :‬هـ‬\n\n\n‫أجــرة عمــل ‪ -‬توجيــه اليمــن علــى املدعــى عليــه ‪ -‬حلــف اليمــن النافية‬\n                                          ‫للدعــوى ‪ -‬احلكــم بــرد الدعوى‪.‬‬\n\n\n\n\n      ‫‪ .1‬قوله صلى اهلل عليه وسلم (ولكن اليمني على املدعى عليه) ‪.‬‬\n         ‫‪ .2‬املادة ‪ 55‬من نظام املرافعات الشرعية والئحتها التنفيذية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه مت‬\n‫االتفــاق مــع املدعــى عليــه علــى أن يعمــل لديــه بوظيفــة معقــب إلجنــاز‬\n‫أعمالــه مــن تســديد فواتيــر الكهربــاء والهواتــف وعمل مســيرات رواتب‬\n‫للعمــال ودفــع رواتبهــم ودفــع اإليجــارات وحتصيــل اإليصــاالت ودفــع‬\n‫أقســاط شــركة ‪ ...‬ووكيــل شــرعي عــن العمالــة املوجــودة لديــه مببلــغ‬\n‫شــهري قــدره ألــف وخمســمائة ريــال وقــد عمــل املدعــي لديــه ملــدة ســت‬\n‫ســنوات وطــول هــذه املــدة لــم يســتلم منــه الرواتــب الشــهرية وقدرهــا مائــة‬\n‫وثمانيــة آالف ريــال ويطلــب إلــزام املدعــى عليــه بدفــع الرواتــب املتأخــرة‬\n‫املشــار إليهــا ‪ -‬لــم يحضــر املدعــى عليــه مــع تبلغــه نظامـ ًا فجــرى الســير‬\n‫يف الدعــوى غيابيـ ًا بنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية ‪-‬‬\n‫ليــس للمدعــي بينــة علــى دعــواه ويطلــب ميــن املدعــى عليــه علــى نفيهــا‬\n\n                                                                                      ‫‪316‬‬\n\f      ‫ورفعــت اجللســة لتبليــغ املدعــى عليــه بتوجــه اليمــن عليــه وأنــه إذا تخلــف‬\n      ‫ال وســوف يقضــى عليــه بالنكــول‬    ‫بغيــر عــذر تقبلــه احملكمــة عـ ّـد نــاك ً‬\n      ‫بنــاء علــى املــادة ‪ 4/55‬مــن نظــام املرافعــات الشــرعية ‪ -‬حضــر املدعــى‬\n      ‫عليــه يف اجللســة التاليــة وأجــاب باملصادقــة علــى التعاقــد مــع املدعــى‬\n      ‫عليــه بــأن يعمــل معقــب لــه وأنــه اســتلم حقوقــه كاملــة وأنكــر تضمــن‬\n      ‫االتفــاق صــرف راتــب شــهري للمدعــي ‪ -‬حلــف املدعــى عليــه اليمــن‬\n      ‫النافيــة بالتعاقــد مــع املدعــي علــى صــرف راتــب شــهري لــه وأن ليــس‬\n      ‫بذمتــه املبلــغ املدعــى بــه ‪ -‬وإلنــكار املدعــى عليــه ملــا جــاء يف الدعــوى‬\n      ‫ولطلــب املدعــي ميــن املدعــى عليــه ولقولــه صلــى اهلل عليــه وســلم‪:‬‬\n      ‫(ولكــن اليمــن علــى املدعــى عليــه ) ولبــذل املدعــى عليــه اليمــن علــى‬\n      ‫نفــي دعــوى املدعــي ملــا تقــدم صــدر احلكــم بــرد دعــوى املدعــي ‪ -‬قنــع‬\n      ‫املدعــى عليــه باحلكــم واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم‬\n      ‫مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة االســتئناف مبنطقــة مكــة‬\n                                                                             ‫املكرمــة‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪......‬القاضــي يف احملكمــة العامــة‬\n      ‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة القائــم بعمــل رئيــس‬\n      ‫احملكمــة العامــة بينبــع برقــم ‪ 34217704‬وتاريــخ ‪ 1434/05/11‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 341158046‬وتاريــخ ‪ 1434/05/11‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1434/07/01‬ه ـ افتتحــت اجللســة وفيهــا حضر ‪......‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي ‪......‬وادعــى علــى الغائــب عــن‬\n      ‫ا يف دعــواه إنــه يف شــهر جمــادى األول‬ ‫مجلــس احلكــم الشــرعي ‪......‬قائـ ً‬\n\n‫‪317‬‬\n\f‫مــن عام‪1428‬ه ـ مت االتفــاق بينــي وبــن املدعــى عليــه علــى أن أعمــل لديه‬\n‫بوظيفــة ‪......‬إلجنــاز أعمالــه مــن تســديد فواتيــر الكهربــاء والهواتــف‬\n‫وعمــل مســيرات رواتــب للعمــال ودفع رواتبهم ودفــع اإليجارات وحتصيل‬\n‫اإليصــاالت ودفــع أقســاط شــركة ‪ ...‬ووكيــل شــرعي عــن العمالــة‬\n‫املوجــودة لديــه مببلــغ شــهري قــدره(‪ )1,500‬ألــف وخمســمائة ريــال وقــد‬\n‫عملــت لديــه ملــدة ســتة ســنوات وطــول هــذه املــدة لــم اســتلم منــه الرواتــب‬\n‫الشــهرية وقدرهــا(‪ )108,000‬مائــة وثمانيــة آالف ريــال أطلــب إلــزام‬\n‫املدعــى عليــه بدفــع الرواتــب املتأخــرة وقدرهــا(‪ )108,000‬مائــة وثمانيــة‬\n‫آالف ريــال هكــذا ادعــى ؛ وقــد ســبق طلــب املدعــى عليــه املذكــور‬\n‫ملقابلــة خصمــه شــرع ًا وتبلــغ باملواعيــد نظاميـ ًا ولــم يحضــر كمــا يتضــح‬\n‫مــن مرفقــات املعاملــة وهــي‪ )1(:‬ورقة التبليــغ األولى وفيها حتديد املوعد‬\n‫املــؤرخ يف يــوم الســبت املوافق‪1434/05/25‬ه ـ الســاعة احلاديــة عشــرة‬\n‫وذلــك عــن طريــق محضــر اخلصــوم باحملكمــة واســتلمها رجــل األمــن‬\n‫يف الشــركة ‪)2( ......‬وقــد ســبق الكتابــة لرئيــس محضــري اخلصــوم‬\n‫باحملكمــة باخلطــاب ذي الرقــم‪ 341271299‬وتاريخ‪1434/05/26‬ه ـ‬\n‫لتكليــف املدعــى عليــه باحلضــور للمحكمــة هــذا اليــوم وقــد وردنــا‬\n‫خطابهــم ذي الرقــم‪ 341271299‬وتاريخ‪1434/07/01‬ه ـ وبرفقــه‬\n‫قــرار محضــر اخلصــوم ‪......‬املتضمن(إشــارة خلطــاب املشــرف اإلداري‬\n‫رقــم ‪ ......‬وتاريخ‪1434/05/26‬ه ـ بشــأن إبــاغ املدعــو ‪......‬بأنــه مت‬\n‫الذهــاب إلــى مقــر عمــل املدعــى عليــه بتاريخ‪1434/06/24‬ه ـ وأفــادوا‬\n‫بأنــه غيــر متواجــد اآلن ومت االتصــال عليــه ولــم يجيــب أكثــر مــن مــرة‬\n‫ويف أوقــات مختلفــة ومت الذهــاب مــرة أخــرى بتاريخ‪1434/06/28‬ه ـ‬\n‫وســألت موظــف األمــن عــن املدعــى عليــه وأفــاد بأنــه متواجــد ورفضــوا‬\n\n\n                                                                                       ‫‪318‬‬\n\f      ‫دخولــي إلــى الشــركة لتبليــغ املدعــى عليــه شــخصي ًا ومت االتصــال‬\n      ‫عليــه ولــم يجيــب حــرر احملضــر بتاريخ‪1434/07/01‬هـ)ا‪.‬ه ـ وملــا ســبق‬\n      ‫واســتناد ًا علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية‬\n      ‫ونصهــا‪ (:‬إذا غــاب املدعــى عليــه عــن اجللســة األولــى فيؤجــل النظــر يف‬\n      ‫القضيــة إلــى جلســة الحقــة يبلــغ بهــا املدعــى عليــه ‪ ،‬فــإن غــاب عــن هــذه‬\n      ‫اجللســة أو غــاب عــن جلســة أخــرى دون عــذر تقبلــه احملكمــة فتحكــم‬\n      ‫احملكمــة يف القضيــة ويعــد حكمهــا يف حــق املدعــى عليــه غيابيـ ًا مــا لم‬\n      ‫يكــن غيابــه بعــد قفــل بــاب املرافعــة يف القضيــة فيعــد احلكــم حضوريـ ًا‬\n      ‫) ا‪.‬ه ـ ‪،‬لــذا فقــد قــررت الســير يف نظــر الدعــوى وطلبــت مــن املدعــي‬\n      ‫البينــة التــي تشــهد بصحــة دعــواه فأجــاب بقولــه ليــس لــدي بينــة هكــذا‬\n      ‫أجــاب فأفهمتــه أن لــه ميــن خصمــه علــى نفــي دعــواه فقــال أطلــب ميينــه‬\n      ‫ـاء علــى املــادة ‪ 4/55‬مــن نظــام املرافعــات الشــرعية والئحتهــا‬     ‫لــذا وبنـ ً‬\n      ‫التنفيذيــة ونصهــا (إذا توجهــت اليمــن علــى املدعــى عليــه بعــد ســماع‬\n      ‫الدعــوى فيبلــغ بذلــك حســب إجــراءات التبليــغ ‪ ،‬ويشــعر بوجــوب‬\n      ‫حضــوره ألداء اليمــن وأنــه إذا تخلــف بغيــر عــذر تقبلــه احملكمــة عـ ّـد‬\n      ‫ال وســوف يقضــى عليــه بالنكــول) لــذا فســيتم إشــعار املدعــى‬           ‫نــاك ً‬\n      ‫عليــه بوجــوب حضــوره يف اجللســة القادمــة ألداء اليمــن وأنــه إذا تخلــف‬\n      ‫ال وســوف يقضــى عليــه بالنكــول‬       ‫بغيــر عــذر تقبلــه احملكمــة عـ ّـد نــاك ً‬\n      ‫ويف جلســة أخــرى لــدي أنــا ‪......‬القاضــي يف احملكمــة العامــة بينبــع‬\n      ‫والقائــم بعمــل املكتــب القضائــي اخلامــس عليــه ففــي يــوم اإلثنــن‬\n      ‫املوافــق‪ 1434/08/22‬ه ـ افتحــت اجللســة وفيهــا حضــر املدعــي وحضــر‬\n      ‫حلضــوره املدعــى عليــه ‪......‬ســعودي بالهويــة الوطنيــة رقــم ‪......‬وجــرى‬\n      ‫عــرض الدعــوى علــى املدعــي فصــادق عليهــا ثــم جــرى ســؤال املدعــى‬\n\n\n‫‪319‬‬\n\f‫عليــه عــن الدعــوى فأجــاب ‪ :‬مــا ذكــره املدعــي مــن انــه عمــل معــي يف‬\n‫التعقيــب فصحيــح إال ان ذلــك كان عــن طريــق املكتــب الــذي ميلكــه‬\n‫واســمه مكتــب ‪......‬وقــد ســلمته كامــل حقوقــه امــا مــا يدعيــه مــن‬\n‫راتــب شــهري فغيــر صحيــح ولــم أتعاقــد معــه علــى ذلــك ولســت مســتعد ًا‬\n‫أن أدفــع لــه مــا ادعــى بــه هكــذا أجــاب املدعــى عليــه وبعــرض جوابــه‬\n‫علــى املدعــي قــال ‪ :‬مــا ذكــره املدعــى عليــه غيــر صحيــح والصحيــح مــا‬\n‫ذكرتــه فســالته عــن البينــه علــى دعــواه فقــال ‪ :‬ليــس لــدي بينــه واطلــب‬\n‫ميــن املدعــى عليــه علــى نفــي دعــواي هكــذا قــال وبعــرض ذلــك علــى‬\n‫املدعــى عليــه قــال ‪ :‬إنــي مســتعد ببــذل اليمــن هكــذا قــال فأفهمتــه‬\n‫بخطــورة اليمــن وعظيــم شــانها فقــال‪ :‬انــي احلــف علــى حــق فأذنــت‬\n‫لــه أن يحلــف فحلــف قائ ـاً‪ :‬واهلل العظيــم واهلل العظيــم واهلل العظيــم‬\n‫إنــي لــم أتعاقــد مــع املدعــي هــذا احلاضــر علــى أن يعمــل معــي براتــب‬\n‫‪ 1500‬ريــال شــهري ًا وليــس يف ذمتــي مبلــغ ‪ 108000‬ريــال للمدعــي واهلل‬\n‫العظيــم هكــذا حلــف املدعــى عليــه فبنــاء عليــه وبعــد ســماع الدعــوى‬\n‫واالجابــة واالطــاع علــى اوراق املعاملــة والنــكار املدعــى عليــه ملــا‬\n‫جــاء يف الدعــوى ولطلــب املدعــي ميــن املدعــى عليــه ولقولــه صلــى اهلل‬\n‫عليــه وســلم‪( :‬ولكــن اليمــن علــى املدعــى عليــه ) ولبــذل املدعــى عليــه‬\n‫اليمــن علــى نفــي دعــوى املدعــي لذلــك كلــه فقــد رددت دعــوى املدعــي‬\n‫وأخليــت ســبيل املدعــى عليــه منهــا وبذلــك حكمــت وبعــرض احلكــم‬\n‫علــى املدعــي قــرر اعتراضــه عليــه وأفهــم باملراجعــة يــوم اإلثنــن املوافــق‬\n‫‪1434/8/29‬ه ـ الســتالم نســخة احلكــم لتقــدمي اعتراضــه عليــه ويف‬\n‫حــال مضــت مــدة ثالثــن يومـ ًا ولــم يتقــدم باعتراضــه ولــم يــأت الســتالم‬\n‫نســخة احلكــم فإنــه يســقط حقــه يف طلــب االســتئناف ويكتســب‬\n\n\n                                                                                     ‫‪320‬‬\n\f      ‫احلكــم القطعيــة وبعرضــه علــى املدعــى عليــه قــرر قناعتــه وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف ‪ 1434/08/22‬ه ـ‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى منــا‬\n      ‫االطــاع نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشيخ ‪......‬القاضي باحملكمة العامة بينبع واملسجل بعدد ‪34305617‬‬\n      ‫وتاريــخ ‪ 1434/8/25‬ه ـ املتضمــن دعــوى ‪ ......‬ضــد ‪......‬واحملكــوم فيــه‬\n      ‫مبــادون باطنــه وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم مــع مالحظــة التنبيــه املرفــق وصلــى اهلل‬\n                                     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪321‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":316,"source_page_end":321,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"805994ba41090f469368d597760c0e0403cba16377075ee5e9db31edebdfd3cb","normalized_text_hash":"ef90b6657e1a6cb67ba3eb90831b96163bfd2d97692dedf38d396a7882798d0e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p316-34305617"},{"id":"aac7a6d3-4c63-5333-953d-dcb674b16dd1","document_type":"judgment","category":"judicial","subcategory":"general","title":"استقدام عمالة -سداد قيمة مادفعه املدعى الستقدام املدعى عليها -مترجم لكون املدعى عليها اجنبيه -عدم الرغبه يف العمل لإلصابة بالسكري -األجير اخلاص يضمن بالتعدي أو التفريط -مقاصة قضائية -الزام املدعى عليها بسداد ماغرمه املدعى","document_number":"34291127","case_number":"34289348","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/8","year":"1434","subject":"استقدام عمالة -سداد قيمة مادفعه املدعى الستقدام املدعى عليها -مترجم لكون املدعى عليها اجنبيه -عدم الرغبه يف العمل لإلصابة بالسكري -األجير اخلاص يضمن بالتعدي أو التفريط -مقاصة قضائية -الزام املدعى عليها بسداد ماغرمه املدعى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34291127 :‬تاريخه‪1434/8/8 :‬هـ‬\n                  ‫رقم الدعوى‪34289348 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34315707‬تاريخه‪1434/9/9 :‬هـ‬\n\n\n‫اســتقدام عمالــة ‪ -‬ســداد قيمــة مادفعــه املدعــى الســتقدام املدعــى‬\n‫عليهــا ‪ -‬مترجــم لكــون املدعــى عليهــا اجنبيــه ‪ -‬عــدم الرغبــه يف العمــل‬\n‫لإلصابــة بالســكري ‪ -‬األجيــر اخلــاص يضمــن بالتعــدي أو التفريــط‬\n‫‪ -‬مقاصــة قضائيــة ‪ -‬الــزام املدعــى عليهــا بســداد ماغرمــه املدعــى‬\n                                                               ‫الســتقدامها ‪.‬‬\n\n\n\n                            ‫األجير اخلاص يضمن بالتعدي أو التفريط‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليهــا انــه اســتقدمها للعمــل لديــه كعاملــة‬\n‫منزليــة ملــده ســنتني بالتكلفــة املذكــورة يف دعــواه وأنهــا عملــت لديــه‬\n‫مــدة ســتة أشــهر وعشــرة أيــام وســلمها رواتــب أربعــة أشــهر ثــم قامــت‬\n‫بالهــرب مــن منزلــه وعثــر عليهــا بعــد ذلــك مركــز شــؤون اخلــدم‪ ،‬ولــذا‬\n‫طلــب احلكــم عليهــا بالرجــوع إلــى العمــل لديــه لباقــي مــدة العقــد أو أن‬\n‫تدفــع لــه مــا غرمــه لقــاء اســتقدامه لهــا‪ -‬أقــرت املدعــى عليهــا بواســطة‬\n‫املترجــم مبــا جــاء يف الدعــوى ودفعــت بأنهــا ال ترغب بالرجــوع إلى العمل‬\n‫لديــه لكونهــا مريضــة بالســكري وآالم يف العظــام فــا تســتطيع العمل‬\n‫كمــا أنهــا ال تســتطيع دفــع مبلــغ االســتقدام للمدعــي لعــدم وجــود مــال‬\n\n                                                                                    ‫‪330‬‬\n\f      ‫لديهــا‪ -‬طلبــت احملكمــة مــن املدعــى عليهــا تقريــر ًا طبيـ ًا يثبــت عجزهــا‬\n      ‫عــن العمــل فقــررت أنــه ليــس لديهــا مــا يثبــت ذلــك‪ -‬أفهمــت احملكمــة‬\n      ‫املدعــي بــأن مــا طلبــه مــن إلــزام املدعــى عليهــا بإكمــال العمــل لديــه‬\n      ‫باقــي مــدة العقــد ال يتوافــق مــع األصــول الشــرعية وال ميكــن إنفــاذه‬\n      ‫وهــي ممتنعــة فعــدل عــن طلبــه وحصــره يف دفــع املدعــى عليهــا لــه مــا‬\n      ‫غرمــه لقــاء اســتقدامها‪ -‬املدعــى عليهــا مبنزلــة األجيــر اخلــاص الــذي‬\n      ‫عليــه الضمــان بالتفريــط أو التعــدي وامتناعهــا عــن العمــل وهروبهــا دون‬\n      ‫ســبب وجيــه تعــد وتفريــط فيلزمهــا ضمــان مــا غرمــه املدعــي‪ -‬قضــت‬\n      ‫احملكمــة بإلــزام املدعــى عليهــا أن تدفــع للمدعــي مــا غرمــه بســبب‬\n      ‫اســتقدامها بعــد إجــراء مقاصــة مــع باقــي رواتبهــا لديــه‪ -‬قنــع املدعــي‬\n      ‫باحلكــم وعارضــت عليــه املدعــى عليهــا‪ -‬قــررت محكمــة االســتئناف‬\n                                                ‫باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 34289348‬وتاريــخ ‪ 1434/06/24‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341521831‬وتاريــخ ‪ 1434/06/24‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافــق‪ 1434/07/16‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 30‬‬\n      ‫وفيهــا حضــر ‪ ........‬ســعودي اجلنســية احلامــل لبطاقــة الهويــة الوطنيــة‬\n      ‫رقــم ‪ ........‬وادعــى علــى احلاضــرة معــه ‪ ........‬ســريالنكية اجلنســية‬\n      ‫مبوجــب اإلقامــة اجلــواز رقــم ‪ ........‬قائــا يف دعــواه عليهــا ان هــذه‬\n      ‫احلاضــرة معــي مت اســتقدامها مــن مكتــب ‪ ...‬بالريــاض للعمــل عنــدي‬\n\n‫‪331‬‬\n\f‫عاملــه منزليــه ملــده ســنتني بــدأت مــن تاريــخ حضورهــا للمملكــة بتاريــخ‬\n‫‪1433/10/29‬ه ـ وبراتــب شــهري قــدره ثمامنائــة ريــال وكلفنــي رســوم‬\n‫اســتقدامها مبلــغ خمســة عشــر الــف ريــال اضافــه الــى مبلــغ الفــي ريــال‬\n‫رســوم تأشــيره واملجمــوع ســبعه عشــر الــف ريــال وقــد عملــت عنــدي مــدة‬\n‫ســتة اشــهر وعشــرة ايــام وقــد اعطيتهــا رواتــب اربعــه اشــهر فقــط ثــم‬\n‫انهــا قامــت بالهــروب مــن منزلــي وبعــد ان بلغــت عنهــا بفتــرة اتصــل علــي‬\n‫مركــز شــؤون اخلــدم واخبرونــي انهــا لديهــم واطلــب احلكــم عليهــا‬\n‫يف هــذه الدعــوى بالرجــوع الــى العمــل عنــدي واكمــال مــده العقــد‬\n‫الســنتني او تدفــع لــي مــا غرمتــه لقــاء اســتقدامي لهــا وهــو مبلــغ ســبعه‬\n‫عشــر الــف ريــال هــذه دعــواي وابــرز املدعــي عقــد اتفــاق بينــه وبــن‬\n‫مكتــب ‪ ...‬لالســتقدام صــادر مــن املكتــب املذكــور برقــم ‪ 46674‬يف‬\n‫‪1433/9/26‬ه ـ ومبطالعتــه وجدتــه يتضمــن ان يقــوم املكتــب املذكــور‬\n‫بالتوســط باســتقدام خادمــه واحــده مــن ســيرالنكا مقابــل مبلــغ خمســة‬\n‫عشــر الــف ريــال وعليــه تواقيــع للمذكوريــن وختــم باســم املكتــب‬\n‫املذكــور كمــا ابــرز ســند قبــض صــادر مــن املكتــب املذكــور برقــم‬\n‫‪ 42954‬يف ‪1433/9/26‬ه ـ باســتالم مبلــغ خمســة عشــر الــف ريــال مــن‬\n‫املدعــي مقابــل اســتقدام عاملــه منزليــه مــن ســيرالنكا كمــا ابــرز‬\n‫تذكــرة مراجعــه تأشــيرات صــادره مــن مكتــب العمــل وقــد تضمــن‬\n‫املوافقــة علــى طلــب املدعــي اســتقدام عاملــه منزليــه مــن ســيرالنكا‬\n‫هــذا وبعــرض ذلــك علــى املدعــى عليهــا فأجابــت علــى لســان مترجــم‬\n‫احملكمــة ‪ ........‬بقولهــا مــا ذكــره املدعــي يف دعــواه صحيــح اال اننــي‬\n‫ال ارغــب بالرجــوع الــى منزلــه حيــث اننــي مريضــه وزاد علــي مــرض‬\n‫الســكري واعانــي مــن آالم يف عظامــي وال اســتطيع العمــل كمــا اننــي‬\n\n\n                                                                                    ‫‪332‬‬\n\f      ‫ال اســتطيع دفــع مبلــغ االســتقدام للمدعــي لعــدم وجــود مــال عنــدي‬\n      ‫هــذا وبعــرض ذلــك علــى املدعــي فقــال نعــم املدعــى عليهــا مريضــه‬\n      ‫بالســكري وقمــت بعالجهــا يف مســتوصف ‪...‬واعطوهــا ا لعــاج الــازم‬\n      ‫وهــذا املــرض ال مينــع مــن العمــل هــذا فســالت املدعــى عليهــا هــل لديهــا‬\n      ‫تقريــر طبــي علــى انهــا ال تســتطيع العمــل فقالــت ال يوجــد عنــدي ذلــك‬\n      ‫هــذا فعرضــت علــى الطرفــن مــن ان يقــوم املدعــي بنقــل كفالــه املدعــى‬\n      ‫عليهــا الــى شــخص اخــر للعمــل عنــده فقــال املدعــي ال مانــع لــدي مــن‬\n      ‫ذلــك امــا املدعــى عليهــا فقالــت ال ارغــب بنقــل كفالتــي الــى شــخص‬\n      ‫اخــر وارغــب بتســفيري لبــادي ثــم ابــرز املدعــي جــواز ســفر املدعــى‬\n      ‫عليهــا رقــم ‪ ........‬وتاريــخ ‪2012/7/4‬م وباالطــاع علــى التأشــيرة‬\n      ‫املرفقــة بهــذا اجلــواز تبــن ان رقمهــا ‪ ........‬وتاريخهــا ‪1433/10/18‬ه ـ‬\n      ‫واســم املدعــى عليهــا ‪ ........‬لغــرض العمــل لــدى ‪..... .....‬أه ـ هــذا فجــرى‬\n      ‫افهــام املدعــى بــان مــا طلبــه مــن الــزام املدعــى عليهــا بإكمــال العمــل‬\n      ‫لديــه مــدة العقــد الســنتني ال يتوافــق مــع االصــول الشــرعية وال ميكــن‬\n      ‫انفــاذه وهــي ممتنعــه ورافضــه فقــال املدعــي اقــرر اذا عدولــي عــن طلبــي‬\n      ‫هــذا واطلــب ان تدفــع لــي املدعــى عليهــا مــا غرمتــه لقــاء اســتقدامي لهــا‬\n      ‫مــن مــال وقــدره ســبعة عشــر الــف ريــال وال مانــع لــدي مــن خصــم باقــي‬\n      ‫رواتبهــا التــي لهــا عنــدي مــن املبلــغ املدعــى بــه هــذا فطلبــت مــن املدعــي‬\n      ‫ابــراز التقريــر الطبــي الــذي عملــه للمدعــى عليهــا فابــرز تقريــرا طبيــا‬\n      ‫صــادرا مــن مســتوصف ‪...‬برقــم ‪ 1125‬يف ‪1434/7/2‬ه ـ وقــد تضمــن ان‬\n      ‫املدعــى عليهــا تعانــي مــن التهــاب يف املســالك البوليــة وارتفــاع بالســكر‬\n      ‫بنســبه ‪530‬مجــم ‪.‬أه ـ فنظــرا ملــا تقــدم مــن الدعــوى واإلجابــة هــذا‬\n      ‫وحيــث ان مــا ذكرتــه املدعــى عليهــا مــن ســبب امتناعهــا عــن العمــل‬\n\n\n‫‪333‬‬\n\f‫غيــر مقنــع حيــث ان مــرض الســكري ال مينــع مــن العمــل خصوصــا‬\n‫ان املدعــى عليهــا ليســت كبيــره فهــي تبلــغ مــن العمــر ثمانيــة وثالثــن‬\n‫عامــا حيــث ان تاريــخ ميالدهــا ‪1976/10/20‬م حســبما جــاء يف جــواز‬\n‫ســفرها ولــم تســتقدم ويتــم التعاقــد معهــا اال مــن اجــل ان ينتفــع املدعــى‬\n‫بخدمتهــا وعملهــا وهــي مبنزلــه االجيــر اخلــاص الــذي عليــه الضمــان‬\n‫بالتفريــط او التعــدي وهنــا املدعــى عليهــا تعــدت وفرطــت بهروبهــا ثــم‬\n‫برفضهــا العمــل واخلــت بعقــد العمــل بــدون ســبب وجيــه وفوتــت علــى‬\n‫املدعــى حقــه يف االنتفــاع بخدمتهــا بباقــي مــدة العقــد واالجــازة عقــد‬\n‫الزم كمــا انهــا احلقــت باملدعــي ضــررا ماديــا بإضاعــة مــا دفعــه مــن‬\n‫مــال نظيــر اســتقدامها للعمــل لديــه فيلزمهــا ضمــان مــا غرمــه ودفعــه‬\n‫املدعــي هــذا وحيــث ان مــا دفعــه املدعــي مبلــغ ســبعة عشــر الــف ريــال‬\n‫وباقــي رواتــب املدعــى عليهــا عنــد املدعــي الــف وثمامنائــة وســبعه وســتون‬\n‫ريــال والفــرق بعــد املقاصــة خمســة عشــر الــف ومائــه وثالثــة وثالثــون‬\n‫ريــاال فقــد حكمــت علــى املدعــى عليهــا ان تدفــع للمدعــى خمســة عشــر‬\n‫الــف ومائــه وثالثــة وثالثــن ريــاال هــذا وبعــرض احلكــم علــى املدعــى‬\n‫عليهــا بواســطه مترجــم احملكمــة ‪ ........‬فقــررت عــدم القناعــة باحلكــم‬\n‫وطلبــت االســتئناف فأجيبــت لطلبهــا كمــا قــررت بقولهــا اننــي ال ارغــب‬\n‫يف اســتالم نســخه مــن قــرار احلكــم لالعتــراض عليــه وامنــا اطلــب تدويــن‬\n‫اعتراضــي يف ضبــط القضيــة وهــو انــه ليــس لــي قــدره يف دفــع املبلــغ‬\n‫احملكــوم بــه علــي حيــث ال مــال عنــدي هــذا هــو اعتراضــي وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪ 1434/07/30‬ه ـ‬\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34315707‬وتاريــخ‬\n                                                             ‫‪1434/9/9‬هـ‬\n                                                                                    ‫‪334‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":330,"source_page_end":334,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"657e7e30f6d5b2a454d0ed9d28313120e98b644ce59aa7571b71a35913450c70","normalized_text_hash":"a160eab6da4930a53dca1cbf69454f96ff43d2383d06deb193e4938ec1d71efa","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p330-34291127"},{"id":"e6075bb2-e08a-5b7c-8ed4-3d64db79ea86","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد اجرة على عمل -جتديد إقامة عامل -مطالبة بفسخ عقد اجرة وإعادة أجرة أعمال التعقيب لعدم إجناز جزء العمل -اإلجارة عقد الزم ال ينفسخ بإرادة طرف واحد -اقرار املدعى عليه بفسخ العقد وارجاع املبالغ التي ميكن استعادتها -احلكم برد املبالغ التي ميكن استعادتها واملقر بها ورد الدعوى يف غير ذلك .","document_number":"34368555","case_number":"34501872","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة بقعاء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/24","year":"1434","subject":"عقد اجرة على عمل -جتديد إقامة عامل -مطالبة بفسخ عقد اجرة وإعادة أجرة أعمال التعقيب لعدم إجناز جزء العمل -اإلجارة عقد الزم ال ينفسخ بإرادة طرف واحد -اقرار املدعى عليه بفسخ العقد وارجاع املبالغ التي ميكن استعادتها -احلكم برد املبالغ التي ميكن استعادتها واملقر بها ورد الدعوى يف غير ذلك .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34368555 :‬تاريخه‪1434/11/24 :‬هـ‬\n                          ‫رقم الدعوى‪34501872 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34373422‬تاريخه‪1434/11/27 :‬هـ‬\n\n\n       ‫عقــد اجــرة علــى عمــل‪ -‬جتديــد إقامــة عامــل ‪ -‬مطالبــة بفســخ عقــد‬\n       ‫اجــرة وإعــادة أجــرة أعمــال التعقيــب لعــدم إجنــاز جــزء العمــل‪ -‬اإلجــارة‬\n       ‫عقــد الزم ال ينفســخ بــإرادة طــرف واحــد‪ -‬اقــرار املدعــى عليــه بفســخ‬\n       ‫العقــد وارجــاع املبالــغ التــي ميكــن اســتعادتها ‪ -‬احلكــم بــرد املبالــغ التــي‬\n                        ‫ميكــن اســتعادتها واملقــر بهــا ورد الدعــوى يف غيــر ذلــك ‪.‬‬\n\n\n\n\n                  ‫‪ -1‬اإلجارة عقد الزم من الطرفني‪ .‬كشاف القناع (‪.)3/262‬‬\n       ‫‪ -2‬جــاء يف كشــاف القنــاع (‪« :)263/3‬وإن فســخها املســتأجر مــن غيــر‬\n                                                       ‫عيــب لــم تنفســخ اإلجــارة»‪.‬‬\n       ‫‪ -3‬جــاء يف املغنــي (‪« :)23/8‬أنــه عقــد ‪-‬أي اإلجــارة‪ -‬ال يجــوز فســخه‬\n                                                                         ‫لغيــر عــذر»‪.‬‬\n       ‫‪ -4‬جــاء يف بدايــة املجتهــد (‪« :)229/2‬ال ينفســخ ‪ -‬أي عقــد اإلجــارة ‪-‬‬\n                                    ‫إال مبــا تنفســخ بــه العقــود الالزمــة ‪..‬إلــخ»‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي بأنــه دفــع للمدعــى عليــه مبلغــا مالي ـ ًا مقابــل أعمــال‬\n       ‫تعقيــب علــى جتديــد إقامــة عامــل لديــه إال أن املدعــى عليــه لــم يجــدد‬\n       ‫اإلقامــة املذكــورة‪ ،‬ولــذا طلــب احلكــم علــى املدعــى عليــه بإرجــاع‬\n\n‫‪335‬‬\n\f‫كامــل املبلــغ الــذي دفعــه لــه‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى‬\n‫ودفــع بأنــه بــدأ يف العمــل املتفــق عليــه فقــام بســداد رســوم مكتــب‬\n‫العمــل ثــم طلــب منــه املدعــي العــدول عــن التجديــد فلــم يتمكــن مــن‬\n‫اســترجاع الرســوم املدفوعــة وأنــه مســتعد بإكمــال جتديــد إقامــة‬\n‫العامــل املذكــور إذا أكمــل املدعــي مــا بقــي عليــه مــن تكاليــف‬\n‫التجديــد وإذا لــم يرغــب املدعــي بذلــك فــا مانــع لديــه مــن إعــادة باقــي‬\n‫املبلــغ لــه ليكمــل إجــراءات التجديــد بنفســه‪ -‬اإلجــارة عقــد الزم مــن‬\n‫الطرفــن ال ينفســخ إال مبــا تنفســخ بــه العقــود الالزمــة واملدعــى عليــه‬\n‫وافــق علــى فســخ العقــد علــى باقــي العمــل‪ -‬قضــت احملكمــة بإلــزام‬\n‫املدعــى عليــه بــأن يدفــع للمدعــي املبلــغ الــذي يقابــل العمــل الــذي لــم‬\n‫ينجــز كمــا قضــت بــرد دعــوى املدعــي يف مطالبتــه باملبلــغ الــذي يقابــل‬\n‫العمــل املنجــز مــن املدعــى عليــه‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض‬\n‫عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد يف يــوم‬\n‫اخلميــس املوافــق ‪1434/11/20‬ه ـ لــدي أنــا ‪ ........‬رئيــس احملكمــة‬\n‫العامــة مبحافظــة بقعــاء افتتحــت اجللســة يف الســاعة العاشــرة والنصــف‬\n‫صباحــا للنظــر يف الدعــوى املقدمــة مــن ‪ ........‬ضــد ‪ ...‬واملقيــدة بهــذه‬\n‫احملكمــة برقــم ‪ 342544637‬يف ‪1434/11/9‬ه ـ واحملالــة لــي برقــم‬\n‫‪ 34501872‬يف ‪1434/11/9‬ه ـ وقــد حضــر يف هــذه اجللســة ‪........‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وادعــى علــى‬\n‫احلاضــر معــه يف هــذه اجللســة ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n\n                                                                                    ‫‪336‬‬\n\f      ‫املدنــي رقــم ‪ ........‬قائــا يف حتريــر دعــواه لقــد دفعــت للمدعــى عليــه‬\n      ‫بتاريــخ ‪1434/5/19‬ه ـ بصفتــه مالــك مكتــب مجموعــة ‪ ...‬مبلغــا قــدره‬\n      ‫ثالثــة آالف ومائــة ريــال وذلــك لتجديــد إقامــة العامــل اخلــاص بــي وهــو‪...‬‬\n      ‫ورقــم إقامتــه ‪ .......‬ومهنتــه عامــل تربيــة مواشــي ولــم يتــم جتديــد اإلقامــة‬\n      ‫حتــى اآلن أطلــب احلكــم علــى املدعــى عليــه بإرجــاع كامــل املبلــغ الــذي‬\n      ‫دفعتــه لــه وقــدره ثالثــة آالف ومائــة ريــال هــذه دعــواي وبســؤال املدعــى‬\n      ‫عليــه عــن دعــوى املدعــي أجــاب قائــا مــا ذكــره املدعــي يف دعــواه مــن‬\n      ‫اســتالمي للمبلــغ املذكــور يف دعــواه فهــذا صحيــح علمــا بــأن ألفــن‬\n      ‫وخمســمائة ريــال مــن إجمالــي املبلــغ املذكــور يف دعــوى املدعــي خــاص‬\n      ‫لرســوم مكتــب العمــل وقمــت بســدادها واملتبقــي وقــدره ســتمائة ريــال‬\n      ‫رســوم للجــوازات وقمــت بســدادها واملبلــغ املدفــوع للجــوازات وقــدره‬\n      ‫ســتمائة ريــال أســتطيع إرجاعــه للمدعــي وأمــا رســوم مكتــب العمــل‬\n      ‫وقدرهــا ألفــان وخمســمائة ريــال فــا ميكــن إرجاعهــا حســب نظــام‬\n      ‫مكتــب العمــل علمــا بأننــي مســتعد بإكمــال طلــب املدعــي وهــو‬\n      ‫جتديــد إقامــة العامــل املذكــور يف دعــواه إذا دفــع مــا بقــي عليــه مــن‬\n      ‫تكاليــف جتديــد إقامــة العامــل وقدرهــا مائــة ريــال وتســديد الغرامــات‬\n      ‫إن كان عليــه غرامــات تأخيــر هكــذا أجــاب املدعــى عليــه وعنــد‬\n      ‫وصــول القضيــة لهــذا احلــد رفعــت اجللســة النتهــاء وقتهــا وطلبــت مــن‬\n      ‫املدعــى عليــه إحضــار الســجل التجــاري اخلــاص مبكتــب مجموعــة ‪...‬‬\n      ‫ويف جلســة أخــرى وفيهــا حضــر املدعــي واملدعــى عليــه وقــد أبــرز املدعــى‬\n      ‫عليــه الســجل التجــاري رقــم ‪ .......‬يف ‪1414/6/28‬ه ـ واملتضمــن أن ‪........‬‬\n      ‫مالــك مجموعــة ‪ ...‬وقــد جــرى منــي عــرض الصلــح علــى الطرفــن فلــم‬\n      ‫يســتجيبا لــه فســألت الطرفــن هــل بينكمــا عقــد مكتــوب فأجابــا‬\n\n\n‫‪337‬‬\n\f‫بالنفــي ثــم ســألت املدعــي عمــا ذكــره املدعــى عليــه يف اجللســة الســابقة‬\n‫فأجــاب مــا ذكــره املدعــى عليــه يف جوابــه صحيــح جملــة وتفصيــا‬\n‫هكــذا أجــاب املدعــي ثــم ســألت املدعــى عليــه عــن املبلــغ الــذي‬\n‫دفــع ملكتــب العمــل وقــدره ألفــان وخمســمائة ريــال فقــال إنــه متعلــق‬\n‫بالســجل املدنــي للمدعــي وبإمــكان املدعــي إكمــال جتديــد إقامــة‬\n‫العامــل وســألته ملــاذا لــم يتــم التجديــد للعامــل فقــال إن املدعــي راجعنــا‬\n‫باملكتــب وطلــب جتديــد رخصــة العامــل املذكــور ودفعنــا تكاليــف‬\n‫اإلصــدار للجــوازات وملكتــب العمــل ثــم عــاد إلينــا بعــد خمــس دقائــق‬\n‫وقــال إننــي عدلــت عــن التجديــد وال أرغــب فيــه ثــم ســألت املدعــي عــن‬\n‫ذلــك فقــال مــا ذكــره املدعــى عليــه مــن أننــي راجعــت املكتــب لطلــب‬\n‫جتديــد رخصــة إقامــة العامــل ثــم رجوعــي لهــم مــرة أخــرى وطلبــي منهــم‬\n‫العــدول عــن التجديــد فهــذا صحيــح هكــذا أجاب املدعي فبنــاء على ما‬\n‫تقــدم مــن الدعــوى واإلجابــة ونظــرا ألن املدعــى عليــه ال يســتطيع إرجــاع‬\n‫املبلــغ الــذي دفــع ملكتــب العمــل نظــرا ألن املبلــغ املدفــوع ملكتــب العمــل‬\n‫وقــدره ألفــان وخمســمائة ريــال مســجل باســم املدعــي ومتعلــق بســجله‬\n‫املدنــي وبإمــكان املدعــي إكمــال إجــراءات جتديــد الرخصــة مــن قبلــه‬\n‫وألن االتفــاق الــذي حصــل بــن الطرفــن يعتبــر إجــارة فاملدعــى عليــه‬\n‫وهــو مالــك مكتــب مجموعــة ‪ ...‬يعتبــر أجيــر مشــترك وألن فســخ العقــد‬\n‫مت مــن قبــل املدعــي واإلجــارة عقــد الزم مــن الطرفــن انظــر كشــاف‬\n‫القنــاع ‪ 262/3‬كمــا جــاء يف كشــاف القنــاع ‪ 263/3‬مــا نصــه (وإن‬\n‫فســخها املســتأجر مــن غيــر عيــب لــم تنفســخ اإلجــارة) وجــاء يف املغنــي‬\n‫‪ 23/8‬مــا نصــه (أنــه عقــد ‪-‬أي اإلجــارة‪ -‬ال يجــوز فســخه لغيــر عــذر)‬\n‫وجــاء يف بدايــة املجتهــد ونهايــة املقتصــد مــا نصــه ‪( 229/2‬ال ينفســخ ‪-‬‬\n\n\n                                                                                      ‫‪338‬‬\n\f      ‫أي عقــد اإلجــارة ‪ -‬إال مبــا تنفســخ بــه العقــود الالزمــة مــن وجــود العيــب‬\n      ‫بهــا أو ذهــاب محــل اســتيفاء املنفعــة ) وألن املدعــى عليــه لــم يظهــر‬\n      ‫منــه عيــب أو خلــل يف إجنــاز العمــل فهــو ال ميانــع مــن إجنــاز العمــل إذا‬\n      ‫أكمــل املدعــي الرســوم املتبقيــة فاســتيفاء املنفعــة وهــي جتديــد رخصــة‬\n      ‫العامــل املذكــور ممكنــة كمــا أن املدعــي لــم يذكــر عيبــا يوجــب‬\n      ‫الفســخ وألن املدعــى عليــه وافــق علــى فســخ العقــد فيمــا يتعلــق باملبلــغ‬\n      ‫املدفــوع للجــوازات وقــدره ســتمائة ريــال وملــا تقــدم كلــه فقــد حكمــت‬\n      ‫مبــا يلــي أوال أن يدفــع املدعــى عليــه للمدعــي مبلــغ ســتمائة ريــال وهــي‬\n      ‫الرســوم التــي دفعــت للجــوازات ثانيــا رددت دعــوى املدعــي يف مطالبتــه‬\n      ‫يف باقــي املبلــغ وقــدره ألفــان وخمســمائة ريــال وأفهمتــه بــأن لــه مطالبــة‬\n      ‫مــن بيــده العــن إذا رغــب وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n      ‫عليــه القناعــة بــه وقــرر املدعــي االعتــراض علــى احلكــم وطالــب بتمييــزه‬\n      ‫بــدون الئحــة اعتراضيــة فأجيــب لذلــك وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/11/23‬ه ـ‬\n      ‫احلمــد هلل وحده ـ والصــاة والســام علــى مــن ال نبــي بعــده فلــدي أنــا‬\n      ‫‪ ........‬رئيــس احملكمــة العامــة مبحافظــة بقعــاء افتتحــت اجللســة يف‬\n      ‫يــوم االثنــن املوافــق ‪1434/12/16‬ه ـ الســاعة الواحــدة وخمســة عشــر‬\n      ‫دقيقــة ظهــرا بنــاء علــى ورود املعاملــة مــن محكمــة االســتئناف بحائــل‬\n      ‫برقــم ‪ 342544637‬يف ‪1434/12/3‬ه ـ ومرفقــا بهــا قــرار الدائــرة‬\n      ‫احلقوقيــة األولــى رقــم ‪ 34373422‬يف ‪1434/11/27‬ه ـ املتضمــن مــا‬\n      ‫نصــه بعــد املقدمــة وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قررنــا املصادقــة علــى مــا حكــم بــه فضيلتــه وصلــى اهلل وســلم علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/12/16‬هــ‪.‬‬\n\n\n‫‪339‬‬\n\f340\n\f341\n\f342\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":335,"source_page_end":342,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b907a8d81539e41279ae2958b01ff85aabce877ba1690bec73179c55592c5a87","normalized_text_hash":"11548a8914fb285247195207f95c9280eb5dbe823199559e41d416f0ad9968ba","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p335-34368555"},{"id":"10199698-97fc-5533-bb2f-2eb43d84fe65","document_type":"judgment","category":"judicial","subcategory":"general","title":"شفعة -شفعة جار -بيع مزرعة -وجود حدود مستقلة بن مزرعة املدعي واملدعى عليه -الشهادة بأن األرض محاطة بعقوم وشبوك- املرفق املشترك يخدم سائر املزارع املجاورة -صرف النظر لكون العن املباعة غير مشاعة (مفروزة مستقلة).","document_number":"3457090","case_number":"3351663","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/7","year":"1434","subject":"شفعة -شفعة جار -بيع مزرعة -وجود حدود مستقلة بن مزرعة املدعي واملدعى عليه -الشهادة بأن األرض محاطة بعقوم وشبوك- املرفق املشترك يخدم سائر املزارع املجاورة -صرف النظر لكون العن املباعة غير مشاعة (مفروزة مستقلة).","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/3/7 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3457090 :‬‬\n                         ‫َر ْق ُم الدعوى‪3351663 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34198915‬تاريخه‪1434/4/27:‬هـ‬\n\n\n      ‫شــفعة‪ -‬شــفعة جــار‪ -‬بيــع مزرعــة‪ -‬وجــود حــدود مســتقلة بــن مزرعــة‬\n      ‫املدعــي واملدعــى عليــه‪ -‬الشــهادة بــأن األرض محاطــة بعقــوم وشــبوك‪-‬‬\n      ‫املرفــق املشــترك يخــدم ســائر املــزارع املجــاورة ‪ -‬صــرف النظــر لكــون‬\n                            ‫العــن املباعــة غيــر مشــاعة (مفــروزة مســتقلة)‪.‬‬\n\n\n\n      ‫‪« .1‬الشــفعة تثبــت للجــار فيمــا إذا كان شــريكا يف حقــوق امللــك مــن‬\n                                   ‫طريــق أو مســيل وغيرهــا» (املبــدع ‪.)206/5‬‬\n                        ‫‪ .2‬قرار هيئة كبار العلماء رقم ‪ 44‬يف ‪1396/4/13‬هــ‪.‬‬\n\n\n\n      ‫تقــدم وكيــل املدعــي بدعــواه ضــد املدعــى عليــه بأنــه اشــترى املزرعــة‬\n      ‫املجــاورة ملزرعــة موكلــه التــي تفصــل بينــه وبــن مزرعــة والــده ويطالــب‬\n      ‫بالشــفعة‪ -‬أقــر املدعــى عليــه بأنــه اشــترى املزرعــة املجــاورة ملزرعــة‬\n      ‫املدعــي ودفــع بــأن شــروط اســتحقاق املدعــي للشــفعة ال تنطبــق علــى‬\n      ‫الواقعــة‪ -‬طلــب صــرف النظــر عــن دعــواه كمــا طلــب تعويضــه عــن‬\n      ‫األضــرار التــي حلقــت بــه جــراء تعليــق تصرفــه يف أرضــه طــول املــدة التــي‬\n      ‫ســتبقى موقوفــة بســبب الدعــوى وحترمــه مــن بيــع أرضــه واســتثمار املبلغ‬\n      ‫الكبيــر قيمــة األرض ‪ ،‬خاصــة عنــد عــدم اســتقرار أســعار األراضــي‬\n      ‫يف الوقــت الراهــن وحتمــل أتعــاب احملامــاة‪ -‬متســك املدعــي ببعــض‬\n‫‪343‬‬\n\f‫النصــوص الشــرعية وأقــوال بعــض أهــل العلــم باســتحقاق اجلــار للشــفعة‬\n‫إن اشــتركا يف حــق مــن حقــوق امللــك كالطريــق وأن الطريــق املوصــل‬\n‫للمزرعتــن واملــزارع املجــاورة واحــد‪ -‬أنكــر املدعــي بأنــه لــم يطالــب‬\n‫بهــا علــى الفــور وقــرر بأنــه طالــب بهــا فــور علمــه بالبيــع وأن الراجــح‬\n‫بــأن املطالبــة بالشــفعة علــى التراخــي ال الفــور وأن طلبــه للصلــح ال يلــزم‬\n‫منــه اإلقــرار بصحــة البيــع ‪ -‬أحضــر املدعــى عليــه شــاهدين شــهدا‬\n‫بــأن املزرعــة محاطــة بشــبوك وعقــوم‪ -‬عليــه وملــا رواه جابــر ‪-‬رضــي‬\n‫اهلل عنــه‪ -‬قــال‪« :‬أن النبــي صلــى اهلل عليــه وســلم قضــى بالشــفعة يف‬\n‫كل مــا لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة «‪،‬‬\n‫وألن أهــل العلــم ‪-‬رحمهــم اهلل تعالــى‪ -‬قــرروا بــأن الشــفعة تثبــت للجــار‬\n‫فيمــا إذا كان شــريكان يف حقــوق امللــك مــن طريــق أو مســيل وغيرهــا‬\n‫(املبــدع ‪ ،)206/5‬وقــد صــدر قــرار هيئــة كبــار العلمــاء رقــم‪ 44 :‬يف‬\n‫‪1396/4/13‬هـ ـ املتضمــن أن الشــفعة تثبــت بالشــركة يف املرافــق‬\n‫اخلاصــة كالبئــر والطريــق واملســيل ‪ ،‬ومبــا أن املدعــي لــم يذكــر وجــود‬\n‫اشــتراك بينــه وبــن املدعــى عليــه إال الطريــق املذكــور‪ ،‬وقــد قــرر أنــه‬\n‫طريــق عــام وقــد شــهد الشــاهدان أن األرض محيــوزة ومعقمــة؛ لذلــك‬\n‫كلــه فقــد صرفــت الدائــرة النظــر عــن دعــوى املدعــي لعــدم اســتحقاقه‬\n‫الشــفعة كمــا صرفــت النظــر عــن طلبــات املدعــى عليــه وأفهمتــه بــأن‬\n‫لــه التقــدم بهــا بعــد اكتســاب احلكــم القطعيــة ‪ -‬وبعــرض احلكــم‬\n‫عليهمــا‪ ،‬قــرر املدعــى عليــه القناعــة‪ ،‬قــرر املدعــي االعتــراض بتقــدمي‬\n‫الئحــة فأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                     ‫‪344‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪......................‬القاضــي يف احملكمــة‬\n      ‫العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بالريــاض برقــم ‪ 3351663‬وتاريــخ ‪1433/01/19‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 33133609‬وتـ ــاريـ ـ ــخ ‪1433/01/19‬ه ففــي‬\n      ‫يـ ـ ـ ـ ــوم الســبت املـ ـ ـ ــوافق‪ 1433/04/10‬ه ـ افتتحــت اجلـ ــلسـ ـ ــة الســاعة‬\n      ‫‪ 11 : 10‬وفيهــا حضــر ‪..........................‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ..................‬بصفتــه وكيــا عــن ‪.........................‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل املزاحميــة برقــم ‪ 14‬يف‬\n      ‫‪1433/4/10‬ه ـ واملخــول لــه فيهــا بإقامــة الدعاوى واملخاصمــة واملرافعة‬\n      ‫واملدافعــة وســماع الدعــاوي والــرد عليهــا وإقامــة البينــة واإلقــرار وحضــر‬\n      ‫حلضــوره ‪ ............................‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ..................‬بصفتــه وكيــا عــن ‪ .......................‬مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم ‪3339621‬‬\n      ‫وتاريــخ ‪1433/4/7‬ه ـ واملخــول لــه فيهــا باملرافعــة واملدافعــة وقبــول‬\n      ‫األحــكام ونفيهــا وطلــب اإلســتئناف قائــا يف دعــواه إن موكلــي ميلــك‬\n      ‫املزرعــة الواقعــة يف مركــز اجللــه شــمال طريــق الريــاض الطائــف ويحــد‬\n      ‫أرض موكلــي أرض زراعيــة مملوكــة ‪ ...‬مــن الشــمال وقــد قــام مالــك‬\n      ‫االرض املذكــورة ببيعهــا علــى املدعــى عليــه أصالــة‪.......................‬‬\n      ‫مببلــغ مليــون وســتمائة ألــف ريــال وقــد علــم موكلــي ببيعهــا قبــل‬\n      ‫افراغهــا للمدعــى عليــه بيــوم فقــام باالتصــال علــى املدعــى عليــه أصالــة‬\n      ‫وأخبــره أنــه شــافع يف األرض لكونهــا حتــده مــن الشــمال وهــذه األرض‬\n\n‫‪345‬‬\n\f‫بينــه وبــن أرض والــده فقــال لــه املدعــى عليــه يكــون خيــر ثــم قــام‬\n‫بإقفــال جوالــه وموكلــي يرغــب يف شــراء هــذه األرض وأننــي أطلــب‬\n‫يف دعــواي هــذه ســؤال املدعــى عليــه وكالــة وإثبــات شــفعة موكلــي‬\n‫يف االرض املذكــورة وشــرائها لكونــه أحــق بهــا مــن املدعــى عليــه‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه وكالــة قــال إننــي أطلــب إمهالــي‬\n‫ملراجعــة موكلــي واســتعد بإحضــار اجلــواب يف اجللســة القادمــة هــذا‬\n‫مــا لــدي وقــال املدعــي وكالــة إننــي ســبق وإن تقدمــت بطلــب احلجــز‬\n‫التحفظــي علــى األرض املدعــى بهــا وأقــرر لديكــم عــدول موكلــي‬\n‫عــن هــذا الطلــب هــذا مــا لــدي وبنــاء عليــه فقــد جــرى رفــع اجللســة ويف‬\n‫جلســة أخــرى حضــر املدعــي وكالــه ‪ .................‬واملدعــى عليــه وكالــه‬\n‫‪ ..................‬وابــرز املدعــى عليــه وكالــة الوكالــة الصــادرة مــن كتابــه‬\n‫عــدل جنــوب الريــاض الثانيــة برقــم ‪ 33151641‬يف ‪1433/7/2‬ه ـ والتي‬\n‫وكلــه فيهــا ‪ ..........................‬وجعــل لــه فيهــا حــق املرافعــة واملدافعــة‬\n‫واالقــرار واالنــكار والصلــح وطلــب اليمــن ورده وابــرز املدعــى عليــه‬\n   ‫وكالــه مذكرتــه اجلوابيــة املكــون مــن صفحتــن والتــي جــاء فيهــا‬\n‫إش ــارة إل ــى الدع ــوى رقــم (‪ )33133609‬وتاريــخ ‪1433 /01/19‬ه ـ‬\n‫املقام ــة مــن املكــرم ‪ ......................... /‬ض ــد موكلــي امل ــكرم ‪/‬‬\n‫‪...........................‬املتضمنــة طلــب إفــراغ أرض موكلــي لــه بحجــة أن‬\n‫األرض املوصوفــة أدنــاه تقــع بينــه وبــن ملــك مزرعــة والــده ومتداخلــة‬\n‫بــن صكوكهمــا الواقعــة يف ‪ .................‬التابعــة حملافظــة املزاحميــة‬\n‫(( التــي اشــتراها موكلــي مــن املكــرم ‪..................... /‬مبوجــب عقــد‬\n‫البيــع رقــم (‪ )55‬وتاريــخ ‪1432 /10/26‬ه ـ مبلــغ وقــدره مليــون وســتمائة‬\n‫ألــف ريــال (‪ )1600000‬باإلضافــة إلــى مبلــغ الســعي البالــغ أربعــون ألــف‬\n\n\n                                                                                          ‫‪346‬‬\n\f      ‫ريــال (‪ )40000‬ومســاحتها مليونــن وأربعمائــة وواحــد وعشــرين ألــف‬\n      ‫وثالثمائــة وخمســة وســبعون متــر مربــع (‪ )2421375‬واألرض حســب‬\n      ‫شــروط العقــد وشــهادة الشــهود محيــوزة ومحــدودة بشــبك وعقــم‬\n      ‫مــن جميــع اجلهــات ومــا بداخلــه داخــل يف البيــع ويحدهــا مــن الغــرب‬\n      ‫شــارع عــام عرضــه خمســون متــرا (‪ )50‬م وقــد مت إفراغهــا ملوكلــي‬\n      ‫مبوجــب الصــك رقــم (‪ )3/149/1697‬وتاريــخ‪1432/11/11‬ه الصــادر‬\n      ‫مــن كتابــة عــدل املزاحميــة))‪ .‬وعليــه أطلــب صــرف النظــر عــن طلــب‬\n                                                       ‫املدعــي لألمــور التاليــة ‪:‬‬\n      ‫أوالً‪ :‬املدعــي غيــر ذي صفــة فــاألرض محيــوزة ومحاطــة بشــبك وعقــم‬\n      ‫ترابــي ‪ ،‬وهــي القطعــة الزراعيــة رقــم (‪ )4‬مــن املخطــط الزراعــي رقــم‬\n      ‫(‪ )6/218‬الصــادر مــن وزارة الزراعــة منــذ أكثــر مــن ثالثــة وعشــرين‬\n      ‫ســنة حســب تاريــخ صــك األرض الصــادر مــن كتابــة عــدل محافظــة‬\n      ‫القويعيــة رقــم (‪52‬ح‪ 2‬صـ‪ 52‬ــ) وتاريــخ ‪1409/12/21‬ه ـ وقد مت إفراغها‬\n      ‫ملوكلي مبوجب الصك رقم (‪ )3/149/1697‬وتاريخ ‪1432/11/11‬هـ‬\n      ‫)) الصــادر مــن كتابــة عــدل املزاحميــة والكروكــي واســتلم موكلــي‬\n      ‫األرض خاليــة غيــر مشــغولة بعــد الوقــوف عليهــا فقبضهــا يف محلهــا‬\n      ‫وصــارت يف حوزتــه وحتــت يــده محيــوزة ومحــدودة بشــبك وعقــم مــن‬\n      ‫جميــع اجلهــات ومــا بداخلــه داخــل يف البيــع‪ ،‬واألرض ليســت متداخلــة‬\n      ‫بــن أرض املدعــي وبــن مزرعــة والــده أو متداخلــة بــن صكوكهمــا‬\n      ‫حســب الصكــوك والكروكــي ‪ ،‬علمــا أن املدعــي لــم يذكــر موقــع‬\n      ‫عقــاره وحــدوده وكامــل أطوالــه ومســاحته وصــك متلكــه وموقــع اجلــزء‬\n                             ‫املتداخــل مــن العقــار وحــدوده وأطوالــه ومســاحته‪.‬‬\n      ‫ثانيـ ًا ‪ :‬األرض معروضــة للبيــع منــذ أكثــر مــن ســنة ‪ ،‬واألرض ومعظــم‬\n\n\n‫‪347‬‬\n\f‫األراضــي املجــاورة هــي عبــارة عــن مــزارع مهجــورة وغيــر مأهولــة‬\n                                                                    ‫بالســكان‪.‬‬\n‫ثالثـ ًا ‪ :‬املدعــي ليــس شــريكا للبائــع يف األرض وال شــريكا يف منافعهــا‬\n‫‪ ،‬فاألرض يحدها من الشمال أرض ‪ ..............‬وجنوبا مزرعة ‪...............‬‬\n                     ‫وشــرقا أرض ‪ ........................‬وغربا شــارع عام عرضه‬\n‫خمســون متــرا ولــم يذكــر يف صحيفــة دعــواه أي مســتند أو بيــان‬\n‫يثبــت شــيئا مــن ذلــك ‪ ،‬وقــد صــدر قــرار فتــوى هيئــة كبــار العلمــاء ذو‬\n‫الرقــم (‪ )44‬يف ‪1396/4/13‬ه ـ يف الــدورة الثامنــة املنعقــدة يف الريــاض‬\n‫والتيــوردت بصيغــة تعميــم علــى كافــة احملاكــم بالرقــم ‪/13/161‬ت‬\n‫يف ‪1396/8/12‬ه ـ مــن معالــي وزيــر العــدل واملبنــي علــى خطــاب‬\n‫املقــام الســامي ذي الرقــم ‪ 17080‬يف ‪1396/7/15‬ه ـ (‪ ...‬قــرر املجلــس‬\n‫باألكثريــة أن الشــفعة تثبــت بالشــركة يف املرافــق اخلاصــة كالبئــر‪...‬‬\n‫ونحوهمــا كمــا تثبــت الشــفعة فيمــا ال ميكــن قســمته مــن العقــار‬\n‫كالبيــت واحلانــوت الصغيريــن ‪ ،....‬وملــا روى البخــاري يف صحيحــه وأبــو‬\n‫داود والترمــذي يف ســننهما بإســنادهم إلــى جابــر بــن عبــداهلل رضــي اهلل‬\n‫عنهمــا قــال ‪ :‬قضــى رســول اهلل صلــى اهلل عليــه وســلم بالشــفعة يف كل‬\n     ‫مــا لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة ‪. )...‬‬\n‫رابعـ ُا ‪ :‬املدعــي تبلــغ بالبيــع حـس ــب إقــراره علــى لســان وكيله يف اجل ــلسة‬\n‫‪1433 /4/10‬ه ـ واملــدون يف محضــر اجللســة أنــه تبلــغ ليلــة إفــراغ الصــك‬\n‫للمشــتري بتاريــخ ‪1432/11/11‬ه ـ ولــم يبــادر بالشــفعة علــى الفــور‬\n‫وقــد تراخــى و تأخــر أكثــر مــن شــهرين يف املطالبــة بالشــفعة وتقــدمي‬\n‫صحيفــة دعــواه حتــى تاريــخ ‪1433/1/19‬ه ـ ‪ .‬وقــد ورديف األثــر (الشــفعة‬\n‫كحــل العقــال) (فــإن قيدهــا مكانــه ثبــت حقــه‪ ،‬وإال فاللــوم عليــه)‬\n\n\n                                                                                       ‫‪348‬‬\n\f      ‫(إمنــا الشــفعة ملــن واثبهــا ) ومــن تراخــى عــن املطالبــة ســقط حقــه يف‬\n                                                                                   ‫الشــفعة‬\n      ‫خامسـ ًا ‪ :‬عــرض املدعــي علــى املشــتري شــراء األرض بفائــدة (خمســون‬\n      ‫ألــف ريــال) بتاريخ‪1432/11/17‬ه ـ بحضــور ‪ .............................‬وبعــد‬\n      ‫فتــرة قبــل تقــدمي صحيفــة الدعــوى عــرض شــرائها مببلــغ مليونــن ريــال‬\n      ‫عــن طريــق ‪ ...‬و‪ ،...‬وهــذا يــدل علــى إقــراره بأنهــا ملــك للمشــتري وأن‬\n      ‫ا حــق يف الشــفعة‪ .‬وعليــه أطلــب صــرف النظــر عــن طلــب‬          ‫ليــس لــه أص ـ ً‬\n      ‫املدعــي لألســباب املذكــورة أعــاه ‪ ،‬كمــا أطلــب تعويــض موكلــي‬\n      ‫عــن األضــرار التــي حلقــت بــه جــراء تعليــق تصرفــه يف أرضــه وطــول‬\n      ‫املــدة التــي ســتبقى موقوفــه بســبب الدعــوى وحترمــه مــن بيــع أرضــه‬\n      ‫واســتثمار املبلــغ الكبيــر قيمــة األرض ‪ ،‬خاصــة عنــد عــدم اســتقرار‬\n      ‫أســعار األراضــي يف الوقــت الراهــن وحتمــل أتعــاب احملامــاة اه ـ وبعــرض‬\n      ‫جــواب املدعــى عليــه وكالــه علــى املدعــي وكالــه بعــد تســليمه صــوره‬\n      ‫مــن املذكــرة اجلوابيــة قــال اطلــب امهالــي ملراجعــة موكلــي واســتعد‬\n      ‫إلحضار اجلواب يف اجللســة القادمة وبناء عليه مت رفع اجللســة ويف جلســة‬\n      ‫اخــرى حضــر املدعــي وكالــة وحضــر حلضــوره املدعــى عليــه وكالــة‬\n      ‫واملدونــة هوياتهمــا ســابقا‪ ،‬وقــدم املدعــي وكالــة مذكــرة جــاء فيهــا‪:‬‬\n      ‫‪ -1‬مــا ذكــره املدعــي عليــه وكالــة بقولــه (واســتلم موكلــي األرض‬\n      ‫خاليــة غيــر مشــغولة بعــد الوقــوف عليهــا فقبضهــا يف محلهــا وصــارت يف‬\n      ‫حوزتــه وحتــت يــده محيــوزة ومحــدودة بشــبك وعقــم مــن جميــع اجلهــات‬\n      ‫ومــا بداخلــه داخــل يف البيــع ‪..‬إلــخ ) وتعقيبــي ‪:‬أنــا ال أطالــب بإزالــة حتــى‬\n      ‫يذكــر املدعــى عليــه وكالــة مــا تقــدم إمنــا أطالــب بالشــفعة والشــفعة‬\n      ‫هــي حــق متلــك العقــار املبيــع جبــرا عــن املشــترى مبــا قــام عليــه مــن ثمــن‬\n\n\n‫‪349‬‬\n\f‫وتكاليــف ‪ ،‬أمــا مــا ذكــره بقولــه (واألرض ليســت متداخلــة بــن أرض‬\n‫املدعــي وبــن مزرعــة والــده أو متداخلــة بــن صكوكهــا ‪..‬إلــخ ) فهــذا‬\n‫غيــر صحيــح‪ ،‬بــل مــا ورد بإجابتــه بإقــراره بالبنــد (ثالث ـاً) يفيــد وقوعــه‬\n‫يف التناقــض وعــدم صحــة مــا ورد بدفعــه حــن قــال (األرض يحدهــا‬\n‫مــن الشــمال أرض ‪( .................... /‬والــد املدعــي) وجنوب ـ ًا مزرعــة ‪/‬‬\n‫‪( ...............‬املدعــي أصالــة)‪ -2.‬قولــه أنــي لســت شــريكا يف األرض‬\n‫أقــول ‪ :‬أهــل العلــم أجــازوا ذلــك ملــن يشــترك يف حــق مــن حقــوق امللــك‬\n‫كالطريــق مثــا ملــا رواه أصحــاب الســن بإســناد صحيــح عــن جابــر‬\n‫عــن النبــي‪ ،‬صلــى اهلل عليــه وســلم‪ ،‬قــال‪ :‬اجلــار أحــق بشــفعة جــاره‪،‬‬\n‫ينتظــر بهــا وإن كان غائبــا إذا كان طريقهمــا واحــدا قــال ابــن القيــم‪:‬‬\n‫وعلــى هــذا القــول تــدل أحاديــث جابــر منطوقهــا ومفهومهــا ويــزول عنهــا‬\n‫القضــاء واالختــاف‪ .‬وقــد فصــل هــذه النقطــة الشــيخ محمــد العثيمــن‬\n‫بقولــه ‪ :‬فــإذا قــال قائــل‪ :‬مــا الدليــل علــى مــا اشــترطه املؤلــف ألن قولــه‪:‬‬\n‫لشــريك يف أرض يخــرج اجلــار‪ ،‬وقــد صـ َّـرح بــه فقــال‪ :‬فــا شــفعة جلــار‬\n‫فمــا الدليــل قالــوا‪ :‬إن الدليــل قــول جابــر ـ رضــي اهلل عنــه ـ‪( :‬قضــى‬\n‫النبــي ص ّلــى اهلل عليــه وسـلّم بالشــفعة يف كل مــا لــم يقســم) فمفهومــه‬\n‫أن مــا قســم ليــس فيــه شــفعة‪ ،‬وإذا قســم صــار الشــريك جــاراً‪ ،‬كأرض‬\n‫بــن رجلــن اقتســماها كانــت يف األول مشــتركة واآلن صــار الشــريك‬\n‫جــاراً‪ ،‬واحلديــث‪( :‬قضــى النبــي ص ّلــى اهلل عليــه وسـلّم بالشــفعة فيــكل‬\n‫مــا لــم يقســم) هــذا املنطــوق‪ ،‬ومفهومــه ال شــفعة فيمــا قســم‪ ،‬والنتيجــة‬\n‫ال شــفعة للجــار ألنــه إذا كان اجلــار الــذي كان شــريك ًا بــاألول ال‬\n‫شــفعة لــه‪ ،‬فاجلــار الــذي ليــس بينــه وبــن جــاره شــركة مــن بــاب أولــى‪.‬‬\n‫ولكــن نقــول‪ :‬االســتدالل بهــذا احلديــث فيــه نظــر؛ ألنــه يجــب إذا‬\n\n\n                                                                                        ‫‪350‬‬\n\f      ‫اســتدللنا باحلديــث أن نســتدل بــه كام ـاً‪ ،‬وإذا اســتدللنا باحلديــث‬\n      ‫ا لــزم أن يكــون اجلــار لــه شــفعة يف بعــض األحــوال‪ ،‬وليــس لــه‬     ‫كام ـ ً‬\n      ‫شــفعة يف بعــض األحــوال‪ ،‬يقــول جاب ـرـ رضــي اهلل عنــه ـ‪( :‬فــإذا وقعــت‬\n      ‫احلــدود وصرفــت الطــرق فــا شــفعة) فاحلديــث بـ َّـن أنــه إذا حصلــت‬\n      ‫وصرفــت الطــرق‪ ،‬بــأن كان هــذا‬     ‫ِّ‬    ‫القســمة ورســمت األرض بحدودهــا‬\n      ‫اجلانــب لــه طريــق واجلانــب اآلخــر لــه طريــق فــا شــفعة‪ ،‬فيؤخــذ مــن‬\n      ‫هــذا أنهمــا لــو اقتســما وبقــي الطريــق واحــد ًا لــم ُيصـ َّـرف فالشــفعة‬\n      ‫باقيــة‪ ،‬وهــذا هــو القــول الراجــح‪ ،‬أن اجلــار لــه الشــفعة فيحــال وليــس لــه‬\n      ‫الشــفعة يف حــال‪ ،‬فــإذا كانــت الطريــق واحــدة‪ ،‬أو املــاء الــذي يســقى‬\n      ‫بــه الــزرع واحــداً‪ ،‬أو أي شــيء اشــتركا فيــه مــن حــق امللــك فــإن الشــفعة‬\n      ‫ثابتــة‪ ،‬وإذا لــم يكــن بينهمــا حــق مشــترك فــا شــفعة‪ ،‬هــذا هــو القــول‬\n      ‫الراجــح يف ثبــوت الشــفعة للجــار‪ ،‬وعليــه يحمــل حديــث‪ :‬اجلــار أحــق‬\n      ‫بســقبه ‪ ،‬وهــو اختيــار شــيخ اإلســام ابــن تيميــة ـ رحمــه اهلل ـ‪ .‬وقــال‬\n      ‫بعــض العلمــاء‪ :‬للجــار الشــفعة مطلق ـ ًا حلديــث‪ :‬اجلــار أحــق بســقبه أي‪:‬‬\n      ‫مبــا جــاوره‪ -3.‬لــم أعلــم عــن عــرض األرض للبيــع خصوصــا وأن غالــب‬\n      ‫إقامتــي الســنوات األخيــرة خــارج البــاد وال يســتطيع املدعــى عليــه‬\n      ‫إثبــات علمــي بالبيــع‪ :-4.‬إننــي بــادرت لطلــب الشــفعة حــال علمــي وال‬\n      ‫ميلــك املدعــى عليــه البينــة علــى رضــاي وتهاونــي ‪ ،‬واالســتدالل مــن قبــل‬\n      ‫املدعــى عليــه بحديــث‪ :‬الشــفعة ملــن واثبهــا والشــفعة كحــل العقــال ] أرد‬\n      ‫عليــه بــأن هذيــن احلديثــن ضعيفــن كمــا قــال ابــن عثيمــن وأضــاف ‪:‬‬\n      ‫ال ُيحتــج بهمــا وال ميكــن أن يتوصــل بهمــا إلــى إســقاط حــق املســلم فــا‬\n      ‫اعتمــاد عليهمــا‪ ،‬وإذا لــم يكــن عليهمــا اعتمــاد رجعنــا إلــى األصــل‪،‬‬\n      ‫واألصــل أن كل مــن ثبــت لــه حــق فإنــه ال يســقط إال مبــا يــدل علــى‬\n\n\n‫‪351‬‬\n\f‫رضــاه؛ ألن هــذا حــق شــرعي‪ :‬قضــى النبــي ص ّلــى اهلل عليــه وس ـلّم‬\n‫بالشــفعة يف كل مــا لــم يقســم فهــذا قضــاء نبــوي ال ميكــن أن يســقط‬\n‫إال مبــا يــدل علــى الرضــا‪ .‬وعليــه فالقــول الراجــح الــذي يتعــن األخــذ‬\n‫بــه أن يقــال‪ :‬هــي علــى التراخــي ال تســقط إال مبــا يــدل علــى الرضــا‪.‬‬\n‫‪ -5‬ال صحــة لطلــب الشــراء وكنــت حريصــا علــى ســامة النفــوس فــا‬\n‫يســقط حقــي مــن الشــفعة قــال ابــن عثيمــن رحمــه اهلل ‪ :‬لكــن ينبغــي‬\n‫أن يقــال‪ :‬إن اللــوازم التــي ذكروهــا مــن أن طلــب املصاحلــة‪ ،‬أو طلــب‬\n‫البعــض‪ ،‬أو مــا أشــبه ذلــك‪ ،‬تــدل علــى أنــه أقــر البيــع‪ ،‬ينبغــي أن يقــال‪:‬‬\n‫إذا وقــع هــذا مــن عالــم فنعــم‪ ،‬وإن وقــع مــن جاهــل ال يــدري‪ ،‬وقــال‪ :‬أنــا‬\n‫أريــد املصاحلــة دفعـ ًا للمطالبــة وكســر قلبــه‪ ،‬ومــا أشــبه ذلــك‪ ،‬فإنــه ال‬\n‫ينبغــي أن تســقط الشــفعة‪ ،‬فيفــرق بــن مــن يفهــم ويعلــم‪ ،‬وبــن مــن ال‬\n‫يفهــم وال يعلــم‪ ،‬فــإذا قــال‪ :‬صاحلنــي‪ ،‬أو جنعلهــا أنصاف ـ ًا لــك النصــف‬\n‫ولــي النصــف‪ ،‬عــن ســامة قلــب وعــدم معرفــة فينبغــي أن ال تســقط‬\n‫الشــفعة؛ ألنــه يف هــذه احلــال معــذور‪ ،‬وكمــا عــذروا مــن لــم يطلبهــا علــى‬\n‫الفــور مبــا عــذروه بــه‪ ،‬فهــذه مثلهــا واخلالصــة‪ :‬أن الشــفعة حق للشــفيع ال‬\n‫تســقط إال مبــا يــدل علــى رضــاه‪ ،‬أمــا كونهــا حقـ ًا للشــفيع فهــو قضــاء‬\n‫نبــوي‪ :‬قضــى بالشــفعة يف كل مــا يقســم ‪ ،‬وأمــا كونهــا ال تســقط‬\n‫إال برضــاه؛ فألنهــا حقــه‪ ،‬وال ميكــن أن تؤخــذ احلقــوق مــن أصحابهــا‬\n‫كره ـ ًا وكذلــك بخصــوص مــا ذكــره املدعــي عليــه مبذكرتــه‬\n‫الســابقة يف البنــد خامســا بــأن موكلــي عــرض شــرائها مببلــغ مليونــن‬\n‫ال مــن ‪ ................‬و‪ ،.................‬فأنــه بعــد رجــوع‬\n                                                              ‫ريــال عــن طريــق ك ً‬\n‫موكلــي لهــم أنكــرا ذلــك‪ ،‬ومســتعدون بالشــهادة بذلــك‪ -6.‬كمــا أن‬\n‫املدعــى عليــه لــم يعمــل بأمركــم املنــع مــن التصــرف يف األرض حلــن‬\n\n\n                                                                                       ‫‪352‬‬\n\f      ‫نهايــة القضيــة بــل قــام ببيــع قطــع فيهــا ومــن املؤســف جــد ًا أنــه بــاع علــى‬\n      ‫أنــاس يعتبــرون دخــاء علــى املنطقــة ويخالفــون أهلهــا يف عقيدتهــم (ال‬\n      ‫والء إال ببــراء) وقــد صــدرت فتــاوى أهــل العلــم بحرمــة ذلــك ممــا يؤكــد‬\n      ‫الضــرر علينــا‪ .‬وحلكمــة الشــفعة مــن حيــث دفــع الضــرر عــن الشــفيع‪،‬‬\n      ‫إذ قــد ال تتفــق أخالقــه وعاداتــه ومذهبــه مــع املشــترى اجلديــد ‪ ،‬وقــد‬\n      ‫يكــون مؤذيــا ســيء األخــاق أو العــادات أو الطبــاع‪ ،‬ولقولــه صلــى اهلل‬\n      ‫عليــه وســلم ( جــار الــدار أحــق بالــدار) و ( اجلــار أحــق بســقبه )‪ .‬بجميــع‬\n      ‫مــا ســبق فإنــي أطلــب حقــي بالشــفعة مــن املدعــى عليــه ‪ ،‬وبعرضــه علــى‬\n      ‫املدعــى عليــه وكالــة بعــد تســليمه صــورة منهــا قــال او ًال املدعــي غير ذي‬\n      ‫صفــة فــاألرض محيــوزة ومحاطــة بشــبك وعقــم ترابــي‪ ،‬وهــي القطعــة‬\n      ‫الزراعيــة رقــم (‪ )4‬مــن املخطــط الزراعــي رقــم (‪ )6/218‬الصــادر مــن‬\n      ‫وزارة الزراعــة منــذ أكثــر مــن ثالثــة وعشــرين ســنة حســب تاريــخ صــك‬\n      ‫األرض الصــادر مــن كتابــة عدل محافظة القويعية رقم (‪52‬ح‪ 2‬صـ‪52‬ــ)‬\n      ‫وتاريــخ ‪1409/12/21‬ه ـ وقــدمت إفراغهــا ملوكلــي مبوجــب الصــك‬\n      ‫رقــم(‪ )3/149/1697‬وتاريخ‪1432/11/11‬ه ـ )الصــادر مــن كتابــة‬\n      ‫عــدل املزاحميــة والكروكــي املرفــق صورتــه واســتلم موكلــي األرض‬\n      ‫خاليــة غيــر مشــغولة بعــد الوقــوف عليهــا فقبضهــا يف محلهــا وصــارت‬\n      ‫يف حوزتــه وحتــت يــده ‪ ،‬محيــوزة ومحــدودة بشــبك وعقــم مــن جميــع‬\n      ‫اجلهــات ومــا بداخلــه داخــل يف البيع(وقــد أقــر املدعــي صراحــة بذلــك‬\n      ‫يف مذكرتــه الدفاعيــة الفقــرة األولــى التــي ســلمها وكيلــه يف اجللســة‬\n      ‫الرابعــة وســجلت يف محضــر اجللســة) علمــا أن املدعــي لــم يذكــر موقــع‬\n      ‫عقــاره وحــدوده وكامــل أطوالــه ومســاحته وصــك متلكــه وموقــع اجلــزء‬\n      ‫املتداخــل مــن العقــار وحــدوده وأطوالــه ومســاحته ‪،‬وهــل يوجــد لديــه‬\n\n\n‫‪353‬‬\n\f‫صــك ملكيــة أم ال ثانيـاً‪ :‬ذكــر املدعــي أنــه يشــترك يف حــق مــن حقــوق‬\n‫امللــك كالطريــق وهــذا غيــر صحيــح فالطريــق عــام عرضــه خمســون‬\n‫متــرا وليــس خــاص بينهمــا كمــا هــو موضــح يف الكروكــي ومذكــور‬\n‫يف صــور الصكــوك املســلمة لفضيلتكــم يف اجللســة املاضيــة ‪ ،‬وقــد‬\n‫صدر قرار فتوى هيئة كبار العلماء ذو الرقم (‪ )44‬يف ‪1396/4/13‬هـ‬\n‫يف الــدورة الثامنــة املنعقــدة يف الريــاض والتــي وردت بصيغــة تعميــم علــى‬\n‫كافــة احملاكــم بالرقــم ‪/13/161‬ت يف ‪1396/8/12‬ه ـ مــن معالــي‬\n‫وزيــر العــدل واملبنــي علــى خطــاب املقــام الســامي ذي الرقــم ‪17080‬يف‬\n‫‪1396/7/15‬هـ (‪ ..‬قرر املجلس باألكثرية أن الشــفعة تثبت بالشــركة‬\n‫يف املرافــق اخلاصــة كالبئــر والطريــق ونحوهمــا كمــا تثبــت الشــفعة‬\n‫فيمــا ال ميكــن قســمته مــن العقــار كالبيــت واحلانــوت الصغيرين ‪ ،..‬وملا‬\n‫روى البخــاري يف صحيحــه وأبــو داود والترمــذي فيســننهما بإســنادهم‬\n‫إلــى جابــر بــن عبــداهلل رضــي اهلل عنهمــا قــال ‪ :‬قضــى رســول اهلل صلــى‬\n‫اهلل عليــه وســلم بالشــفعة يف كل مــا لــم يقســم فــإذا وقعــت احلــدود‬\n                                             ‫وصرفــت الطــرق فــا شــفعة ‪.)..‬‬\n‫ثالث ـ ًا ‪:‬ذكــر أنــه طلــب الشــفعة حــال علمــه ولــم يذكــر تاريخــا لذلــك‬\n‫‪ ،‬وأكتفــي مبــا ذكرتــه يف املذكــرة الســابقة عــن هــذه الفقــرة رابعـاُ‪:‬‬\n‫أنكــر املدعــي أنــه عــرض شــرائها مببلــغ مليونــن ريــال عــن طريــق‬\n‫ال مــن ‪..............‬و‪ ................‬وأنهمــا أنكــرا ذلــك وعليــه فــإن املبلــغ‬\n                                                                                   ‫ك ً‬\n‫ليــس هدفــا يف ذاتــه ‪ ،‬وأكتفــي مبــا ذكرتــه يف املذكــرة الســابقة عــن‬\n‫هــذه الفقــرة ‪.‬خامس ـاً‪ :‬ذكــر املدعــي أن موكلــي لــم يعمــل بأمــر املنــع‬\n‫مــن التصــرف يف األرض حلــن نهايــة القضيــة ‪ ،‬ولــم يصــدر أي خطــاب‬\n‫باملنــع وأكتفــي عــن بقيــة الفقــرات مبــا ذكرتــه يف املذكــرة الســابقة‬\n\n\n                                                                                         ‫‪354‬‬\n\f      ‫وعليــه أطلــب صــرف النظــر عــن طلــب املدعــي واحلكــم بذلــك لألســباب‬\n      ‫املذكــورة أعــاه ‪،‬كمــا أطلــب تعويــض موكلــي عــن األضــرار التــي‬\n      ‫حلقــت بــه جــراء ابتعــاد املشــترين بســبب وجــود قضيــة فيهــا وطــول‬\n      ‫املــدة التــي ســتبقى معطلــة بســبب الدعــوى وحترمــه مــن اســتثمار املبلــغ‬\n      ‫الكبيــر (قيمــة األرض)‪ ،‬خاصــة عنــد عــدم اســتقرار أســعار األراضــي‬\n      ‫يف الوقــت الراهــن ‪ ،‬وحتمــل أتعــاب احملامــاة وبعرضــه علــى املدعــي‬\n      ‫وكالــة قــال اكتفــي مبــا قدمــت يف دعــواي وال أعلــم هــل األرض‬\n      ‫محيــوزة بعقــوم وشــبوك هــذا مــا لــدي ‪ ،‬وقــال املدعــى عليــه وكالــة‬\n      ‫لــدي بينــة علــى أن األرض محيــوزة ومحاطــة بعقــوم وشــبوك واســتعد‬\n      ‫بإحضارهــا هــذا مــا لــدي وبنــاء عليــه فقــد مت رفــع اجللســة ويف جلســة‬\n      ‫اخــرى حضــر املدعــي أصالــة‪ .................... /‬حامــل الســجل املدنــي رقــم‪:‬‬\n      ‫(‪ ).......................‬وحضــر حلضــوره املدعــي وكالــة ‪ ...............‬املدونــة‬\n      ‫هويتــه ســابقا‪ ،‬كمــا حضــر املدعــى عليــه أصالــة‪ .................... /‬حامــل‬\n      ‫الســجل املدنــي رقــم‪ )..……………( :‬وحضــر حلضــوره املدعــى‬\n      ‫عليــه وكالــة‪ ................. /‬حامــل الســجل املدنــي رقــم‪)..................( :‬‬\n      ‫بالوكالــة عــن ‪ ...............‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بجنــوب الريــاض برقــم‪ )34219243( :‬وتاريــخ ‪1434/2/24‬ه ـ ـ‬\n      ‫والتــي تخولــه املطالبــة واملدافعــة واملرافعــة وطلــب اليمــن واالقــرار‬\n      ‫واالنــكار‪ ،‬وقــال املدعــي وكالــة إن مزرعــة موكلــي ومزرعــة املدعــى‬\n      ‫عليــه ومزرعــة والــد موكلــي كلهــا ميــر بهــا طريــق عــام عرضــه خمســن‬\n      ‫متــر يخــدم هــذه املــزارع‪ ،‬وغيرهــا‪ ،‬هــذا مــا لــدي‪ .‬وقــال املدعــى عليــه‬\n      ‫أصالــة‪ /‬إن األرض محــل الدعــوى محيــوزة وميــر بهــا الطريــق املذكــور‬\n      ‫مــن جهــة الغــرب ولــدي بينــة أطلــب ســماعها‪ ،‬وأحضــر معــه كال مــن‪:‬‬\n\n\n‫‪355‬‬\n\f‫‪ .................... /1‬حامــل الســجل املدنــي رقــم‪ ،).....................( :‬و‪/2‬‬\n‫‪ ......................‬حامــل الســجل املدنــي رقــم‪ ،).................( :‬وطلــب ســماع‬\n‫مــا لديهمــا‪ ،‬وبســؤالهما عمــا لديهمــا قــال الشــاهد األول ‪.............‬‬\n‫إننــي مــن مواليــد عــام ‪ 1354‬وأســكن يف تبــراك وال أعمــل وليــس‬\n‫بينــي وبــن املدعــي وال املدعــى عليــه أي عالقــة قرابــة‪ ،‬وأشــهد هلل بــأن‬\n‫األرض محــل النــزاع الواقعــة يف شــمال اجللــه التــي يدعــي بهــا املدعــي‬\n‫كانــت ملــكا ل‪ ...................‬ثــم باعهــا علــى ‪ ..................‬ثــم ‪.............‬‬\n‫علــى ‪ ،.................‬واألرض محاطــة بعقــوم وشــبوك‪ ،‬هــذا مــا لــدي مــن‬\n‫شــهادة‪ ،‬وأشــهد هلل بهــا‪ .‬وقــال الشــاهد الثانــي إننــي مــن مواليــد عــام‬\n‫‪1382‬هـ ـ وأســكن يف الريــاض‪ ،‬وأعمــل يف جامعــة امللــك ســعود‪ ،‬وال‬\n‫تربطنــي باملدعــي وال املدعــى عليــه أي عالقــة قرابــة‪ ،‬وأشــهد اهلل بــأن‬\n‫األرض محــل النــزاع الواقعــة يف شــمال اجللــه التــي يدعــي بهــا املدعــي‬\n‫كانــت ملــك ل‪ ....................‬ثــم باعهــا علــى ‪ .................‬ثــم ‪...............‬‬\n‫باعهــا علــى ‪ ،..................‬واألرض محاطــة بعقــوم وشــبوك‪ ،‬هــذا مــا‬\n‫لــدي مــن شــهادة‪ ،‬وأشــهد هلل بهــا‪ ،‬هــذا مــا لــدي‪ .‬وبعــرض الشــهود‬\n‫ومــا جــاء يف شــهادتهم علــى املدعــي أصالــة‪ ،‬قــال‪ :‬أمــا الشــاهد األول‬\n‫عــدل ثقــة‪ ،‬وأمــا الثانــي فــا أعرفــه ومــا جــاء يف شــهادتهم صحيــح إال‬\n‫أن العقــوم والشــبوك علــى أرض أكبــر مســاحة مــن مشــمول الصــك‪،‬‬\n‫هــذا مــا لــدي‪ .‬وبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة وملــا رواه جابــر‬\n‫رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وســلم قضــى بالشــفعة يف‬\n‫كل مــا لــم يقســم فــإذا وقعــت احلــدود وصرفــت الطــرق فــا شــفعة‪،‬‬\n‫ومبــا أن أهــل العلــم رحمهــم اهلل تعالــى قــرروا أن الشــفعة إمنــا تثبــت‬\n‫للجــار فيمــا إذا كان شــريكان يف حقــوق امللــك مــن طريــق أو مســيل‬\n\n\n                                                                                               ‫‪356‬‬\n\f      ‫وغيرهــا (املبــدع ‪ )206/5‬وقــد صــدر قــرار هيئــة كبــار العلمــاء رقــم‪:‬‬\n      ‫‪ 44‬يف ‪1396/4/13‬ه ـ املتضمن أن الشــفعة تثبت بالشــركة يف املرافق‬\n      ‫اخلاصــة كالبئــر والطريــق واملســيل ومبــا أن املدعــي لــم يذكــر وجــود‬\n      ‫اشــتراك بينــه وبــن املدعــى عليــه إال الطريــق املذكــور‪ ،‬وقــد قــرر أنــه‬\n      ‫طريــق عــام وقــد شــهد الشــاهدان أن األرض محيــوزة ومعقمــة؛ لذلــك‬\n      ‫كلــه فقــد صرفــت النظــر عــن دعــوى املدعــي لعــدم اســتحقاقه الشــفعة‬\n      ‫كمــا صرفــت النظــر عــن طلبــات املدعــى عليــه وكالــة املذكــورة‬\n      ‫وأفهمتــه بــأن لــه التقــدم بهــا بعــد اكتســاب احلكــم القطعيــة وبجميــع‬\n      ‫مــا تقــدم حكمــت‪ ،‬وبعــرض احلكــم عليهمــا‪ ،‬قــرر املدعــى عليهــا‬\n      ‫أصالــة القناعــة‪ ،‬وأمــا املدعــي أصالــة فقــرر عــدم القناعــة‪ ،‬وطلــب‬\n      ‫رفــع املعاملــة إلــى محكمــة االســتئناف‪ ،‬فأجبتــه إلــى طلبــه وأفهمتــه‬\n      ‫بأنــه ســوف يســلم صــورة مــن نســخة احلكــم يــوم االثنــن املوافــق‬\n      ‫‪1434/3/9‬هـ ـ وأن لــه مهلــة ثالثــن يومــا مــن تاريــخ االســتالم لتقــدمي‬\n      ‫الئحتــه االعتراضيــة‪ ،‬فــإذا انتهــت املهلــة ولــم يتقــدم بالئحتــه ســقط‬\n      ‫حقــه يف االعتــراض وأصبــح احلكــم نافــذا وبــه ختمــت اجللســة يف متــام‬\n      ‫الســاعة ‪ 12 : 15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                     ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/4‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪ 1434/5/14‬ه ـ‬\n      ‫افتتحــت ‪ :02 15‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫باخلطــاب رقــم ‪ 34956370‬يف ‪1434/5/4‬ه ـ وبرفقهــا القــرار الصــادر‬\n      ‫مــن الدائــرة الثالثــة لتمييــز القضايــا احلقوقيــة يف محكمــة االســتئناف‬\n      ‫رقم ‪ 34198915‬يف ‪1434/4/27‬هـ واملتضمن وبدراســة الصك وصورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة واوراق املعاملــة تقــرر الدائــرة املصادقــة‬\n\n\n‫‪357‬‬\n\f‫علــى احلكــم واهلل املوفــق أه ـ ‪ ،‬وعليــه جــرى التهميــش مبوجبــه ‪ ،‬وبــه‬\n‫ختمــت اجللســة يف متــام الســاعة ‪ 02:20‬وبــاهلل التوفيــق ‪،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد‬\n‫باخلطــاب رقــم ‪ 33133609‬وتاريــخ ‪1434/4/14‬ه ـ املرفــق بهــا الصــك‬\n‫رقــم ‪ 3457090‬وتاريــخ ‪1434/3/7‬ه ـ الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ...................... /‬املتضمــن احلكــم يف الدعــوى‬\n‫املقامــة مــن ‪........................ /‬ضــد ‪ ........................ /‬علــى النحــو‬\n‫املوضــح بالصــك واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫تقــرر الدائــرة املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                          ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪358‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":343,"source_page_end":358,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"366f1f3dc75012f9d182f41758f80b337b7b24697025cbde79d645c19a4ae757","normalized_text_hash":"483ae3a6198f99ba0ede51060187356643208ec25b976effc0c8a810c08a7711","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p343-3457090"}]$archive_payload$::jsonb) AS x LIMIT 25
